/* Индекс шаблонов для каталога и поиска. Собирается tools/sync_templates.js, вручную не править. */
window.TEMPLATE_INDEX = [
{"id":"services","title":"Договор возмездного оказания услуг","category":"Договоры","summary":"Услуги для гражданина или бизнеса. Условия меняются, если заказчик является потребителем.","notes":["Опишите услугу конкретно: предмет является существенным условием договора.","Если исполнитель является гражданином, проверьте налоговые последствия и риск признания отношений трудовыми.","Для отдельных видов услуг могут действовать особые правила. Шаблон описывает общий случай."],"basis":[{"lawId":"GK","number":"779"},{"lawId":"GK","number":"780"},{"lawId":"GK","number":"781"},{"lawId":"GK","number":"782"},{"lawId":"GK","number":"783"},{"lawId":"ZOZPP","number":"16"},{"lawId":"ZOZPP","number":"17"}],"reviewed":false,"file":"contracts"},
{"id":"vehicle","title":"Договор купли-продажи автомобиля","category":"Договоры","summary":"Продажа транспортного средства между гражданами.","notes":["Сверьте VIN и номера с документами и самим автомобилем.","Проверьте залог, ограничения и розыск по официальным реестрам.","Срок обращения за регистрацией установлен законодательством о регистрации транспортных средств. Этого закона пока нет в базе, сверьте срок отдельно."],"basis":[{"lawId":"GK","number":"223"},{"lawId":"GK","number":"454"},{"lawId":"GK","number":"456"},{"lawId":"GK","number":"460"},{"lawId":"GK","number":"475"}],"reviewed":false,"file":"contracts"},
{"id":"loan","title":"Договор займа между гражданами","category":"Договоры","summary":"Денежный заем с процентами или без них. Деньги передаются при подписании.","notes":["Заем от гражданина считается заключенным с момента передачи денег, поэтому передачу стоит подтвердить распиской.","Проценты в два раза и более выше обычно взимаемых суд может уменьшить."],"basis":[{"lawId":"GK","number":"807"},{"lawId":"GK","number":"808"},{"lawId":"GK","number":"809"},{"lawId":"GK","number":"810"},{"lawId":"GK","number":"811"},{"lawId":"GK","number":"395"}],"reviewed":false,"file":"contracts"},
{"id":"lease","title":"Договор найма жилого помещения","category":"Договоры","summary":"Сдача квартиры или дома гражданину. Показывает, когда нужна регистрация.","notes":["Убедитесь по выписке из ЕГРН, что наймодатель является собственником или уполномочен собственником.","Нанимателем может быть только гражданин.","При сроке менее года к договору не применяются некоторые правила о найме, если договором не предусмотрено иное."],"basis":[{"lawId":"GK","number":"671"},{"lawId":"GK","number":"674"},{"lawId":"GK","number":"676"},{"lawId":"GK","number":"677"},{"lawId":"GK","number":"678"},{"lawId":"GK","number":"681"},{"lawId":"GK","number":"682"},{"lawId":"GK","number":"683"},{"lawId":"GK","number":"685"},{"lawId":"GK","number":"687"},{"lawId":"GK","number":"381.1"}],"reviewed":false,"file":"contracts"},
{"id":"work","title":"Договор подряда","category":"Договоры","summary":"Работа с результатом: ремонт, изготовление, монтаж. Учитывает бытовой подряд с гражданином.","notes":["Сроки начала и окончания работы нужно указать в договоре.","Для строительного подряда и работ, требующих лицензии или членства в СРО, есть особые правила. Шаблон описывает общий случай.","Без гарантийного срока требования по качеству можно предъявить за недостатки, обнаруженные в разумный срок, но в пределах двух лет."],"basis":[{"lawId":"GK","number":"702"},{"lawId":"GK","number":"703"},{"lawId":"GK","number":"704"},{"lawId":"GK","number":"708"},{"lawId":"GK","number":"711"},{"lawId":"GK","number":"715"},{"lawId":"GK","number":"717"},{"lawId":"GK","number":"720"},{"lawId":"GK","number":"721"},{"lawId":"GK","number":"722"},{"lawId":"GK","number":"723"},{"lawId":"GK","number":"724"},{"lawId":"GK","number":"730"},{"lawId":"ZOZPP","number":"32"}],"reviewed":false,"file":"contracts-more"},
{"id":"rent","title":"Договор аренды нежилого помещения","category":"Договоры","summary":"Офис, магазин или склад. Предупреждает о регистрации договора на срок от года.","notes":["Адрес, площадь и кадастровый номер должны определенно указывать на помещение: без этого договор не считается заключенным.","Размер арендной платы обязателен: без него договор аренды здания или сооружения считается незаключенным.","Статья 651 ГК РФ говорит о зданиях и сооружениях. Проверьте по актуальной судебной практике, как она применяется к вашему помещению.","Передача оформляется отдельным актом. Подойдет шаблон акта приема-передачи."],"basis":[{"lawId":"GK","number":"606"},{"lawId":"GK","number":"607"},{"lawId":"GK","number":"608"},{"lawId":"GK","number":"609"},{"lawId":"GK","number":"610"},{"lawId":"GK","number":"611"},{"lawId":"GK","number":"614"},{"lawId":"GK","number":"615"},{"lawId":"GK","number":"616"},{"lawId":"GK","number":"619"},{"lawId":"GK","number":"620"},{"lawId":"GK","number":"622"},{"lawId":"GK","number":"651"},{"lawId":"GK","number":"654"},{"lawId":"GK","number":"655"},{"lawId":"GK","number":"381.1"}],"reviewed":false,"file":"contracts-more"},
{"id":"gift","title":"Договор дарения вещи между гражданами","category":"Договоры","summary":"Безвозмездная передача движимого имущества. Для недвижимости не подходит.","notes":["Дарение недвижимости между гражданами подлежит нотариальному удостоверению. Этот шаблон для него не подходит.","Любая встречная передача или обязательство одаряемого лишают договор характера дарения.","Договор о передаче дара после смерти дарителя ничтожен: такие случаи решаются правилами о наследовании.","Имущество в совместной собственности можно дарить только с согласия всех участников."],"basis":[{"lawId":"GK","number":"572"},{"lawId":"GK","number":"573"},{"lawId":"GK","number":"574"},{"lawId":"GK","number":"575"},{"lawId":"GK","number":"576"},{"lawId":"GK","number":"578"}],"reviewed":false,"file":"contracts-more"},
{"id":"sale","title":"Договор купли-продажи вещи","category":"Договоры","summary":"Разовая продажа движимого имущества. Для автомобиля есть отдельный шаблон.","notes":["Шаблон не подходит для недвижимости, ценных бумаг и постоянных поставок.","Если продавец является предпринимателем, а покупатель берет товар для личных нужд, применяются правила о розничной продаже и защите прав потребителей."],"basis":[{"lawId":"GK","number":"223"},{"lawId":"GK","number":"454"},{"lawId":"GK","number":"456"},{"lawId":"GK","number":"460"},{"lawId":"GK","number":"469"},{"lawId":"GK","number":"475"},{"lawId":"GK","number":"486"}],"reviewed":false,"file":"contracts-more"},
{"id":"termination","title":"Соглашение о расторжении договора","category":"Соглашения и расписки","summary":"Расторжение договора по согласию сторон, с расчётами или без них.","notes":["Соглашение заключается в той же форме, что и договор. Если договор удостоверен нотариусом или зарегистрирован, проверьте, что требуется для соглашения.","Проверьте особые условия расторжения в самом договоре."],"basis":[{"lawId":"GK","number":"450"},{"lawId":"GK","number":"452"},{"lawId":"GK","number":"453"}],"reviewed":false,"file":"agreements"},
{"id":"receipt","title":"Расписка в получении займа","category":"Соглашения и расписки","summary":"Подтверждает передачу денег заемщику.","notes":["Расписка должна удостоверять передачу денег, а не только намерение их передать.","Без указания на беспроцентность заем больше 100 000 рублей считается процентным."],"basis":[{"lawId":"GK","number":"807"},{"lawId":"GK","number":"808"},{"lawId":"GK","number":"809"},{"lawId":"GK","number":"810"}],"reviewed":false,"file":"agreements"},
{"id":"completion","title":"Акт оказанных услуг или выполненных работ","category":"Акты","summary":"Подтверждает сдачу результата по договору. Можно записать замечания заказчика.","notes":["Заказчик, принявший работу без проверки, теряет право ссылаться на явные недостатки. Осмотрите результат до подписания.","Если есть замечания, запишите их в акте: на недостатки, обнаруженные при приемке, можно ссылаться, когда они в нем оговорены."],"basis":[{"lawId":"GK","number":"720"},{"lawId":"GK","number":"723"},{"lawId":"GK","number":"783"}],"reviewed":false,"file":"acts"},
{"id":"transfer","title":"Акт приема-передачи имущества","category":"Акты","summary":"Фиксирует передачу вещи и ее состояние по договору.","notes":["Опишите имущество так, чтобы его можно было однозначно определить.","Для зданий и сооружений передаточный документ обязателен, уклонение от подписи считается отказом от передачи или принятия."],"basis":[{"lawId":"GK","number":"223"},{"lawId":"GK","number":"456"},{"lawId":"GK","number":"655"}],"reviewed":false,"file":"acts"},
{"id":"power","title":"Доверенность от гражданина","category":"Доверенности","summary":"На представительство в суде или другие действия. Для суда перечисляет особые полномочия.","notes":["Доверенность без даты ничтожна. Если срок не указан, она действует один год.","Сделки, требующие нотариальной формы, подача заявлений о регистрации прав и распоряжение зарегистрированными правами требуют нотариальной доверенности. Этот шаблон для них не подходит.","Для суда проверьте удостоверение доверенности: варианты перечислены в части 2 статьи 53 ГПК РФ."],"basis":[{"lawId":"GK","number":"185"},{"lawId":"GK","number":"185.1"},{"lawId":"GK","number":"186"},{"lawId":"GK","number":"187"},{"lawId":"GK","number":"188"},{"lawId":"GPK","number":"53"},{"lawId":"GPK","number":"54"}],"reviewed":false,"file":"powers"},
{"id":"claim","title":"Претензия о недостатках товара","category":"Претензии и уведомления","summary":"Требование покупателя вернуть деньги или снизить цену. Учитывает технически сложные товары.","notes":["Шаблон подходит для товара с недостатками. Возврат исправного товара регулируется другими статьями.","Перечень технически сложных товаров утверждён Правительством. Проверьте, входит ли в него товар.","Сохраните доказательство вручения претензии: отметку продавца или почтовую квитанцию с описью."],"basis":[{"lawId":"ZOZPP","number":"13"},{"lawId":"ZOZPP","number":"15"},{"lawId":"ZOZPP","number":"18"},{"lawId":"ZOZPP","number":"22"},{"lawId":"ZOZPP","number":"23"}],"reviewed":false,"file":"claims"},
{"id":"debt-claim","title":"Претензия об оплате долга","category":"Претензии и уведомления","summary":"Требование погасить денежный долг по договору до обращения в суд.","notes":["В спорах, подсудных арбитражному суду, взысканию долга обычно предшествует претензия: обращение возможно через тридцать календарных дней после ее направления, если договор или закон не устанавливают другое.","Сохраните доказательство отправки: опись вложения и квитанцию либо отметку о вручении.","Проценты по статье 395 ГК РФ рассчитываются по ключевой ставке за соответствующие периоды. Если договором предусмотрена неустойка, такие проценты по общему правилу не взыскиваются."],"basis":[{"lawId":"GK","number":"309"},{"lawId":"GK","number":"310"},{"lawId":"GK","number":"314"},{"lawId":"GK","number":"395"},{"lawId":"APK","number":"4"}],"reviewed":false,"file":"claims-more"},
{"id":"service-claim","title":"Претензия к исполнителю работ или услуг","category":"Претензии и уведомления","summary":"Потребитель заявляет о просрочке или недостатках. Считает сроки по закону.","notes":["Шаблон подходит гражданину, который заказал работу или услугу для личных нужд у предпринимателя или организации.","При недостатках отказ от договора возможен, если они существенные или не устранены в установленный срок.","Сохраните доказательство вручения претензии."],"basis":[{"lawId":"ZOZPP","number":"27"},{"lawId":"ZOZPP","number":"28"},{"lawId":"ZOZPP","number":"29"},{"lawId":"ZOZPP","number":"30"},{"lawId":"ZOZPP","number":"31"},{"lawId":"ZOZPP","number":"13"},{"lawId":"ZOZPP","number":"15"}],"reviewed":false,"file":"claims-more"},
{"id":"refusal","title":"Уведомление об отказе от договора","category":"Претензии и уведомления","summary":"Односторонний отказ заказчика от договора услуг или подряда.","notes":["Договор прекращается с момента получения уведомления другой стороной, если иное не предусмотрено законом или договором. Сохраните доказательство вручения.","Заказчик услуг оплачивает фактически понесенные расходы исполнителя. Заказчик по подряду оплачивает выполненную часть и возмещает убытки в пределах статьи 717 ГК РФ.","Проверьте, нет ли в договоре особого порядка отказа."],"basis":[{"lawId":"GK","number":"450.1"},{"lawId":"GK","number":"782"},{"lawId":"GK","number":"717"},{"lawId":"ZOZPP","number":"32"}],"reviewed":false,"file":"claims-more"},
{"id":"loan-suit","title":"Исковое заявление о взыскании долга по займу","category":"Суд","summary":"Иск гражданина к гражданину. Считает цену иска и государственную пошлину.","notes":["Иск предъявляется по месту жительства ответчика, если договором не определено иное.","Проценты по статье 395 ГК РФ считаются по ключевой ставке за соответствующие периоды. Приложите расчет, подписанный истцом.","Пошлина рассчитана по шкале статьи 333.19 НК РФ. Перед оплатой проверьте сумму и льготы по статье 333.36 НК РФ.","При цене до 500 000 рублей и письменном договоре подумайте о судебном приказе: он быстрее и дешевле, но отменяется по возражению должника."],"basis":[{"lawId":"GPK","number":"131"},{"lawId":"GPK","number":"132"},{"lawId":"GPK","number":"23"},{"lawId":"GPK","number":"24"},{"lawId":"GPK","number":"28"},{"lawId":"GK","number":"807"},{"lawId":"GK","number":"810"},{"lawId":"GK","number":"811"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"court"},
{"id":"court-order","title":"Заявление о вынесении судебного приказа","category":"Суд","summary":"Взыскание долга до 500 000 рублей по письменной сделке. Считает пошлину.","notes":["К заявлению нужно приложить документ об уплате пошлины и уведомление о вручении или иные документы о направлении должнику копии заявления и приложений.","Суд откажет, если из документов усматривается спор о праве или должник находится вне России.","Судья выносит приказ в течение десяти дней без вызова сторон. Должник может подать возражения, и тогда приказ отменяется."],"basis":[{"lawId":"GPK","number":"121"},{"lawId":"GPK","number":"122"},{"lawId":"GPK","number":"123"},{"lawId":"GPK","number":"124"},{"lawId":"GPK","number":"125"},{"lawId":"GPK","number":"126"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"court"},
{"id":"order-objection","title":"Возражения относительно судебного приказа","category":"Суд","summary":"Должник просит отменить приказ. Проверяет десятидневный срок.","notes":["Срок на возражения составляет десять дней со дня получения приказа.","При поступлении возражений в срок судья отменяет приказ. Причины несогласия можно указать, но закон этого условием не называет.","Если срок пропущен, нужно обосновать невозможность подать возражения вовремя по независящим причинам."],"basis":[{"lawId":"GPK","number":"128"},{"lawId":"GPK","number":"129"},{"lawId":"GPK","number":"112"}],"reviewed":false,"file":"court"},
{"id":"divorce","title":"Исковое заявление о расторжении брака","category":"Суд","summary":"Для развода через суд без спора о детях. Пошлина 5 000 рублей.","notes":["Через суд брак расторгается при общих несовершеннолетних детях, при отсутствии согласия одного из супругов или если супруг уклоняется от расторжения в ЗАГСе.","При спорах о детях дело подсудно районному суду. Этот шаблон такие споры не охватывает.","Иск подается по месту жительства ответчика, а по месту жительства истца, если с ним живет несовершеннолетний или выезд затруднен по здоровью.","При взаимном согласии суд расторгает брак не ранее чем через месяц после подачи заявления."],"basis":[{"lawId":"SK","number":"21"},{"lawId":"SK","number":"22"},{"lawId":"SK","number":"23"},{"lawId":"SK","number":"24"},{"lawId":"GPK","number":"23"},{"lawId":"GPK","number":"28"},{"lawId":"GPK","number":"29"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"court"},
{"id":"restore-term","title":"Заявление о восстановлении процессуального срока","category":"Суд","summary":"Для пропущенного срока по уважительной причине. Подается вместе с пропущенным действием.","notes":["Одновременно с заявлением нужно совершить пропущенное действие: подать жалобу или документы.","Для апелляционных, кассационных и надзорных жалоб действует особый порядок: проверьте его по статье, указанной в части 6 статьи 112 ГПК РФ.","Срок кассационной и надзорной жалобы восстанавливают только в исключительных случаях."],"basis":[{"lawId":"GPK","number":"112"}],"reviewed":false,"file":"court"},
{"id":"resignation","title":"Заявление об увольнении по собственному желанию","category":"Трудовые отношения","summary":"Считает срок предупреждения и учитывает увольнение с указанной работником даты.","notes":["Срок предупреждения начинается на следующий день после получения заявления работодателем. Сохраните доказательство подачи.","До истечения срока заявление можно отозвать, если на место работника не приглашен в письменной форме другой работник, которому нельзя отказать в договоре.","Для отдельных категорий работников федеральным законом может быть установлен другой срок предупреждения."],"basis":[{"lawId":"TK","number":"80"},{"lawId":"TK","number":"84.1"},{"lawId":"TK","number":"140"}],"reviewed":false,"file":"labor"},
{"id":"employment-termination","title":"Соглашение о расторжении трудового договора","category":"Трудовые отношения","summary":"Увольнение по соглашению сторон, с компенсацией или без нее.","notes":["Прекращение договора оформляется приказом, с которым работника знакомят под роспись.","Для отдельных категорий выплата компенсации ограничена законом. Проверьте это, если работник является руководителем или работает в государственной организации."],"basis":[{"lawId":"TK","number":"77"},{"lawId":"TK","number":"78"},{"lawId":"TK","number":"84.1"},{"lawId":"TK","number":"140"}],"reviewed":false,"file":"labor"},
{"id":"supply","title":"Договор поставки","category":"Договоры","summary":"Поставка товара между предпринимателями. Приемка, качество, оплата и претензионный порядок.","notes":["Поставщиком может быть только предприниматель, а товар покупается не для личных нужд.","Наименование и количество товара являются существенными условиями. Для нескольких позиций составьте спецификацию.","При неоднократном нарушении сроков поставки или оплаты нарушение предполагается существенным, и договор можно расторгнуть в одностороннем порядке."],"basis":[{"lawId":"GK","number":"506"},{"lawId":"GK","number":"508"},{"lawId":"GK","number":"509"},{"lawId":"GK","number":"510"},{"lawId":"GK","number":"513"},{"lawId":"GK","number":"516"},{"lawId":"GK","number":"518"},{"lawId":"GK","number":"521"},{"lawId":"GK","number":"523"},{"lawId":"APK","number":"4"}],"reviewed":false,"file":"additional"},
{"id":"employment","title":"Трудовой договор","category":"Трудовые отношения","summary":"Прием работника: обязательные условия статьи 57 ТК РФ, испытание, срочный договор.","notes":["До подписания договора работника нужно ознакомить под роспись с правилами внутреннего трудового распорядка и другими локальными актами.","Месячная зарплата при полной норме времени не может быть ниже МРОТ. Его размер устанавливается федеральным законом: проверьте актуальное значение.","Условия труда на рабочем месте указываются по результатам специальной оценки условий труда."],"basis":[{"lawId":"TK","number":"56"},{"lawId":"TK","number":"57"},{"lawId":"TK","number":"58"},{"lawId":"TK","number":"59"},{"lawId":"TK","number":"67"},{"lawId":"TK","number":"68"},{"lawId":"TK","number":"70"},{"lawId":"TK","number":"91"},{"lawId":"TK","number":"115"},{"lawId":"TK","number":"133"},{"lawId":"TK","number":"136"}],"reviewed":false,"file":"additional"},
{"id":"consumer-suit","title":"Исковое заявление о защите прав потребителя","category":"Суд","summary":"Возврат денег за товар с недостатками, неустойка, моральный вред и штраф. Считает неустойку и цену иска.","notes":["Иск можно подать по месту жительства или пребывания истца, по месту заключения или исполнения договора либо по адресу ответчика.","Истцы по искам о защите прав потребителей освобождены от пошлины при цене иска до 1 000 000 рублей.","Неустойка считается со дня, следующего за последним днем десятидневного срока на ответ. Сверьте даты с почтовыми документами.","Суд может уменьшить неустойку по статье 333 ГК РФ."],"basis":[{"lawId":"ZOZPP","number":"13"},{"lawId":"ZOZPP","number":"15"},{"lawId":"ZOZPP","number":"17"},{"lawId":"ZOZPP","number":"18"},{"lawId":"ZOZPP","number":"22"},{"lawId":"ZOZPP","number":"23"},{"lawId":"GPK","number":"23"},{"lawId":"GPK","number":"29"},{"lawId":"GPK","number":"131"},{"lawId":"GPK","number":"132"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"additional"},
{"id":"appeal","title":"Апелляционная жалоба","category":"Суд","summary":"На решение суда общей юрисдикции. Проверяет месячный срок и считает пошлину.","notes":["Жалоба подается через суд, принявший решение, в течение месяца со дня принятия решения в окончательной форме.","Нельзя заявлять требования, которые не заявлялись в первой инстанции. Новые доказательства допускаются, только если обосновано, почему их нельзя было представить раньше.","К жалобе прилагаются документ об уплате пошлины и доказательства направления копий другим лицам, участвующим в деле.","Если срок пропущен, заявление о его восстановлении подается в суд апелляционной инстанции вместе с жалобой."],"basis":[{"lawId":"GPK","number":"320"},{"lawId":"GPK","number":"321"},{"lawId":"GPK","number":"322"},{"lawId":"GPK","number":"323"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"additional"},
{"id":"alimony-suit","title":"Исковое заявление о взыскании алиментов на детей","category":"Суд","summary":"Алименты на несовершеннолетних детей в доле от заработка или в твёрдой сумме. Пошлину платить не нужно.","notes":["Если отцовство не оспаривается и других заинтересованных лиц нет, алименты на детей можно взыскать быстрее через судебный приказ: для этого есть шаблон заявления о вынесении судебного приказа.","Иск можно подать по месту жительства ответчика или по своему месту жительства.","Истец по иску о взыскании алиментов освобожден от государственной пошлины.","Алименты присуждаются с момента обращения в суд. За прошлое время, не более трех лет, их взыскивают, только если вы пытались получить средства, а ответчик уклонялся от уплаты."],"basis":[{"lawId":"SK","number":"80"},{"lawId":"SK","number":"81"},{"lawId":"SK","number":"83"},{"lawId":"SK","number":"107"},{"lawId":"SK","number":"117"},{"lawId":"GPK","number":"29"},{"lawId":"GPK","number":"122"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"more"},
{"id":"enforcement","title":"Заявление о возбуждении исполнительного производства","category":"Суд","summary":"Для передачи исполнительного листа или судебного приказа приставам. С реквизитами счёта для перечисления денег.","notes":["Заявление подается вместе с подлинником исполнительного документа в отделение судебных приставов по месту жительства или нахождения имущества должника.","Исполнительный лист обычно можно предъявить в течение трех лет со дня вступления судебного акта в законную силу, судебный приказ — в течение трех лет со дня его выдачи.","Если исполнительный документ подписывает представитель, к заявлению прикладывается доверенность."],"basis":[{"lawId":"FZ229","number":"30"},{"lawId":"FZ229","number":"21"},{"lawId":"FZ229","number":"33"},{"lawId":"FZ229","number":"13"}],"reviewed":false,"file":"more"},
{"id":"claim-objection","title":"Возражения на исковое заявление","category":"Суд","summary":"Письменный ответ ответчика на иск: с чем вы не согласны и чем это подтверждается.","notes":["Возражения передаются суду и истцу при подготовке дела. Приложите копии для истца или документы о направлении ему возражений.","Каждое обстоятельство, на которое вы ссылаетесь, нужно подтвердить доказательствами. Если получить доказательство самостоятельно нельзя, попросите суд истребовать его.","Ссылайтесь на конкретные статьи закона. Проверить, не утратили ли они силу, можно в разделе «Проверка»."],"basis":[{"lawId":"GPK","number":"149"},{"lawId":"GPK","number":"56"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"more"},
{"id":"vacation","title":"Заявление о предоставлении отпуска","category":"Трудовые отношения","summary":"Ежегодный оплачиваемый отпуск или отпуск без сохранения заработной платы.","notes":["Ежегодный отпуск предоставляется по графику отпусков. Отпуск в другие даты работодатель предоставлять не обязан, если закон не дает работнику такого права.","За первый год работы право на отпуск возникает через шесть месяцев непрерывной работы, а некоторым работникам предоставляется и раньше.","Отпуск без сохранения заработной платы предоставляется по соглашению с работодателем. Отдельным работникам, например при рождении ребенка, регистрации брака или смерти близкого родственника, работодатель обязан его предоставить в пределах установленного срока."],"basis":[{"lawId":"TK","number":"114"},{"lawId":"TK","number":"115"},{"lawId":"TK","number":"122"},{"lawId":"TK","number":"123"},{"lawId":"TK","number":"128"}],"reviewed":false,"file":"more"},
{"id":"bailiff-complaint","title":"Жалоба на судебного пристава-исполнителя","category":"Суд","summary":"На бездействие, действие или постановление пристава, старшему судебному приставу. Срок — десять дней.","notes":["Жалоба на судебного пристава-исполнителя подается старшему судебному приставу отделения, в котором ведется исполнительное производство. Её можно подать и через Госуслуги.","Срок — десять дней со дня вынесения постановления, совершения действия или установления факта бездействия. Если вас не известили, срок считается со дня, когда вы узнали или должны были узнать о нарушении.","Жалобу должны рассмотреть в течение десяти дней со дня поступления. Те же действия можно оспорить в суде."],"basis":[{"lawId":"FZ229","number":"121"},{"lawId":"FZ229","number":"122"},{"lawId":"FZ229","number":"123"},{"lawId":"FZ229","number":"124"},{"lawId":"FZ229","number":"126"}],"reviewed":false,"file":"extra"},
{"id":"writ-request","title":"Заявление о выдаче исполнительного листа","category":"Суд","summary":"После вступления решения в силу: получить лист на руки, по почте или направить его сразу приставам.","notes":["Исполнительный лист выдается после вступления решения в законную силу, кроме случаев немедленного исполнения.","По решению о взыскании денег в бюджет и в некоторых других случаях суд направляет лист сам, без заявления.","Лист можно предъявить к исполнению в течение трех лет со дня вступления решения в законную силу."],"basis":[{"lawId":"GPK","number":"428"},{"lawId":"GPK","number":"209"},{"lawId":"FZ229","number":"21"}],"reviewed":false,"file":"extra"},
{"id":"alimony-agreement","title":"Соглашение об уплате алиментов на детей","category":"Соглашения и расписки","summary":"Проект для нотариуса: размер, способ и сроки уплаты алиментов на несовершеннолетних детей.","notes":["Соглашение подлежит нотариальному удостоверению. Без него оно ничтожно. Этот текст — проект, который нотариус может изменить.","Удостоверенное нотариусом соглашение имеет силу исполнительного листа: при неуплате его можно сразу передать приставам.","Алименты на несовершеннолетних детей по соглашению не могут быть меньше, чем суд взыскал бы по закону: четверть дохода на одного ребенка, треть на двоих, половина на трех и более."],"basis":[{"lawId":"SK","number":"99"},{"lawId":"SK","number":"100"},{"lawId":"SK","number":"103"},{"lawId":"SK","number":"104"},{"lawId":"SK","number":"105"},{"lawId":"SK","number":"115"},{"lawId":"SK","number":"81"}],"reviewed":false,"file":"extra"},
{"id":"free-use","title":"Договор безвозмездного пользования вещью","category":"Договоры","summary":"Ссуда между гражданами: передать вещь на время бесплатно, с возвратом в том же состоянии.","notes":["Передать вещь в безвозмездное пользование может собственник или лицо, которому это разрешено законом или собственником.","Ссудополучатель сам содержит вещь и делает ее ремонт, если договор не говорит иное.","Договор без срока каждая сторона может расторгнуть, предупредив другую за месяц.","Для жилья и других помещений подходит этот же договор, но проверьте права собственника и согласие других собственников."],"basis":[{"lawId":"GK","number":"689"},{"lawId":"GK","number":"690"},{"lawId":"GK","number":"695"},{"lawId":"GK","number":"696"},{"lawId":"GK","number":"697"},{"lawId":"GK","number":"698"},{"lawId":"GK","number":"699"}],"reviewed":false,"file":"extra"},
{"id":"case-materials","title":"Заявление об ознакомлении с материалами дела","category":"Суд","summary":"Чтобы прочитать дело и сфотографировать документы до заседания или после решения.","notes":["Лица, участвующие в деле, вправе знакомиться с материалами дела, делать выписки и снимать копии, в том числе фотографировать.","Представитель прикладывает доверенность, если она еще не приобщена к делу.","Многие суды принимают такое заявление через электронную приемную или ГАС «Правосудие»."],"basis":[{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"extra"},
{"id":"ddu-penalty-suit","title":"Исковое заявление о взыскании неустойки по договору долевого участия","category":"Суд","summary":"Если застройщик опоздал с передачей квартиры. Считает неустойку и пошлину, просит штраф и моральный вред.","notes":["Неустойка — одна трехсотая ставки рефинансирования (ключевой ставки) Банка России, действовавшей на день, когда квартиру должны были передать, от цены договора за каждый день просрочки. Гражданину она уплачивается в двойном размере.","В отдельные периоды начисление неустойки по договорам долевого участия приостанавливалось постановлениями Правительства. Проверьте, не попадает ли просрочка на такие периоды, и укажите эти дни в поле «Дни, за которые неустойка не начисляется».","Штраф 5 % от присужденной суммы суд взыскивает, если застройщик не удовлетворил требования добровольно, поэтому сначала направьте ему претензию.","Иск можно подать по своему месту жительства. При цене иска до 100 000 рублей он подается мировому судье, выше — в районный суд."],"basis":[{"lawId":"FZ214","number":"6"},{"lawId":"FZ214","number":"10"},{"lawId":"FZ214","number":"8"},{"lawId":"GPK","number":"29"},{"lawId":"GPK","number":"23"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"practice"},
{"id":"settlement","title":"Мировое соглашение","category":"Суд","summary":"Чтобы закончить спор миром: сумма, срок, отказ от остальных требований и судебные расходы.","notes":["Мировое соглашение утверждает суд. После утверждения производство по делу прекращается, и повторно обратиться в суд с тем же спором нельзя.","Соглашение подписывают сами стороны или представители, у которых в доверенности специально оговорено право заключить мировое соглашение.","Экземпляров нужно на один больше, чем сторон: один остается в деле.","Если соглашение не исполнят добровольно, суд выдаст исполнительный лист."],"basis":[{"lawId":"GPK","number":"39"},{"lawId":"GPK","number":"101"},{"lawId":"GPK","number":"153.8"},{"lawId":"GPK","number":"153.9"},{"lawId":"GPK","number":"153.10"},{"lawId":"GPK","number":"153.11"},{"lawId":"GPK","number":"173"},{"lawId":"GPK","number":"221"}],"reviewed":false,"file":"practice"},
{"id":"decision-copy","title":"Заявление о выдаче копии решения суда","category":"Суд","summary":"Копия решения, определения или приговора: получить лично или по почте, в том числе с отметкой о вступлении в силу.","notes":["Лицам, участвующим в деле, копии решения вручаются или направляются в течение пяти дней после его составления. Если копию не получили, ее можно запросить.","Копия с отметкой о вступлении в законную силу нужна, например, для регистрации права, ЗАГСа или банка.","Многие суды принимают такие заявления через электронную приемную или ГАС «Правосудие»."],"basis":[{"lawId":"GPK","number":"214"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"practice"},
{"id":"repayment-receipt","title":"Расписка в получении возврата долга","category":"Соглашения и расписки","summary":"Кредитор подтверждает, что долг возвращен полностью или частично. Защищает должника от повторного требования.","notes":["Кредитор обязан выдать расписку по требованию должника. Если он отказывается, должник вправе задержать исполнение.","При полном возврате кредитор возвращает долговой документ, например расписку о займе. Если вернуть его нельзя, это указывается в расписке.","Расписку пишет и подписывает кредитор. Лучше, чтобы он написал ее от руки."],"basis":[{"lawId":"GK","number":"408"},{"lawId":"GK","number":"810"}],"reviewed":false,"file":"practice"},
{"id":"storage","title":"Договор хранения вещи между гражданами","category":"Договоры","summary":"Оставить вещь на хранение знакомому или соседу: бесплатно или за плату, на срок или до востребования.","notes":["Между гражданами договор хранения заключается письменно, если стоимость вещи больше 10 000 рублей.","Поклажедатель может забрать вещь в любой момент, даже до окончания срока хранения.","Хранитель отвечает за утрату, недостачу и повреждение вещи по общим правилам статьи 401 ГК РФ. Если срок хранения кончился, а поклажедатель вещь не забрал, хранитель отвечает только за умысел и грубую неосторожность."],"basis":[{"lawId":"GK","number":"886"},{"lawId":"GK","number":"887"},{"lawId":"GK","number":"889"},{"lawId":"GK","number":"891"},{"lawId":"GK","number":"896"},{"lawId":"GK","number":"899"},{"lawId":"GK","number":"900"},{"lawId":"GK","number":"901"},{"lawId":"GK","number":"904"}],"reviewed":false,"file":"practice"},
{"id":"alimony-order","title":"Заявление о вынесении судебного приказа о взыскании алиментов","category":"Суд","summary":"Самый быстрый способ взыскать алименты на детей в доле от заработка, без судебного заседания. Пошлину платить не нужно.","notes":["Судебный приказ выдается, если отцовство не оспаривается и не нужно привлекать других лиц. Алименты в твердой сумме приказом не взыскиваются — для этого подается иск.","Заявление подается мировому судье по месту жительства должника или по своему месту жительства.","Должник может отменить приказ, подав возражения в течение десяти дней. Тогда алименты взыскиваются в исковом порядке.","Должнику нужно направить копию заявления и приложить к заявлению подтверждение отправки."],"basis":[{"lawId":"GPK","number":"122"},{"lawId":"GPK","number":"124"},{"lawId":"GPK","number":"29"},{"lawId":"SK","number":"80"},{"lawId":"SK","number":"81"},{"lawId":"SK","number":"107"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"family-labor"},
{"id":"property-division","title":"Исковое заявление о разделе общего имущества супругов","category":"Суд","summary":"Раздел нажитого в браке имущества в равных долях: кому что передается и какая компенсация. Считает пошлину.","notes":["Имущество, нажитое в браке, по общему правилу делится поровну, независимо от того, на кого из супругов оно оформлено. Имущество, полученное одним из супругов в дар или по наследству, разделу не подлежит.","После расторжения брака раздел можно требовать в течение трех лет. Срок считается со дня, когда супруг узнал или должен был узнать о нарушении своего права.","При цене иска до 50 000 рублей дело рассматривает мировой судья, выше — районный суд. Иск о разделе недвижимости подается по месту ее нахождения.","Цена иска — стоимость имущества и компенсации, которые вы просите передать вам. Подтвердите стоимость отчетом оценщика или другими документами."],"basis":[{"lawId":"SK","number":"34"},{"lawId":"SK","number":"36"},{"lawId":"SK","number":"38"},{"lawId":"SK","number":"39"},{"lawId":"GPK","number":"23"},{"lawId":"GPK","number":"24"},{"lawId":"GPK","number":"30"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"family-labor"},
{"id":"work-documents","title":"Заявление о выдаче документов, связанных с работой","category":"Трудовые отношения","summary":"Копии приказов, справки о зарплате и стаже. Работодатель обязан выдать их бесплатно за три рабочих дня.","notes":["Работодатель обязан выдать копии документов не позднее трех рабочих дней со дня подачи заявления. Копии заверяются и выдаются бесплатно.","Подайте заявление в двух экземплярах и попросите поставить отметку о получении на втором.","Если документы не выдали, можно пожаловаться в трудовую инспекцию: для этого есть отдельный шаблон."],"basis":[{"lawId":"TK","number":"62"},{"lawId":"TK","number":"66.1"},{"lawId":"TK","number":"84.1"}],"reviewed":false,"file":"family-labor"},
{"id":"labor-complaint","title":"Жалоба в трудовую инспекцию","category":"Трудовые отношения","summary":"На невыплату зарплаты, незаконное увольнение, невыдачу документов и другие нарушения работодателя.","notes":["Жалоба подается в государственную инспекцию труда в субъекте РФ по месту работы. Ее можно подать и через сайт «Онлайнинспекция.рф» или Госуслуги.","Инспектор обязан сохранить в тайне, от кого поступила жалоба, если вы об этом попросите.","Если спор уже рассматривает суд или комиссия по трудовым спорам, инспекция его не рассматривает.","Приложите копии документов, которые подтверждают нарушение: трудового договора, расчетных листков, переписки."],"basis":[{"lawId":"TK","number":"352"},{"lawId":"TK","number":"356"},{"lawId":"TK","number":"357"},{"lawId":"TK","number":"358"}],"reviewed":false,"file":"family-labor"},
{"id":"deferral","title":"Заявление об отсрочке или рассрочке исполнения решения суда","category":"Суд","summary":"Для должника, который не может заплатить сразу: перенести срок или платить частями.","notes":["Заявление подается в суд, который рассмотрел дело, или в суд по месту исполнения решения.","Суд учитывает имущественное положение сторон и интересы взыскателя. Подтвердите доходы, расходы и обстоятельства документами: справками о доходах, свидетельствами о рождении детей, медицинскими документами.","Предложите реальный график: суд вряд ли согласится на рассрочку на многие годы."],"basis":[{"lawId":"GPK","number":"203"},{"lawId":"GPK","number":"434"}],"reviewed":false,"file":"family-labor"},
{"id":"wage-suit","title":"Исковое заявление о взыскании заработной платы","category":"Трудовые отношения","summary":"Невыплаченная зарплата или расчет при увольнении с компенсацией за задержку. Пошлину платить не нужно.","notes":["Иск о невыплаченной зарплате можно подать в течение года со дня, когда ее должны были выплатить.","Работник освобожден от пошлины. Иск можно подать по своему месту жительства.","Компенсация за задержку — не меньше 1/150 ключевой ставки Банка России от невыплаченной суммы за каждый день. Если ставка за период менялась, посчитайте компенсацию по частям и укажите итог.","Сначала можно пожаловаться в трудовую инспекцию — для этого есть отдельный шаблон. Иск и жалобу можно подать одновременно."],"basis":[{"lawId":"TK","number":"136"},{"lawId":"TK","number":"140"},{"lawId":"TK","number":"236"},{"lawId":"TK","number":"237"},{"lawId":"TK","number":"392"},{"lawId":"GPK","number":"29"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"consumer-work"},
{"id":"management-claim","title":"Претензия к управляющей компании","category":"Претензии и уведомления","summary":"Протечка, неработающий лифт, грязный подъезд, плохое отопление: требование устранить и пересчитать плату.","notes":["Управляющая организация отвечает перед собственниками за содержание общего имущества и качество коммунальных услуг.","Зафиксируйте нарушение: фото, видео, акт, подписанный соседями или представителем управляющей организации.","Претензию подайте в двух экземплярах и попросите отметку о получении или отправьте заказным письмом. Ее можно подать и через ГИС ЖКХ.","Если претензию не выполнят, можно обратиться в жилищную инспекцию или в суд."],"basis":[{"lawId":"JK","number":"161"},{"lawId":"JK","number":"162"},{"lawId":"ZOZPP","number":"29"}],"reviewed":false,"file":"consumer-work"},
{"id":"vehicle-lease","title":"Договор аренды автомобиля без экипажа","category":"Договоры","summary":"Сдать машину в аренду, чтобы арендатор сам управлял ею: плата, срок, ремонт, страховка и ответственность.","notes":["Договор заключается письменно независимо от срока. Регистрировать его не нужно.","Арендатор сам управляет машиной, ремонтирует ее и несет расходы на содержание и страхование, если договор не говорит иное.","За вред, причиненный машиной третьим лицам, отвечает арендатор. Проверьте, что он вписан в полис ОСАГО или полис без ограничений.","Машину передайте по акту с описанием состояния, пробега и комплектности."],"basis":[{"lawId":"GK","number":"642"},{"lawId":"GK","number":"643"},{"lawId":"GK","number":"644"},{"lawId":"GK","number":"645"},{"lawId":"GK","number":"646"},{"lawId":"GK","number":"648"},{"lawId":"GK","number":"614"}],"reviewed":false,"file":"consumer-work"},
{"id":"prepayment-claim","title":"Претензия: оплаченный товар не передан в срок","category":"Претензии и уведомления","summary":"Мебель, техника или другой товар по предоплате не привезли: вернуть деньги или передать в новый срок, неустойка 0,5 % в день.","notes":["Деньги за непереданный товар продавец обязан вернуть в течение десяти дней со дня предъявления требования.","Неустойка — половина процента суммы предоплаты за каждый день просрочки, но не больше самой предоплаты. Она начисляется со дня, когда товар должны были передать.","Выберите одно требование: вернуть деньги или передать товар в новый срок. Если новый срок тоже нарушат, можно потребовать вернуть деньги."],"basis":[{"lawId":"ZOZPP","number":"23.1"}],"reviewed":false,"file":"consumer-work"},
{"id":"deposit","title":"Соглашение о задатке","category":"Соглашения и расписки","summary":"Перед покупкой квартиры, машины или другой вещи: задаток в обеспечение будущего договора, с последствиями по закону.","notes":["Соглашение о задатке заключается письменно независимо от суммы. Если форма не соблюдена, сумма может быть признана авансом и вернется в любом случае.","Если сделка сорвалась по вине покупателя, задаток остается у продавца. Если по вине продавца — он возвращает задаток в двойном размере.","Если обе стороны передумали или исполнение стало невозможным, задаток возвращается.","Опишите будущий договор подробно: предмет, цену и срок, до которого его нужно заключить."],"basis":[{"lawId":"GK","number":"380"},{"lawId":"GK","number":"381"},{"lawId":"GK","number":"429"}],"reviewed":false,"file":"consumer-work"},
{"id":"services-suit","title":"Исковое заявление к исполнителю работ или услуг","category":"Суд","summary":"Ремонт, пошив, химчистка, туристические и другие услуги: возврат денег, неустойка 3 % в день, моральный вред и штраф 50 %.","notes":["Перед иском направьте исполнителю претензию: без нее суд не взыщет штраф 50 % за неудовлетворение требований добровольно.","Неустойка — 3 % цены работы или услуги за каждый день просрочки, но не больше самой цены. Если цена в договоре не определена, — от общей цены заказа.","Иск можно подать по своему месту жительства. При цене иска до 100 000 рублей он подается мировому судье. Пошлину при цене до 1 000 000 рублей платить не нужно."],"basis":[{"lawId":"ZOZPP","number":"28"},{"lawId":"ZOZPP","number":"29"},{"lawId":"ZOZPP","number":"31"},{"lawId":"ZOZPP","number":"13"},{"lawId":"ZOZPP","number":"15"},{"lawId":"ZOZPP","number":"17"},{"lawId":"GPK","number":"29"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"services-court"},
{"id":"default-judgment","title":"Заявление об отмене заочного решения","category":"Суд","summary":"Если суд решил дело без вас: уважительная причина неявки и доводы, которые могут изменить решение. Срок — семь дней.","notes":["Заявление подается в суд, принявший заочное решение, в течение семи дней со дня, когда вам вручили его копию.","Нужно показать сразу две вещи: что вы не пришли по уважительной причине и не могли сообщить об этом суду, и что у вас есть доводы и доказательства, которые могут изменить решение.","Если суд откажет в отмене, решение можно обжаловать в апелляцию в течение месяца после такого отказа.","Приложите копии заявления по числу лиц, участвующих в деле."],"basis":[{"lawId":"GPK","number":"237"},{"lawId":"GPK","number":"238"},{"lawId":"GPK","number":"242"},{"lawId":"GPK","number":"112"}],"reviewed":false,"file":"services-court"},
{"id":"court-costs","title":"Заявление о взыскании судебных расходов","category":"Суд","summary":"После выигранного дела: расходы на представителя, экспертизу, почту и проезд. Подается в течение трех месяцев.","notes":["Заявление подается в суд первой инстанции в течение трех месяцев со дня вступления в силу последнего судебного акта по делу.","Расходы на представителя суд взыскивает в разумных пределах. Приложите договор, акт об оказанных услугах и документы об оплате.","Если иск удовлетворен частично, расходы возмещаются пропорционально удовлетворенной части требований."],"basis":[{"lawId":"GPK","number":"88"},{"lawId":"GPK","number":"94"},{"lawId":"GPK","number":"98"},{"lawId":"GPK","number":"100"},{"lawId":"GPK","number":"103.1"}],"reviewed":false,"file":"services-court"},
{"id":"writ-duplicate","title":"Заявление о выдаче дубликата исполнительного листа","category":"Суд","summary":"Если исполнительный лист или судебный приказ потерялся: у вас, на почте или у приставов.","notes":["Заявление подается в суд, принявший решение, до истечения срока предъявления листа к исполнению. Если лист потеряли приставы или другой исполнитель, — в течение месяца со дня, когда вы узнали об утрате.","Подтвердите утрату: справкой приставов, ответом почты, актом об утрате.","Суд рассматривает заявление в заседании в течение десяти дней."],"basis":[{"lawId":"GPK","number":"430"},{"lawId":"FZ229","number":"21"}],"reviewed":false,"file":"services-court"},
{"id":"vacation-postpone","title":"Заявление о переносе или продлении отпуска","category":"Трудовые отношения","summary":"Если заболели в отпуске, отпускные пришли поздно или о начале отпуска предупредили меньше чем за две недели.","notes":["При болезни во время отпуска работодатель обязан продлить отпуск или перенести его на другой срок с учетом пожеланий работника.","Если отпускные не выплатили за три дня до начала отпуска или о его начале предупредили позже чем за две недели, работодатель по заявлению работника обязан перенести отпуск на согласованный срок.","В остальных случаях перенос возможен только по договоренности с работодателем."],"basis":[{"lawId":"TK","number":"124"},{"lawId":"TK","number":"123"},{"lawId":"TK","number":"136"}],"reviewed":false,"file":"services-court"},
{"id":"flood-suit","title":"Исковое заявление о возмещении ущерба от залива квартиры","category":"Суд","summary":"Затопили соседи сверху или прорвало общий стояк: ущерб по оценке, расходы на оценку, пошлина. К соседу или к управляющей компании.","notes":["Сразу после залива вызовите представителя управляющей компании и составьте акт о заливе с причиной и описанием повреждений.","Если течь была в квартире соседа (кран, стиральная машина, внутриквартирная разводка), отвечает собственник этой квартиры. Если причина в общем имуществе (стояк до первого крана, крыша), — управляющая компания.","К управляющей компании применяется закон о защите прав потребителей: пошлину при цене иска до 1 000 000 рублей платить не нужно, можно требовать штраф 50 % и моральный вред. Сначала направьте ей претензию.","Стоимость ремонта подтвердите отчетом оценщика. Расходы на оценку тоже взыскиваются с виновника."],"basis":[{"lawId":"GK","number":"15"},{"lawId":"GK","number":"1064"},{"lawId":"JK","number":"30"},{"lawId":"JK","number":"161"},{"lawId":"ZOZPP","number":"13"},{"lawId":"ZOZPP","number":"15"},{"lawId":"NK","number":"333.19"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"property-misc"},
{"id":"expertise-motion","title":"Ходатайство о назначении судебной экспертизы","category":"Суд","summary":"Когда спор требует специальных знаний: вопросы эксперту, предлагаемые эксперты и кто оплачивает.","notes":["Сформулируйте вопросы так, чтобы на них можно было ответить однозначно. Окончательный круг вопросов определяет суд.","Можно предложить конкретное экспертное учреждение или эксперта. Приложите сведения о стоимости, сроке и квалификации.","Сторона, которая просит экспертизу, обычно вносит деньги на ее оплату на депозит суда. Уточните реквизиты в суде."],"basis":[{"lawId":"GPK","number":"79"},{"lawId":"GPK","number":"80"},{"lawId":"GPK","number":"96"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"property-misc"},
{"id":"subsistence-minimum","title":"Заявление о сохранении прожиточного минимума","category":"Суд","summary":"Если приставы списывают со счета всю зарплату: оставлять ежемесячно сумму не ниже прожиточного минимума. Приставам или в банк.","notes":["Заявление подается в отделение судебных приставов, где ведется производство, или прямо в банк, где открыт счет для зарплаты.","Приложите документы о доходе и его источниках: справку о доходах, выписку по счету.","Если у вас есть иждивенцы и прожиточного минимума не хватает, сохранить большую сумму можно только через суд.","Пособия на детей, алименты на детей и некоторые другие выплаты вообще не подлежат взысканию."],"basis":[{"lawId":"FZ229","number":"69"},{"lawId":"FZ229","number":"99"},{"lawId":"FZ229","number":"8"},{"lawId":"FZ229","number":"101"}],"reviewed":false,"file":"property-misc"},
{"id":"lease-notice","title":"Уведомление нанимателя о расторжении договора найма квартиры","category":"Претензии и уведомления","summary":"Съезжаете со съемной квартиры: письменное предупреждение наймодателя за три месяца, порядок возврата ключей и залога.","notes":["Наниматель вправе в любое время расторгнуть договор найма, письменно предупредив наймодателя за три месяца, если договор не дает более короткий срок. Проверьте свой договор.","Нужно согласие граждан, которые постоянно проживают вместе с нанимателем.","Передайте уведомление под подпись или отправьте заказным письмом с описью вложения. Квартиру сдайте по акту."],"basis":[{"lawId":"GK","number":"687"},{"lawId":"GK","number":"671"}],"reviewed":false,"file":"property-misc"},
{"id":"land-sale","title":"Договор купли-продажи земельного участка","category":"Договоры","summary":"Участок между гражданами: кадастровый номер, категория, разрешенное использование, обременения, расчеты и регистрация.","notes":["Продавать можно только участок, прошедший кадастровый учет. Сверьте данные с выпиской из ЕГРН.","Переход права собственности подлежит государственной регистрации в Росреестре. Нотариус нужен, если продается доля или участок принадлежит несовершеннолетнему.","Продавец обязан сообщить покупателю об известных ему обременениях и ограничениях использования участка.","Если участок в совместной собственности супругов, нужно нотариальное согласие второго супруга."],"basis":[{"lawId":"GK","number":"549"},{"lawId":"GK","number":"551"},{"lawId":"GK","number":"554"},{"lawId":"GK","number":"555"},{"lawId":"GK","number":"556"},{"lawId":"GK","number":"488"},{"lawId":"ZK","number":"37"}],"reviewed":false,"file":"property-misc"},
{"id":"building-contract","title":"Договор строительного подряда на дом","category":"Договоры","summary":"Построить дом или другой объект: сроки, цена по смете, материалы, этапы оплаты, приемка и гарантия.","notes":["Договор строительного подряда заключается на строительство дома и других объектов. Начальный и конечный сроки и цена работ или способ ее определения — обязательные условия.","Подрядчик строит по технической документации и смете. Приложите смету и проект, они становятся частью договора.","Если заказчик — гражданин, а подрядчик — предприниматель или организация, действует закон о защите прав потребителей. Неустойка за просрочку по закону — 3 % цены в день, договором ее уменьшить нельзя.","Заказчик может в любое время до сдачи результата отказаться от договора, оплатив подрядчику уже выполненную часть работы.","Проверьте у заказчика права на землю и разрешение на строительство, если оно нужно для вашего объекта."],"basis":[{"lawId":"GK","number":"702"},{"lawId":"GK","number":"708"},{"lawId":"GK","number":"709"},{"lawId":"GK","number":"715"},{"lawId":"GK","number":"717"},{"lawId":"GK","number":"720"},{"lawId":"GK","number":"740"},{"lawId":"GK","number":"743"},{"lawId":"GK","number":"745"},{"lawId":"ZOZPP","number":"28"}],"reviewed":false,"file":"inheritance-build"},
{"id":"inheritance-application","title":"Заявление нотариусу о принятии наследства","category":"Соглашения и расписки","summary":"Принять наследство и получить свидетельство о праве на наследство: по закону или по завещанию, лично или через нотариуса.","notes":["Заявление подается нотариусу по месту открытия наследства, то есть по последнему месту жительства умершего, в течение шести месяцев со дня смерти.","Заявление о принятии наследства и о выдаче свидетельства можно объединить в одном документе, как в этом шаблоне.","Если заявление передает нотариусу другой человек или оно отправлено по почте, подпись на нем должна быть засвидетельствована нотариусом.","Принятие части наследства означает принятие всего, что причитается наследнику, где бы оно ни находилось.","Если шесть месяцев пропущены, срок можно восстановить в суде или, если все остальные наследники письменно согласны, у нотариуса. Для суда есть отдельный шаблон."],"basis":[{"lawId":"GK","number":"1152"},{"lawId":"GK","number":"1153"},{"lawId":"GK","number":"1154"},{"lawId":"GK","number":"1142"},{"lawId":"NOTAR","number":"72"}],"reviewed":false,"file":"inheritance-build"},
{"id":"inheritance-restore","title":"Исковое заявление о восстановлении срока принятия наследства","category":"Суд","summary":"Если шесть месяцев со дня смерти пропущены по уважительной причине: восстановить срок и признать принявшим наследство.","notes":["Суд восстановит срок, если вы не знали и не должны были знать об открытии наследства или пропустили срок по другой уважительной причине, и вы обратились в суд в течение шести месяцев после того, как причины пропуска отпали.","Ответчики — другие наследники, принявшие наследство. Если нотариус выдал им свидетельства, суд признает их недействительными и заново определит доли.","Без суда срок можно восстановить только с письменного согласия всех остальных наследников, принявших наследство.","Размер государственной пошлины зависит от того, какие требования заявлены, в том числе от того, оспариваются ли доли и права на имущество. Уточните его в суде или по статье 333.19 Налогового кодекса Российской Федерации."],"basis":[{"lawId":"GK","number":"1155"},{"lawId":"GK","number":"1154"},{"lawId":"GK","number":"1153"},{"lawId":"GK","number":"1152"}],"reviewed":false,"file":"inheritance-build"},
{"id":"inheritance-fact","title":"Заявление об установлении факта принятия наследства","category":"Суд","summary":"Если срок у нотариуса пропущен, но вы фактически приняли наследство: жили в квартире, платили за нее, пользовались вещами.","notes":["Наследник считается принявшим наследство, если в течение шести месяцев фактически вступил во владение имуществом, принял меры по его сохранению, оплатил расходы на содержание или долги наследодателя.","Суд устанавливает такой факт только если нельзя получить документ в ином порядке, например нотариус отказал в выдаче свидетельства. Приложите постановление об отказе.","Заявление подается в суд по месту вашего жительства, а если установление факта связано с недвижимостью, — по месту ее нахождения.","Государственная пошлина по делам особого производства — 3 000 рублей (подпункт 8 пункта 1 статьи 333.19 Налогового кодекса Российской Федерации)."],"basis":[{"lawId":"GK","number":"1153"},{"lawId":"GPK","number":"264"},{"lawId":"GPK","number":"265"},{"lawId":"GPK","number":"266"},{"lawId":"GPK","number":"267"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"inheritance-build"},
{"id":"legal-services","title":"Договор об оказании юридических услуг","category":"Договоры","summary":"Консультации, документы и представительство в суде: объем услуг, цена, порядок приемки и отказ от договора.","notes":["Предмет договора — действия или деятельность исполнителя, а не результат, поэтому гарантировать выигрыш дела нельзя. Не обещайте в договоре определенного итога.","Опишите объем услуг по этапам: консультация, подготовка документов, участие в заседаниях. Это поможет избежать споров и потом подтвердить расходы на представителя в суде.","Заказчик вправе отказаться от договора, оплатив фактически понесенные исполнителем расходы. Если заказчик — гражданин, а исполнитель — предприниматель или организация, действует закон о защите прав потребителей.","Для участия в суде представителю нужна доверенность или ордер адвоката."],"basis":[{"lawId":"GK","number":"779"},{"lawId":"GK","number":"781"},{"lawId":"GK","number":"782"},{"lawId":"GK","number":"783"},{"lawId":"ZOZPP","number":"32"}],"reviewed":false,"file":"inheritance-build"},
{"id":"repair-contract","title":"Договор бытового подряда на ремонт квартиры","category":"Договоры","summary":"Ремонт квартиры для гражданина: объем работ, материалы, цена, сроки, гарантия и права заказчика-потребителя.","notes":["Бытовой подряд — это работа для личных нужд гражданина, которую выполняет подрядчик-предприниматель или организация. Если подрядчик — частное лицо без регистрации, это обычный подряд: для него подойдет шаблон договора подряда.","Подрядчик обязан до заключения договора сообщить достоверную информацию о работе, цене и форме оплаты, и не вправе навязывать дополнительные работы. Заказчик вправе отказаться платить за то, что договором не предусмотрено.","Неустойка за просрочку по закону — 3 % цены работы в день, договором ее уменьшить нельзя. Заказчик вправе в любое время отказаться от договора, оплатив расходы подрядчика.","Приложите смету. Недостатки можно предъявлять в течение гарантийного срока, а если его нет, — не более пяти лет для недвижимости."],"basis":[{"lawId":"GK","number":"730"},{"lawId":"GK","number":"731"},{"lawId":"GK","number":"732"},{"lawId":"GK","number":"721"},{"lawId":"GK","number":"723"},{"lawId":"GK","number":"737"},{"lawId":"ZOZPP","number":"28"},{"lawId":"ZOZPP","number":"32"}],"reviewed":false,"file":"repair-honor"},
{"id":"honor-suit","title":"Исковое заявление о защите чести и достоинства","category":"Суд","summary":"Опровержение ложных сведений, удаление их из интернета и компенсация морального вреда. Пошлина 3 000 рублей.","notes":["Гражданин вправе требовать опровержения сведений, если они порочащие, распространены и не соответствуют действительности. Доказать их правдивость должен тот, кто их распространил.","Опровержение должно быть сделано тем же способом, которым распространены сведения. Если сведения в интернете, можно потребовать их удаления.","Приложите доказательства распространения: скриншоты с датой и адресом страницы, лучше заверенные нотариусом, аудио- или видеозапись, показания свидетелей.","Требования о защите чести и достоинства, включая моральный вред, — неимущественные: пошлина 3 000 рублей, дело рассматривает районный суд."],"basis":[{"lawId":"GK","number":"152"},{"lawId":"GK","number":"150"},{"lawId":"GK","number":"151"},{"lawId":"GPK","number":"131"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"repair-honor"},
{"id":"spouses-agreement","title":"Соглашение о разделе общего имущества супругов","category":"Соглашения и расписки","summary":"Разделить нажитое в браке без суда: кому что достается и какая компенсация. Проект для нотариуса.","notes":["Соглашение о разделе общего имущества, нажитого в браке, должно быть нотариально удостоверено. Этот текст — проект, который нотариус может изменить.","Если соглашение не получается, раздел происходит в суде: для этого есть шаблон иска.","Доли в общем имуществе по закону равны, но супруги могут договориться иначе. Перечислите каждое имущество точно: недвижимость с кадастровым номером, автомобиль с VIN.","Раздел недвижимости и автомобилей влечет регистрацию перехода права в Росреестре и ГИБДД."],"basis":[{"lawId":"SK","number":"33"},{"lawId":"SK","number":"34"},{"lawId":"SK","number":"38"},{"lawId":"SK","number":"39"}],"reviewed":false,"file":"repair-honor"},
{"id":"proceeding-materials","title":"Заявление об ознакомлении с материалами исполнительного производства","category":"Суд","summary":"Узнать, что сделали приставы: прочитать дело, сфотографировать документы и получить копии постановлений.","notes":["Стороны исполнительного производства, то есть взыскатель и должник, вправе знакомиться с материалами производства, делать выписки и снимать копии.","Заявление подается судебному приставу-исполнителю, который ведет производство, лично, по почте или через Госуслуги.","Если вам не дали материалы или не ответили, можно пожаловаться старшему судебному приставу: для этого есть шаблон жалобы."],"basis":[{"lawId":"FZ229","number":"50"}],"reviewed":false,"file":"repair-honor"},
{"id":"consumer-complaint","title":"Жалоба в Роспотребнадзор","category":"Претензии и уведомления","summary":"На магазин или исполнителя, который нарушил права потребителя: проверка и меры по закону о защите прав потребителей.","notes":["Жалоба подается в территориальный орган Роспотребнадзора по месту нарушения или по месту жительства. Можно подать и через Госуслуги или сайт ведомства.","Роспотребнадзор проверяет соблюдение обязательных требований и может привлечь нарушителя к административной ответственности. Требовать вернуть деньги или выплатить неустойку он не может — для этого направьте претензию продавцу и, если не поможет, иск в суд.","Приложите подтверждения: чек, договор, переписку, фото недостатков, свою претензию и ответ на нее."],"basis":[{"lawId":"ZOZPP","number":"40"},{"lawId":"KOAP","number":"14.4"},{"lawId":"KOAP","number":"14.8"}],"reviewed":false,"file":"repair-honor"},
{"id":"utilities-order","title":"Заявление о судебном приказе о взыскании платы за жилье и коммунальные услуги","category":"Суд","summary":"Для управляющей организации, ТСЖ или ресурсоснабжающей организации: долг за жилье, отопление, воду, капитальный ремонт и пени.","notes":["Судебный приказ выдается по требованию о взыскании задолженности по оплате жилого помещения, коммунальных услуг и расходов на капитальный ремонт и содержание общего имущества.","Пени за просрочку: с 31-го по 90-й день — одна трехсотая ставки рефинансирования за каждый день, с 91-го дня — одна стотридцатая. Расчет приложите отдельным документом.","Подавайте заявление мировому судье по месту жительства должника. Пошлина — половина пошлины по иску.","Должник может подать возражения в течение десяти дней, и тогда приказ отменят. Тогда долг взыскивается иском."],"basis":[{"lawId":"GPK","number":"121"},{"lawId":"GPK","number":"122"},{"lawId":"GPK","number":"123"},{"lawId":"GPK","number":"124"},{"lawId":"JK","number":"153"},{"lawId":"JK","number":"155"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"procedure-more"},
{"id":"mandate","title":"Договор поручения","category":"Договоры","summary":"Поручить другому человеку совершить сделку или юридические действия от вашего имени: регистрацию, покупку, получение документов.","notes":["Поверенный действует от имени доверителя, и права и обязанности по заключенной сделке возникают у доверителя. Для этого доверитель выдает доверенность: ее нужно оформить отдельно.","Поручение должно быть конкретным и правомерным: что именно сделать, на каких условиях, в какие сроки.","Вознаграждение платится, если оно предусмотрено договором. Если оба участника или один из них действуют как предприниматели, вознаграждение причитается, если договором не сказано иное.","Доверитель может отменить поручение, а поверенный отказаться от него в любое время. Соглашение об отказе от этого права ничтожно."],"basis":[{"lawId":"GK","number":"971"},{"lawId":"GK","number":"972"},{"lawId":"GK","number":"973"},{"lawId":"GK","number":"974"},{"lawId":"GK","number":"975"},{"lawId":"GK","number":"977"},{"lawId":"GK","number":"978"}],"reviewed":false,"file":"procedure-more"},
{"id":"explanation-request","title":"Заявление о разъяснении решения суда","category":"Суд","summary":"Если резолютивная часть решения непонятна и мешает исполнению: суд поясняет, не меняя содержания.","notes":["Решение разъясняется, если оно неясно. Суд не может его изменить, а только пояснить, что именно им постановлено.","Заявление можно подать, пока решение не приведено в исполнение и не истек срок, в течение которого его можно исполнить принудительно.","Укажите конкретные формулировки решения и в чем состоит неясность. Ссылайтесь на то, как это мешает исполнению."],"basis":[{"lawId":"GPK","number":"202"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"procedure-more"},
{"id":"absence-motion","title":"Ходатайство о рассмотрении дела в отсутствие стороны","category":"Суд","summary":"Если не получается прийти в заседание: суд рассмотрит дело без вас, а копию решения направит по почте.","notes":["Стороны вправе просить суд рассмотреть дело в их отсутствие и направить им копию решения.","Если вы не придете и не сообщите причину или не попросите рассмотреть дело без вас, суд может рассмотреть его в ваше отсутствие и вынести решение, с которым вы не согласитесь.","Если у вас есть возражения или доказательства, пришлите их в суд письменно до заседания."],"basis":[{"lawId":"GPK","number":"167"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"procedure-more"},
{"id":"private-appeal","title":"Частная жалоба на определение суда","category":"Суд","summary":"Если суд вернул иск, отказал в обеспечении или вынес другое определение, которое можно обжаловать отдельно. Срок — 15 дней.","notes":["Отдельно от решения можно обжаловать только те определения, которые это допускают по закону, или те, которые исключают дальнейшее движение дела (например, оставление иска без рассмотрения).","Жалоба подается через суд, вынесший определение, в течение пятнадцати дней со дня его вынесения. Ее рассматривает вышестоящий суд.","Жалоба должна содержать название суда, ваши данные, номер дела, указание на определение, ваши требования и основания, по которым вы считаете его неправильным, и перечень приложений.","Пошлина по частной жалобе для гражданина — 3 000 рублей, для организации — 15 000. Если пошлина не уплачена, жалобу оставят без движения."],"basis":[{"lawId":"GPK","number":"331"},{"lawId":"GPK","number":"332"},{"lawId":"GPK","number":"333"},{"lawId":"GPK","number":"322"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"procedure-more"},
{"id":"interim-measures","title":"Заявление об обеспечении иска","category":"Суд","summary":"Чтобы ответчик не продал имущество и не вывел деньги до решения: арест или запрет действий в пределах иска.","notes":["Обеспечение допускается на любой стадии дела, если непринятие мер может затруднить или сделать невозможным исполнение решения.","Меры должны быть соразмерны требованию: арест накладывается на имущество в пределах цены иска. Укажите, какое именно имущество вы просите арестовать.","Обоснуйте риск: ответчик продает имущество, переводит деньги, скрывается. Приложите доказательства, например выписки или объявления о продаже.","За подачу заявления об обеспечении иска уплачивается государственная пошлина."],"basis":[{"lawId":"GPK","number":"139"},{"lawId":"GPK","number":"140"},{"lawId":"GPK","number":"141"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-motions"},
{"id":"evidence-request","title":"Ходатайство об истребовании доказательств","category":"Суд","summary":"Если нужный документ у другого лица и вы не можете получить его сами: суд запросит его по вашему ходатайству.","notes":["Суд оказывает содействие в собирании доказательств, если стороне это затруднительно. Прежде чем просить суд, попробуйте запросить документ сами и приложите отказ или отсутствие ответа.","В ходатайстве нужно назвать доказательство, обстоятельства, которые оно подтверждает, причины, по которым вы не можете получить его сами, и где оно находится.","Лицо, у которого находится доказательство, обязано представить его или в течение пяти дней сообщить суду о причинах невозможности."],"basis":[{"lawId":"GPK","number":"57"},{"lawId":"GPK","number":"35"},{"lawId":"GPK","number":"56"}],"reviewed":false,"file":"civil-motions"},
{"id":"third-party-motion","title":"Ходатайство о привлечении третьего лица к участию в деле","category":"Суд","summary":"Если решение по делу может повлиять на права или обязанности другого человека или организации: привлечь их на стороне истца или ответчика.","notes":["Третье лицо, не заявляющее самостоятельных требований, привлекается, если решение по делу может повлиять на его права или обязанности по отношению к одной из сторон.","Привлечь можно до принятия решения судом первой инстанции. После вступления третьего лица в процесс дело рассматривается с самого начала.","Объясните, как именно решение затронет права привлекаемого лица, например при споре о залоге или о регрессе."],"basis":[{"lawId":"GPK","number":"43"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"civil-motions"},
{"id":"adjournment-motion","title":"Ходатайство об отложении судебного заседания","category":"Суд","summary":"Если вы не можете прийти или не успели подготовиться: попросить суд отложить заседание, подтвердив причину.","notes":["Суд откладывает дело, если признает невозможным рассмотрение в этом заседании из-за неявки участника, необходимости представить дополнительные доказательства и по другим причинам, перечисленным в статье 169 ГПК.","Просьба не обязывает суд отложить заседание. Подайте ходатайство заранее и приложите документ, подтверждающий причину: больничный лист, командировочное удостоверение, билеты.","Если вы не придете и не сообщите причину, суд может рассмотреть дело без вас (часть 3 статьи 167 ГПК)."],"basis":[{"lawId":"GPK","number":"169"},{"lawId":"GPK","number":"167"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"civil-motions"},
{"id":"judge-recusal","title":"Заявление об отводе судьи","category":"Суд","summary":"Если судья не может рассматривать дело из-за родства, прежнего участия или заинтересованности. Подается до рассмотрения по существу.","notes":["Отвод должен быть мотивирован и заявлен до начала рассмотрения дела по существу. Позже — только если основание стало известно уже после начала рассмотрения.","Недовольство решениями судьи или внепроцессуальное обращение к нему само по себе не основание для отвода. Нужны конкретные факты: родство, прежнее участие в деле, личная заинтересованность.","Повторно заявить отвод тому же судье по тем же основаниям нельзя.","Отвод разрешает тот же судья мотивированным определением. Если отвод удовлетворят, дело передадут другому судье."],"basis":[{"lawId":"GPK","number":"16"},{"lawId":"GPK","number":"19"},{"lawId":"GPK","number":"20"},{"lawId":"GPK","number":"21"}],"reviewed":false,"file":"civil-motions"},
{"id":"claim-amendment","title":"Заявление об уточнении исковых требований","category":"Суд","summary":"Если сумма долга выросла или уменьшилась, изменились основания или предмет иска. Подается до решения суда.","notes":["Истец вправе изменить основание или предмет иска, увеличить или уменьшить размер требований. Нельзя одновременно менять и предмет, и основание иска.","При изменении основания, предмета или увеличении размера требований срок рассмотрения дела начинается заново со дня такого заявления.","Если цена иска увеличивается, проверьте, нужно ли доплатить государственную пошлину, и приложите расчет.","Суд не примет уточнение, если оно противоречит закону или нарушает права других лиц."],"basis":[{"lawId":"GPK","number":"39"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"civil-claims"},
{"id":"claim-withdrawal","title":"Заявление об отказе от иска","category":"Суд","summary":"Если спор решен или вы передумали: суд прекратит дело, а повторно подать тот же иск нельзя.","notes":["Суд принимает отказ от иска, если он не противоречит закону и не нарушает права других лиц, и прекращает производство по делу.","После прекращения производства повторно обратиться в суд по тому же спору, о том же предмете и по тем же основаниям нельзя.","Суд разъяснит вам последствия отказа. Заявление можно подать письменно, и оно приобщается к делу.","При отказе до решения суда первой инстанции возвращается 70 % уплаченной пошлины. Подайте отдельное заявление о возврате."],"basis":[{"lawId":"GPK","number":"39"},{"lawId":"GPK","number":"173"},{"lawId":"GPK","number":"220"},{"lawId":"GPK","number":"221"},{"lawId":"NK","number":"333.40"}],"reviewed":false,"file":"civil-claims"},
{"id":"counterclaim","title":"Встречное исковое заявление","category":"Суд","summary":"Ответчик предъявляет свой иск к истцу в том же деле: зачет, взаимные требования или спор, связанный с первоначальным.","notes":["Встречный иск предъявляется до принятия решения по первоначальному. Подается по общим правилам, как обычный иск, с уплатой пошлины.","Судья принимает его, если требование направлено к зачету, исключает полностью или частично удовлетворение первоначального иска либо тесно связано с ним.","Указывайте и цену иска, и расчет. Приложите доказательства и документы о направлении копии истцу."],"basis":[{"lawId":"GPK","number":"137"},{"lawId":"GPK","number":"138"},{"lawId":"GPK","number":"131"},{"lawId":"GPK","number":"132"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-claims"},
{"id":"review-new-circumstances","title":"Заявление о пересмотре решения по вновь открывшимся или новым обстоятельствам","category":"Суд","summary":"Если после решения стали известны важные факты или отменен акт, на котором оно основано. Срок — три месяца со дня открытия обстоятельства.","notes":["Пересматривается вступившее в силу решение. Основаниями могут быть вновь открывшиеся обстоятельства (существовали на момент решения, но не были известны) или новые (возникли после).","Заявление подается в суд, принявший решение, в течение трех месяцев со дня открытия или появления обстоятельства. Пропущенный срок можно восстановить, если прошло не больше шести месяцев и причины уважительные.","Недовольство оценкой доказательств или выводами суда — не основание: нужны именно обстоятельства из статьи 392 ГПК.","Пошлина за такое заявление — 10 000 рублей (подпункт 14 пункта 1 статьи 333.19 НК РФ)."],"basis":[{"lawId":"GPK","number":"392"},{"lawId":"GPK","number":"393"},{"lawId":"GPK","number":"394"},{"lawId":"GPK","number":"396"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-claims"},
{"id":"protocol-remarks","title":"Замечания на протокол судебного заседания","category":"Суд","summary":"Если в протоколе неверно записаны показания, ходатайства или решения. Срок — пять дней со дня подписания протокола.","notes":["Участники дела вправе ознакомиться с протоколом и аудиозаписью заседания и в течение пяти дней со дня подписания протокола подать замечания на полноту и правильность записи.","Лучше сначала прослушать аудиозапись и указать, в какое время она подтверждает ваши замечания. Копию протокола и записи можно получить по письменному ходатайству.","Замечания, поданные позже, суд не рассматривает, если вместе с ними нет ходатайства о восстановлении срока."],"basis":[{"lawId":"GPK","number":"229"},{"lawId":"GPK","number":"230"},{"lawId":"GPK","number":"231"}],"reviewed":false,"file":"civil-claims"},
{"id":"typo-correction","title":"Заявление об исправлении описки или арифметической ошибки в решении","category":"Суд","summary":"В решении неверно указаны фамилия, номер, дата или сумма из-за технической ошибки: суд исправит, не меняя сути.","notes":["Суд исправляет описки и явные арифметические ошибки, не меняя содержания решения: ошибку в имени, адресе, номере документа, дате или неверное сложение.","Если речь о неверных выводах суда, это обжалуется в апелляции. Исправление описки их не изменит.","Исправление нужно, например, чтобы приставы приняли исполнительный лист или Росреестр зарегистрировал право."],"basis":[{"lawId":"GPK","number":"200"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"civil-after"},
{"id":"additional-judgment","title":"Заявление о принятии дополнительного решения суда","category":"Суд","summary":"Если суд не рассмотрел одно из требований, не указал сумму или не решил вопрос о судебных расходах. Подается до вступления решения в силу.","notes":["Дополнительное решение принимается, если по требованию, по которому стороны представляли доказательства, не вынесено решение, не указана сумма или имущество либо не разрешен вопрос о судебных расходах.","Вопрос можно поставить до вступления решения в силу. Вопрос о судебных расходах позже можно решить отдельным заявлением в течение трех месяцев.","Суд рассмотрит заявление в заседании. Если откажет, на определение можно подать частную жалобу."],"basis":[{"lawId":"GPK","number":"201"},{"lawId":"GPK","number":"98"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"civil-after"},
{"id":"leave-without-consideration","title":"Ходатайство об оставлении иска без рассмотрения","category":"Суд","summary":"Если у иска есть процессуальный недостаток: нет досудебной претензии, дело уже рассматривается, иск подписан без полномочий.","notes":["Оставление без рассмотрения не лишает истца права обратиться снова после устранения недостатка. В этом оно отличается от отказа в иске.","Досудебный порядок обязателен только в случаях, прямо установленных законом, например по некоторым спорам с банками и перевозчиками. Для обычного иска о долге претензия не требуется.","Приложите подтверждения: определение о возбужденном деле, документы, показывающие отсутствие претензии."],"basis":[{"lawId":"GPK","number":"222"},{"lawId":"GPK","number":"223"},{"lawId":"GPK","number":"35"}],"reviewed":false,"file":"civil-after"},
{"id":"succession-motion","title":"Заявление о процессуальном правопреемстве","category":"Суд","summary":"Если сторона выбыла: умерла, реорганизована, уступила требование или передала долг. Суд заменит ее правопреемником, в том числе при исполнении.","notes":["Правопреемство возможно на любой стадии, в том числе после решения, при исполнении исполнительного документа.","Приложите документы о выбытии стороны: свидетельство о смерти и свидетельство о праве на наследство, выписку из ЕГРЮЛ, договор уступки.","Пошлина: 2 000 рублей для гражданина и 15 000 для организации, кроме случаев универсального правопреемства (наследование, реорганизация): тогда пошлина не уплачивается."],"basis":[{"lawId":"GPK","number":"44"},{"lawId":"GPK","number":"35"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-after"},
{"id":"indexation-motion","title":"Заявление об индексации присужденных судом сумм","category":"Суд","summary":"Если должник платил долго: индексация по индексу потребительских цен за время с решения до исполнения. Срок — год со дня исполнения.","notes":["Индексация возмещает обесценивание денег между решением и исполнением. Она считается по индексу потребительских цен Росстата, если иное не установлено законом или договором.","Накопленный индекс за период берите на официальном сайте Росстата. Например, 106,5 % означает рост цен на 6,5 %.","Заявление можно подать в течение года со дня исполнения решения должником. Пропущенный срок восстанавливается по уважительным причинам.","Индексируются суммы со дня вынесения решения или со дня, когда их нужно было выплатить."],"basis":[{"lawId":"GPK","number":"208"},{"lawId":"GPK","number":"112"}],"reviewed":false,"file":"civil-after"},
{"id":"fee-refund","title":"Заявление о возврате государственной пошлины","category":"Суд","summary":"Если пошлина уплачена лишней, иск вернули или вы отказались от иска: вернуть всю сумму или 70 % при отказе до решения.","notes":["Пошлина возвращается полностью или частично, например при уплате в большем размере, возвращении заявления или отказе в принятии иска.","При отказе истца от иска или мировом соглашении до принятия решения судом первой инстанции возвращается 70 % пошлины, в апелляции — 50 %, в кассации — 30 %.","Заявление о возврате излишне уплаченной пошлины можно подать в течение трех лет со дня уплаты; по судебным основаниям срок считается со дня вступления в силу судебного акта.","Приложите подлинник платежного документа и реквизиты счета, на который вернуть деньги."],"basis":[{"lawId":"NK","number":"333.40"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-disputes"},
{"id":"fee-deferral","title":"Ходатайство об отсрочке или рассрочке уплаты государственной пошлины","category":"Суд","summary":"Если нет денег на пошлину при подаче иска: просьба отсрочить или рассрочить уплату, с подтверждением тяжелого положения.","notes":["Отсрочка или рассрочка предоставляется по ходатайству в пределах сроков, установленных для налоговых отсрочек: отсрочка — не более года, рассрочка — не более трех лет.","Приложите документы о доходах и расходах, составе семьи, счетах и обязательствах: справки о доходах, выписки, свидетельства о рождении детей, кредитные договоры.","Ходатайство подается вместе с исковым заявлением. Без уплаты пошлины и без решения по ходатайству иск могут оставить без движения."],"basis":[{"lawId":"NK","number":"333.41"},{"lawId":"NK","number":"64"}],"reviewed":false,"file":"civil-disputes"},
{"id":"void-transaction-suit","title":"Исковое заявление о признании сделки недействительной","category":"Суд","summary":"Договор купли-продажи, дарения или другая сделка заключена под обманом, заблуждением, угрозой или нарушает закон. Считает срок давности.","notes":["Сделки делятся на оспоримые, которые признаёт недействительными суд, и ничтожные, которые недействительны независимо от этого. Нужно назвать конкретное основание из Гражданского кодекса.","Срок давности для оспоримой сделки — один год, для ничтожной — три года. Для оспоримой он идет со дня, когда прекратились насилие или угроза или стало известно об обмане или заблуждении.","Если сделка признана недействительной, стороны возвращают друг другу всё полученное, а при невозможности — деньги (статья 167 ГК). Просите применить последствия.","Пошлина зависит от того, оспаривается ли сделка с требованием о возврате имущества, и считается по цене иска или как за требование неимущественного характера."],"basis":[{"lawId":"GK","number":"166"},{"lawId":"GK","number":"167"},{"lawId":"GK","number":"168"},{"lawId":"GK","number":"178"},{"lawId":"GK","number":"179"},{"lawId":"GK","number":"181"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-disputes"},
{"id":"contract-termination-suit","title":"Исковое заявление о расторжении договора","category":"Суд","summary":"Если другая сторона существенно нарушила договор: сначала предложение расторгнуть, потом иск. Проверяет срок в 30 дней.","notes":["По требованию одной стороны договор расторгается судом только при существенном нарушении другой стороной (или в случаях, указанных в законе или договоре). Нарушение существенно, если сторона в значительной мере лишается того, на что рассчитывала.","Иск можно подать только после получения отказа на предложение расторгнуть договор либо если на него не ответили в срок, а при его отсутствии — в течение тридцати дней.","Расторжение — требование неимущественного характера, пошлина 3 000 рублей. Если одновременно взыскиваете деньги, пошлина считается и по этому требованию."],"basis":[{"lawId":"GK","number":"450"},{"lawId":"GK","number":"451"},{"lawId":"GK","number":"452"},{"lawId":"GK","number":"309"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-disputes"},
{"id":"execution-reversal","title":"Заявление о повороте исполнения решения суда","category":"Суд","summary":"Если решение уже исполнили, а потом отменили и отказали в иске: вернуть всё, что с вас взыскали по отмененному решению.","notes":["Поворот исполнения возможен, если исполненное решение отменено и новым решением в иске отказано полностью или частично либо дело прекращено или иск оставлен без рассмотрения.","Суд, заново рассматривавший дело, обязан сам рассмотреть вопрос о повороте. Если он этого не сделал, заявление подается в этот же суд.","Приложите документы об исполнении отмененного решения: платежные поручения, справки приставов, исполнительные листы.","Пошлина за заявление о повороте исполнения — 3 000 рублей (подпункт 13 пункта 1 статьи 333.19 НК РФ)."],"basis":[{"lawId":"GPK","number":"443"},{"lawId":"GPK","number":"444"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-disputes"},
{"id":"losses-suit","title":"Исковое заявление о взыскании убытков","category":"Суд","summary":"Если из-за нарушения договора вы потеряли деньги или не получили доход: реальный ущерб и упущенная выгода с расчетом и пошлиной.","notes":["Убытки — это реальный ущерб (расходы и повреждение имущества) и упущенная выгода (неполученные доходы). Требовать можно полного возмещения, если договором не предусмотрено меньшее.","Нужно доказать четыре обстоятельства: нарушение договора, размер убытков, причинную связь между ними и свои меры по уменьшению ущерба. Размер подтверждайте документами, оценкой или экспертизой.","При определении упущенной выгоды учитываются меры и приготовления, которые вы предприняли, чтобы получить доход.","Договорную неустойку и убытки можно взыскивать вместе, если иное не следует из договора или закона."],"basis":[{"lawId":"GK","number":"15"},{"lawId":"GK","number":"393"},{"lawId":"GK","number":"309"},{"lawId":"GPK","number":"131"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-property"},
{"id":"unjust-enrichment-suit","title":"Исковое заявление о взыскании неосновательного обогащения","category":"Суд","summary":"Если вы перевели деньги или передали имущество без договора и оснований: вернуть полученное и проценты по статье 395.","notes":["Неосновательное обогащение — это имущество или деньги, которые одно лицо получило за счет другого без оснований, установленных законом или сделкой. Истец доказывает передачу и размер, ответчик — основание, если оно есть.","Ошибочный платеж, предоплата по несостоявшемуся договору, пользование чужим имуществом без договора — типичные случаи.","На сумму денежного обогащения начисляются проценты по статье 395 ГК с того времени, когда получатель узнал или должен был узнать о неосновательности. Сумму процентов можно посчитать в разделе «Расчёты».","Общий срок исковой давности — три года со дня, когда вы узнали или должны были узнать о нарушении права."],"basis":[{"lawId":"GK","number":"1102"},{"lawId":"GK","number":"1103"},{"lawId":"GK","number":"1107"},{"lawId":"GK","number":"395"},{"lawId":"GK","number":"196"},{"lawId":"GK","number":"200"}],"reviewed":false,"file":"civil-property"},
{"id":"penalty-suit","title":"Исковое заявление о взыскании неустойки по договору","category":"Суд","summary":"Если договор предусматривает неустойку за просрочку: расчет по проценту в день и пределу, пошлина, ссылка на статью 333.","notes":["Неустойка — денежная сумма, которую должник уплачивает за просрочку или нарушение обязательства. Она должна быть предусмотрена договором или законом, а договор с условием о ней — заключен в письменной форме.","Кредитору не нужно доказывать размер убытков. Но суд может уменьшить неустойку, если она явно несоразмерна последствиям нарушения; для предпринимателя — только по заявлению должника.","Если договор ограничивает неустойку, укажите предел. Ставку и период считайте по договору, ключевую ставку здесь не используйте.","Одновременно можно требовать основной долг. Тогда цена иска складывается из долга и неустойки."],"basis":[{"lawId":"GK","number":"330"},{"lawId":"GK","number":"331"},{"lawId":"GK","number":"333"},{"lawId":"GK","number":"309"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"civil-property"},
{"id":"vindication-suit","title":"Исковое заявление об истребовании имущества из чужого незаконного владения","category":"Суд","summary":"Вернуть свою вещь: автомобиль, технику, имущество, которое удерживает другой человек без оснований. С учетом добросовестного приобретателя.","notes":["Собственник вправе истребовать имущество из чужого незаконного владения. Нужно доказать, что вещь ваша, что она есть у ответчика и что он владеет ею без оснований.","Если вещь купили у того, кто не имел права ее продавать, и покупатель не знал об этом (добросовестный приобретатель), вернуть ее можно только если она выбыла из вашего владения помимо вашей воли, например была украдена или утеряна. Деньги и ценные бумаги на предъявителя от добросовестного приобретателя не истребуются.","Иск о недвижимости подается по месту ее нахождения. Срок давности — три года со дня, когда вы узнали о нарушении и о том, кто ответчик.","Если вещь уже передана другим людям, укажите, что известно о ее местонахождении."],"basis":[{"lawId":"GK","number":"301"},{"lawId":"GK","number":"302"},{"lawId":"GK","number":"305"},{"lawId":"GK","number":"196"},{"lawId":"GK","number":"200"},{"lawId":"GPK","number":"30"}],"reviewed":false,"file":"civil-property"},
{"id":"negatory-suit","title":"Исковое заявление об устранении препятствий в пользовании имуществом","category":"Суд","summary":"Сосед загораживает проезд, мешает пользоваться участком или квартирой, хотя вас не лишали владения: обязать убрать препятствие.","notes":["Собственник вправе требовать устранения всяких нарушений его права, даже если вас не лишили владения: забор на вашей земле, ограничение проезда, захламление, залив, запрет входа.","На такие требования срок исковой давности не распространяется, пока нарушение продолжается.","Опишите, в чем препятствие, где оно находится и что именно нужно сделать ответчику: снести, убрать, перенести, не препятствовать проходу. Приложите фото, схему, акты.","Иск о правах на землю, здания и помещения подается по месту их нахождения. Пошлина зависит от того, оценивается ли требование: обычно это требование неимущественного характера."],"basis":[{"lawId":"GK","number":"304"},{"lawId":"GK","number":"305"},{"lawId":"GK","number":"208"},{"lawId":"GPK","number":"30"}],"reviewed":false,"file":"civil-property"},
{"id":"adverse-possession-suit","title":"Исковое заявление о признании права собственности по приобретательной давности","category":"Суд","summary":"Если вы добросовестно, открыто и непрерывно владеете чужим имуществом как своим: 15 лет для недвижимости, 5 лет для остального.","notes":["Добросовестность означает, что вы получили имущество, не зная об отсутствии права, и не скрывали владение. Владение должно быть открытым и непрерывным, как своим собственным.","К своему сроку можно присоединить время владения предшественника, чьим правопреемником вы являетесь. Течение срока по вещам, которые могли быть истребованы, начинается со дня открытого владения добросовестного приобретателя.","Право собственности на недвижимость возникает с момента государственной регистрации по решению суда. Иск о недвижимости подается по месту ее нахождения.","Приложите доказательства владения: платежи за коммунальные услуги и налоги, ремонт, переписку, показания соседей."],"basis":[{"lawId":"GK","number":"234"},{"lawId":"GK","number":"225"},{"lawId":"GPK","number":"30"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"property-family"},
{"id":"forced-contract-suit","title":"Исковое заявление о понуждении заключить договор","category":"Суд","summary":"Если организация отказывается заключить публичный договор или договор, обязательный для нее: суд обяжет заключить его.","notes":["Требовать заключения можно, если по Гражданскому кодексу или закону заключить договор для другой стороны обязательно. Например, публичный договор: продажа в розницу, перевозка, услуги связи, энергоснабжение.","Лицо, осуществляющее предпринимательскую деятельность, не вправе отказаться от публичного договора, если может предоставить товары и услуги, и не вправе оказывать предпочтение одному лицу перед другим.","Направьте проект договора и получите отказ или не получите ответ в течение тридцати дней. Лицо, необоснованно уклоняющееся от заключения, возмещает убытки.","Договор считается заключенным на условиях, определенных решением суда. Пошлина — 3 000 рублей за требование неимущественного характера."],"basis":[{"lawId":"GK","number":"445"},{"lawId":"GK","number":"426"},{"lawId":"GK","number":"309"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"property-family"},
{"id":"accident-damage-suit","title":"Исковое заявление о возмещении ущерба от ДТП","category":"Суд","summary":"Ущерб автомобилю превысил страховую выплату: взыскать разницу и расходы на оценку с виновника или владельца.","notes":["Вред возмещается в полном объеме лицом, причинившим вред. Если страхового возмещения не хватает, разницу между ущербом и выплатой взыскивают с причинителя вреда или владельца транспортного средства.","Подтвердите размер ущерба заключением оценщика или экспертизой, а страховую выплату — документом страховщика. Приложите справку о ДТП и протокол или постановление по делу об административном правонарушении.","При столкновении нескольких транспортных средств владельцы отвечают за вред третьим лицам солидарно, а вред друг другу возмещается на общих основаниях.","Иск можно подать по месту своего жительства или месту причинения вреда."],"basis":[{"lawId":"GK","number":"15"},{"lawId":"GK","number":"1064"},{"lawId":"GK","number":"1072"},{"lawId":"GK","number":"1079"},{"lawId":"GPK","number":"29"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"property-family"},
{"id":"marriage-contract","title":"Брачный договор","category":"Соглашения и расписки","summary":"Определить имущественные права супругов: раздельная или долевая собственность, судьба имущества при разводе. Проект для нотариуса.","notes":["Брачный договор заключается письменно и подлежит нотариальному удостоверению. Его можно заключить до или во время брака. Договор до брака вступает в силу со дня регистрации брака.","Договор не может ограничивать правоспособность и дееспособность супругов, их право обратиться в суд, регулировать личные неимущественные отношения и права и обязанности в отношении детей.","Нельзя включать условия, которые ставят одного из супругов в крайне неблагоприятное положение: суд может признать их недействительными.","Односторонний отказ от брачного договора не допускается. Изменить или расторгнуть его можно по соглашению супругов в той же форме. Это проект для нотариуса."],"basis":[{"lawId":"SK","number":"40"},{"lawId":"SK","number":"41"},{"lawId":"SK","number":"42"},{"lawId":"SK","number":"43"},{"lawId":"SK","number":"44"},{"lawId":"SK","number":"34"}],"reviewed":false,"file":"property-family"},
{"id":"children-agreement","title":"Соглашение о детях при расторжении брака","category":"Соглашения и расписки","summary":"С кем будут жить дети, алименты и порядок общения: суд учтет соглашение родителей при разводе, если оно не нарушает интересы детей.","notes":["При разводе через суд родители вправе представить соглашение о том, с кем будут жить дети, о выплате средств на их содержание, об участии в воспитании. Если соглашение нарушает интересы детей, суд сам решит эти вопросы.","Алименты по соглашению на несовершеннолетних детей не могут быть ниже, чем суд взыскал бы по закону: четверть дохода на одного ребенка, треть на двоих, половина на трех и более.","Если алименты хотите платить через нотариуса с силой исполнительного листа, оформите соглашение об уплате алиментов у нотариуса: для него есть отдельный шаблон.","Подпишите соглашение до суда и приложите его к иску о разводе или передайте в заседание."],"basis":[{"lawId":"SK","number":"24"},{"lawId":"SK","number":"80"},{"lawId":"SK","number":"81"},{"lawId":"SK","number":"103"},{"lawId":"SK","number":"66"}],"reviewed":false,"file":"property-family"},
{"id":"child-residence-suit","title":"Исковое заявление об определении места жительства ребенка","category":"Суд","summary":"Если родители живут раздельно и не договорились, с кем жить ребенку: суд решит с учетом интересов и мнения ребенка.","notes":["Место жительства детей при раздельном проживании родителей устанавливается соглашением родителей. При его отсутствии спор решает суд исходя из интересов детей и с учетом их мнения.","Суд учитывает привязанность ребенка к каждому из родителей, братьям и сестрам, возраст ребенка, нравственные и личные качества родителей, отношения между ними и ребенком, возможность создать условия для воспитания и развития.","К участию в деле привлекается орган опеки и попечительства. Приложите характеристики, справки о доходах, документы о жилье и режиме жизни ребенка.","Расскажите, как и с кем ребенок живет сейчас, кто его воспитывает, как он учится и лечится."],"basis":[{"lawId":"SK","number":"65"},{"lawId":"SK","number":"66"},{"lawId":"SK","number":"24"},{"lawId":"GPK","number":"28"}],"reviewed":false,"file":"family-claims"},
{"id":"child-contact-suit","title":"Исковое заявление об определении порядка общения с ребенком","category":"Суд","summary":"Если родитель, с которым живет ребенок, не дает общаться: график встреч, праздники, каникулы, участие в воспитании.","notes":["Родитель, проживающий отдельно, вправе общаться с ребенком, участвовать в его воспитании и решать вопросы образования. Родитель, с которым живет ребенок, не должен препятствовать общению, если оно не вредит ребенку.","Если соглашение невозможно, спор решает суд с участием органа опеки и попечительства. Предложите конкретный график: дни, часы, места, праздники, часть каникул, порядок передачи ребенка.","Условия графика должны учитывать возраст ребенка, режим дня, школу или сад. Для маленьких детей график обычно предусматривает короткие встречи, для старших — более долгие.","Приложите доказательства препятствий: переписку, обращения, ответы, и сведения о том, как вы участвуете в жизни ребенка."],"basis":[{"lawId":"SK","number":"66"},{"lawId":"SK","number":"65"},{"lawId":"GPK","number":"28"}],"reviewed":false,"file":"family-claims"},
{"id":"paternity-suit","title":"Исковое заявление об установлении отцовства","category":"Суд","summary":"Если ребенок родился вне брака и отец не признает ребенка добровольно: суд установит отцовство по любым достоверным доказательствам.","notes":["Отцовство устанавливается в суде, если родители не состоят в браке и нет совместного заявления в ЗАГС или заявления отца. Подать иск может мать, опекун ребенка, лицо, на иждивении которого находится ребенок, или сам ребенок по достижении совершеннолетия.","Суд принимает любые доказательства, с достоверностью подтверждающие происхождение ребенка от конкретного лица: совместное проживание, ведение общего хозяйства, переписку, признание отцовства, показания свидетелей, фотографии. Можно просить суд назначить генетическую экспертизу.","Вместе с отцовством можно потребовать взыскания алиментов на ребенка: для этого есть отдельный шаблон иска.","После вступления решения в силу запись об отце вносится в актовую запись о рождении."],"basis":[{"lawId":"SK","number":"49"},{"lawId":"SK","number":"48"},{"lawId":"SK","number":"51"},{"lawId":"SK","number":"80"}],"reviewed":false,"file":"family-claims"},
{"id":"paternity-contest-suit","title":"Исковое заявление об оспаривании отцовства","category":"Суд","summary":"Если записанный отец фактически не является отцом ребенка: оспорить запись в книге рождений и исключить сведения об отце.","notes":["Запись об отце можно оспорить только в суде. Иск вправе подать лицо, записанное отцом или матерью, лицо, фактически являющееся отцом или матерью, сам ребенок по достижении совершеннолетия, опекун ребенка. Требование наследника записанного отца допускается в случае нарушения его прав.","Требование записанного отца нельзя удовлетворить, если в момент записи ему было известно, что он не отец ребенка. Супруг, давший письменное согласие на искусственное оплодотворение или имплантацию эмбриона, не вправе оспаривать отцовство по этим основаниям.","Суд интересуют доказательства: заключение генетической экспертизы, медицинские документы, сведения о времени зачатия. Обычно просят назначить экспертизу. Расскажите, как вы узнали, что не являетесь отцом.","Если ребенок несовершеннолетний, привлекаются орган опеки и попечительства и законный представитель ребенка."],"basis":[{"lawId":"SK","number":"52"},{"lawId":"SK","number":"51"},{"lawId":"SK","number":"48"}],"reviewed":false,"file":"family-claims"},
{"id":"alimony-change-suit","title":"Исковое заявление об изменении размера алиментов","category":"Суд","summary":"Если после решения суда изменилось материальное или семейное положение: уменьшить, увеличить алименты или освободить от них.","notes":["Размер алиментов, определенный судом, можно изменить, если изменилось материальное или семейное положение одной из сторон: потеря работы, болезнь, рождение другого ребенка, рост дохода, расходы на лечение.","Для алиментов на детей изменить можно размер в твердой сумме или долю; при этом суд учитывает минимальные доли по закону. Освободить от уплаты можно в исключительных случаях, например при утрате трудоспособности.","Приложите решение или судебный приказ, справки о доходах, доказательства изменившихся обстоятельств. Иск подается по месту жительства ответчика, а получатель алиментов может подать и по своему месту жительства.","Если алименты платятся по соглашению, изменить его можно соглашением сторон; суд изменяет только установленные судом алименты."],"basis":[{"lawId":"SK","number":"119"},{"lawId":"SK","number":"81"},{"lawId":"SK","number":"83"},{"lawId":"SK","number":"117"}],"reviewed":false,"file":"family-claims"},
{"id":"spouse-alimony-suit","title":"Исковое заявление о взыскании алиментов на супруга","category":"Суд","summary":"Для супруга (бывшего) в особом положении: в период беременности, при уходе за малышом до трех лет, при нетрудоспособности. Сумма — в твердой величине.","notes":["Право требовать алименты от супруга при отсутствии соглашения имеют нетрудоспособный нуждающийся супруг, жена в период беременности, супруг, ухаживающий за общим ребенком до трех лет, и нуждающийся супруг, ухаживающий за ребенком-инвалидом.","После развода круг лиц уже: бывшая жена в период беременности, наступившей в браке, бывший супруг, ухаживающий за общим ребенком до трех лет, ребенок-инвалид и некоторые случаи нетрудоспособности и пенсионного возраста.","Суд определяет размер в твердой денежной сумме, исходя из материального и семейного положения сторон. Обоснуйте потребности и возможности другой стороны.","Суд может освободить от содержания или ограничить срок, например при непродолжительном браке или недостойном поведении. Истец по алиментным искам освобожден от пошлины."],"basis":[{"lawId":"SK","number":"89"},{"lawId":"SK","number":"90"},{"lawId":"SK","number":"91"},{"lawId":"SK","number":"92"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"family-housing"},
{"id":"parental-rights-suit","title":"Исковое заявление о лишении родительских прав","category":"Суд","summary":"Крайняя мера, если родитель не выполняет обязанности, жестоко обращается с ребенком или злостно уклоняется от алиментов.","notes":["Лишение родительских прав производится только в судебном порядке и только по основаниям из статьи 69 СК. Это крайняя мера, суд применяет ее лишь при виновном поведении родителя и если иные меры не помогают.","Дела рассматриваются с участием прокурора и органа опеки и попечительства. Суд одновременно решает вопрос о взыскании алиментов с лишенного прав родителя.","Лишение не освобождает от обязанности содержать ребенка. Ребенок сохраняет право на жилье и имущественные права, основанные на родстве, но родитель теряет права, основанные на родстве с этим ребенком.","Соберите доказательства: решения и справки приставов о долге по алиментам, характеристики из школы или сада, акты опеки, медицинские документы, свидетельства."],"basis":[{"lawId":"SK","number":"69"},{"lawId":"SK","number":"70"},{"lawId":"SK","number":"71"},{"lawId":"SK","number":"80"}],"reviewed":false,"file":"family-housing"},
{"id":"alimony-penalty-suit","title":"Исковое заявление о взыскании неустойки за просрочку алиментов","category":"Суд","summary":"Если плательщик задолжал по алиментам, установленным судом: 0,1 % долга за каждый день просрочки. Пошлину платить не нужно.","notes":["При долге по алиментам, установленным судом, виновный плательщик уплачивает получателю неустойку 0,1 % от суммы невыплаченных алиментов за каждый день просрочки. Суд вправе уменьшить ее, если она явно несоразмерна последствиям.","Если алименты платятся по соглашению, ответственность определяется самим соглашением.","Считайте неустойку по каждому месяцу отдельно: долг растет, и за разные месяцы разные периоды. Если у вас точный расчет по месяцам, введите итоговую сумму в поле «Сумма неустойки по расчету», иначе шаблон посчитает по одной сумме долга.","Приложите расчет и справку приставов о задолженности. Истец по алиментным искам освобожден от пошлины."],"basis":[{"lawId":"SK","number":"115"},{"lawId":"SK","number":"113"},{"lawId":"GPK","number":"29"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"family-housing"},
{"id":"spouse-consent","title":"Согласие супруга на совершение сделки","category":"Доверенности","summary":"Для сделок с недвижимостью и другим имуществом, права на которое регистрируются: письменное согласие супруга. Проект для нотариуса.","notes":["Для сделки по распоряжению имуществом, права на которое подлежат государственной регистрации, или сделки с обязательной нотариальной формой требуется нотариально удостоверенное согласие другого супруга.","Супруг, чье нотариальное согласие не получено, может требовать признания сделки недействительной в течение года со дня, когда узнал о ней.","Согласие можно дать на конкретную сделку с известным имуществом, а можно и без указания покупателя и цены. Чем конкретнее, тем меньше споров.","Если имущество не общее (личное, по наследству, до брака), согласие не нужно, но нотариус часто просит его для подстраховки."],"basis":[{"lawId":"SK","number":"35"},{"lawId":"SK","number":"34"},{"lawId":"NOTAR","number":"59"}],"reviewed":false,"file":"family-housing"},
{"id":"eviction-suit","title":"Исковое заявление о выселении","category":"Суд","summary":"Если бывший член семьи или бывший жилец не освобождает жилье: признать право пользования прекращенным и выселить.","notes":["Если право пользования жильем прекращено, гражданин обязан его освободить. Если он не делает этого в срок, установленный собственником, его выселяют в судебном порядке.","Право пользования жилым помещением бывшего члена семьи собственника не сохраняется, если иное не установлено соглашением. Суд может сохранить его на определенный срок, если у бывшего члена семьи нет оснований пользоваться другим жильем или он не может обеспечить себя им по имущественному положению.","Иск о правах на жилые помещения подается по месту нахождения жилья. Сначала направьте требование освободить помещение в разумный срок.","Приложите доказательства права собственности, доказательства прекращения семейных отношений, выписку из домовой книги и копию требования об освобождении."],"basis":[{"lawId":"JK","number":"35"},{"lawId":"JK","number":"31"},{"lawId":"JK","number":"30"},{"lawId":"GK","number":"304"},{"lawId":"GPK","number":"30"}],"reviewed":false,"file":"family-housing"},
{"id":"use-order-suit","title":"Исковое заявление об определении порядка пользования жилым помещением","category":"Суд","summary":"Если собственники квартиры в долях не договорились, кто какими комнатами пользуется: закрепить комнаты по долям или компенсацию.","notes":["Владение и пользование общим имуществом осуществляются по соглашению всех участников, а при споре — в порядке, который устанавливает суд.","Каждый участник вправе требовать выделить ему в пользование часть имущества, соразмерную его доле, а если это невозможно, — компенсацию от тех, кто пользуется приходящейся на него частью.","Опишите квартиру: общая и жилая площадь, комнаты, места общего пользования. Приложите поэтажный план из технического паспорта или БТИ.","Если жилая площадь не соответствует вашей доле, можно просить компенсацию за пользование чужой частью."],"basis":[{"lawId":"GK","number":"247"},{"lawId":"GK","number":"246"},{"lawId":"GK","number":"304"},{"lawId":"JK","number":"30"},{"lawId":"GPK","number":"30"}],"reviewed":false,"file":"coowners-sale"},
{"id":"share-allotment-suit","title":"Исковое заявление о выделе доли в натуре или выплате ее стоимости","category":"Суд","summary":"Если сособственники не договорились о разделе: выдел доли в натуре или денежная компенсация, если выдел невозможен.","notes":["Участник долевой собственности вправе требовать выдела доли. Если соглашения нет, он вправе в судебном порядке требовать выдела доли в натуре.","Если выдел в натуре невозможен без несоразмерного ущерба имуществу или не допускается законом, участник вправе получить стоимость доли. Выплата вместо выдела допускается с его согласия, а при незначительной доле суд может обязать выплатить компенсацию и без согласия.","Приложите оценку стоимости имущества и доли, технический план и заключение о возможности выдела. Цена иска — стоимость доли.","С получением компенсации собственник утрачивает право на долю в общем имуществе."],"basis":[{"lawId":"GK","number":"252"},{"lawId":"GK","number":"246"},{"lawId":"GK","number":"247"},{"lawId":"GPK","number":"30"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"coowners-sale"},
{"id":"share-sale-notice","title":"Уведомление сособственников о продаже доли","category":"Претензии и уведомления","summary":"Перед продажей доли постороннему: письменно известить остальных сособственников о цене и условиях, у них месяц на покупку.","notes":["При продаже доли постороннему остальные участники долевой собственности имеют преимущественное право покупки по той же цене и на тех же условиях.","Продавец обязан известить остальных участников в письменной форме о намерении продать долю с указанием цены и других условий. Недвижимость — месяц на покупку, движимое имущество — десять дней.","Если все остальные участники письменно откажутся от покупки, срок ждать не нужно. Сохраните доказательство извещения: подпись о получении или почтовое уведомление, и ответы.","Сделки по отчуждению долей в праве общей собственности на недвижимость подлежат нотариальному удостоверению (с исключениями, перечисленными в законе)."],"basis":[{"lawId":"GK","number":"250"},{"lawId":"GK","number":"246"},{"lawId":"FZ218","number":"42"}],"reviewed":false,"file":"coowners-sale"},
{"id":"flat-sale","title":"Договор купли-продажи квартиры","category":"Договоры","summary":"Квартира между гражданами: описание, цена, порядок расчетов, передача и регистрация перехода права, лица с правом пользования.","notes":["В договоре должны быть данные, позволяющие определенно установить квартиру (адрес, кадастровый номер, площадь, этаж), и цена. Без них договор считается незаключенным.","Существенное условие — перечень лиц, которые сохраняют право пользования после продажи, и их права. Если таких нет, укажите это.","Переход права собственности подлежит государственной регистрации. Квартира передается по передаточному акту. Если супруг продавца не дал нотариального согласия на сделку, сделку можно оспорить.","Для безопасного расчета используют банковскую ячейку или аккредитив. Проверьте выписку из ЕГРН и документы продавца перед сделкой."],"basis":[{"lawId":"GK","number":"549"},{"lawId":"GK","number":"551"},{"lawId":"GK","number":"554"},{"lawId":"GK","number":"555"},{"lawId":"GK","number":"556"},{"lawId":"GK","number":"558"}],"reviewed":false,"file":"coowners-sale"},
{"id":"share-sale","title":"Договор купли-продажи доли в праве общей долевой собственности","category":"Договоры","summary":"Доля в квартире или доме: извещение сособственников, нотариальная форма, цена, передача и регистрация. Проект для нотариуса.","notes":["Сделки по отчуждению долей в праве общей собственности на недвижимость подлежат нотариальному удостоверению, за исключением случаев, прямо указанных в законе, например когда все участники продают свои доли по одной сделке. Это проект для нотариуса.","Перед продажей доли постороннему лицу продавец обязан письменно известить остальных сособственников о цене и условиях. Если они не купят долю за месяц или откажутся письменно, продавать можно любому. Нотариусу покажите доказательства извещения.","Нарушение преимущественного права дает любому сособственнику три месяца, чтобы потребовать в суде перевода на него прав покупателя.","Опишите долю точно: размер доли, имущество, кадастровый номер, права остальных сособственников."],"basis":[{"lawId":"GK","number":"250"},{"lawId":"GK","number":"246"},{"lawId":"GK","number":"549"},{"lawId":"GK","number":"551"},{"lawId":"FZ218","number":"42"}],"reviewed":false,"file":"coowners-sale"},
{"id":"exchange","title":"Договор мены","category":"Договоры","summary":"Обмен вещи на вещь без денег или с доплатой: автомобиль на мотоцикл, технику на технику. Равноценность, доплата, передача.","notes":["По договору мены каждая сторона передает в собственность другой один товар в обмен на другой. Каждая сторона считается и продавцом своего товара, и покупателем чужого, поэтому применяются правила о купле-продаже.","Если из договора не следует иное, обмениваемые товары предполагаются равноценными. Если они неравноценны, сторона, чей товар дешевле, доплачивает разницу до или после передачи.","Если передача товаров по времени не совпадает, применяются правила о встречном исполнении: вторая сторона вправе не передавать товар, пока не получит свой.","Недвижимость и транспортные средства меняют по общим правилам оформления сделок: для недвижимости нужна регистрация перехода права."],"basis":[{"lawId":"GK","number":"567"},{"lawId":"GK","number":"568"},{"lawId":"GK","number":"569"},{"lawId":"GK","number":"570"}],"reviewed":false,"file":"civil-contracts"},
{"id":"commission","title":"Договор комиссии","category":"Договоры","summary":"Продать вещь через комиссионера или купить ее: сделка заключается от имени комиссионера, но за счет комитента. Вознаграждение и отчет.","notes":["Комиссионер совершает сделки от своего имени, но за счет комитента. По сделке права и обязанности возникают у комиссионера, хотя комитент назван в сделке.","Комитент платит вознаграждение в размере и в порядке, установленных договором. Если договор не исполнен по причинам, зависящим от комитента, комиссионер сохраняет право на вознаграждение и возмещение расходов.","Комиссионер не отвечает перед комитентом за неисполнение третьим лицом сделки, кроме случаев, когда он не проявил осмотрительности в выборе контрагента или дал ручательство (делькредере).","По исполнении поручения комиссионер представляет комитенту отчет, а комитент принимает его в течение срока, указанного в договоре."],"basis":[{"lawId":"GK","number":"990"},{"lawId":"GK","number":"991"},{"lawId":"GK","number":"993"},{"lawId":"GK","number":"997"},{"lawId":"GK","number":"1001"}],"reviewed":false,"file":"civil-contracts"},
{"id":"agency","title":"Агентский договор","category":"Договоры","summary":"Агент действует по поручению принципала за вознаграждение: от своего имени или от имени принципала. Территория, отчет, ограничения.","notes":["Агент совершает юридические и иные действия по поручению принципала от своего имени, но за счет принципала, либо от имени и за счет принципала. От этого зависит, у кого возникают права и обязанности по сделке.","Принципал платит вознаграждение в размере и в порядке, указанных в договоре. Если порядок не указан, оно платится в течение недели после представления отчета.","Договор может ограничивать территорию: принципал не заключает аналогичных договоров с другими агентами на этой территории, а агент — с другими принципалами.","Агент представляет отчеты по мере исполнения поручения или по окончании. Принципал обязан принять отчет или заявить возражения в срок, указанный в договоре."],"basis":[{"lawId":"GK","number":"1005"},{"lawId":"GK","number":"1006"},{"lawId":"GK","number":"1007"},{"lawId":"GK","number":"1008"},{"lawId":"GK","number":"1010"}],"reviewed":false,"file":"civil-contracts"},
{"id":"pledge","title":"Договор залога движимого имущества","category":"Договоры","summary":"Обеспечить заем или долг: залог автомобиля, техники, драгоценностей. Предмет, обеспечиваемое обязательство, где хранится, обращение взыскания.","notes":["В договоре залога должны быть указаны предмет залога, существо, размер и срок исполнения обеспечиваемого обязательства. Без этого договор недействителен. Он заключается письменно.","Залогодателем может быть должник или третье лицо. Передать вещь в залог вправе собственник; чужую вещь заложить нельзя.","При неисполнении долга залогодержатель вправе получить удовлетворение из стоимости предмета залога преимущественно перед другими кредиторами. Если выручки не хватило, залогодержатель вправе взыскать остаток с должника.","Залог недвижимости (ипотека) и залог транспортных средств с регистрацией имеют особенности; этот шаблон подходит для движимого имущества. Уведомление о залоге можно зарегистрировать в реестре уведомлений."],"basis":[{"lawId":"GK","number":"334"},{"lawId":"GK","number":"335"},{"lawId":"GK","number":"339"},{"lawId":"GK","number":"337"}],"reviewed":false,"file":"civil-contracts"},
{"id":"suretyship","title":"Договор поручительства","category":"Договоры","summary":"Кто-то отвечает за долг заемщика: поручитель отвечает солидарно с должником. Письменная форма, срок поручительства, объем ответственности.","notes":["Договор поручительства заключается в письменной форме, иначе он недействителен. В нем нужно описать, за какое обязательство отвечает поручитель: достаточно ссылки на основной договор.","Если иное не предусмотрено договором, поручитель и должник отвечают перед кредитором солидарно и в том же объеме, включая проценты, судебные расходы и убытки.","Поручительство прекращается с исполнением основного обязательства. Если в договоре не указан срок поручительства, оно прекращается, если кредитор не предъявит иск в течение года со дня наступления срока исполнения основного обязательства.","Если основное обязательство изменено без согласия поручителя и его ответственность выросла, поручитель отвечает на прежних условиях."],"basis":[{"lawId":"GK","number":"361"},{"lawId":"GK","number":"362"},{"lawId":"GK","number":"363"},{"lawId":"GK","number":"365"},{"lawId":"GK","number":"367"}],"reviewed":false,"file":"civil-contracts"},
{"id":"will","title":"Завещание","category":"Соглашения и расписки","summary":"Распорядиться имуществом на случай смерти: кому что достанется, подназначение наследника, завещательный отказ. Проект для нотариуса.","notes":["Завещание составляется письменно и удостоверяется нотариусом, иначе оно недействительно. Оно должно быть совершено лично, через представителя завещание составить нельзя. Составление в электронном виде не допускается.","Завещатель свободен в выборе наследников и вправе лишить наследства любых наследников по закону. Но нетрудоспособные и несовершеннолетние дети, нетрудоспособные супруг и родители наследуют обязательную долю независимо от завещания.","Завещать можно любое имущество, в том числе то, которое будет приобретено в будущем. Завещание можно в любое время изменить или отменить новым завещанием, не объясняя причин.","Это проект: нотариус разъяснит последствия, проверит дееспособность и при необходимости изменит формулировки."],"basis":[{"lawId":"GK","number":"1118"},{"lawId":"GK","number":"1119"},{"lawId":"GK","number":"1120"},{"lawId":"GK","number":"1124"},{"lawId":"GK","number":"1130"},{"lawId":"GK","number":"1149"}],"reviewed":false,"file":"succession"},
{"id":"inheritance-contract","title":"Наследственный договор","category":"Соглашения и расписки","summary":"Наследодатель заранее договаривается с будущим наследником, кто и на каких условиях получит имущество, и что наследник должен делать. Проект для нотариуса.","notes":["Наследственный договор заключается между наследодателем и тем, кто может призываться к наследованию. Он определяет круг наследников и порядок перехода прав на имущество после смерти наследодателя и может возлагать на наследника обязанности: ухаживать, содержать, платить.","Он подписывается каждой стороной и подлежит нотариальному удостоверению; нотариус при этом ведет видеофиксацию, если стороны не возражают.","Права и обязанности по договору неотчуждаемы и не передаются иным способом. Он действует в части, не противоречащей правилам об обязательной доле в наследстве.","Изменить или расторгнуть договор можно только при жизни сторон по соглашению или по решению суда. Наследодатель вправе односторонне отказаться, уведомив стороны через нотариуса, но возместит убытки другим сторонам."],"basis":[{"lawId":"GK","number":"1140.1"},{"lawId":"GK","number":"1118"},{"lawId":"GK","number":"1116"},{"lawId":"GK","number":"1149"}],"reviewed":false,"file":"succession"},
{"id":"inheritance-renunciation","title":"Заявление об отказе от наследства","category":"Соглашения и расписки","summary":"Если вы не хотите принимать наследство: в пользу других наследников или без указания лиц. Подается нотариусу в срок принятия.","notes":["Отказаться можно в течение шести месяцев со дня смерти, даже если вы уже приняли наследство. Отказ нельзя изменить или взять обратно, поэтому подумайте заранее.","Отказ допускается в пользу других наследников по завещанию или по закону, но не от обязательной доли и не по условию или с оговорками. От части наследства отказаться нельзя, только от всего.","Если за вас или за несовершеннолетнего отказывается представитель, понадобится доверенность с таким полномочием или разрешение органа опеки. Если заявление передано через другого человека или по почте, подпись должна быть засвидетельствована.","После отказа вы теряете право на любое наследство после этого человека, и ваша доля переходит к другим наследникам."],"basis":[{"lawId":"GK","number":"1157"},{"lawId":"GK","number":"1158"},{"lawId":"GK","number":"1159"},{"lawId":"GK","number":"1154"}],"reviewed":false,"file":"succession"},
{"id":"inheritance-partition","title":"Соглашение о разделе наследства","category":"Соглашения и расписки","summary":"Если наследников несколько и имущество в общей долевой собственности: разделить его по договоренности, без суда, с компенсацией.","notes":["К соглашению о разделе наследства применяются правила о форме сделок: если в состав входит недвижимость, соглашение заключается после выдачи свидетельства о праве на наследство и подлежит нотариальному удостоверению, как и сделки с долями.","Регистрация прав на недвижимость проводится по соглашению и ранее выданному свидетельству. Если раздел не соответствует долям из свидетельства, это не повод отказать в регистрации.","Несоразмерность полученного имущества доле наследника устраняется выплатой денежной компенсации. Наследники, жившие в жилье на день открытия наследства и не имеющие другого жилья, имеют преимущественное право на получение жилого помещения при разделе.","Если договориться не получается, раздел происходит в суде."],"basis":[{"lawId":"GK","number":"1164"},{"lawId":"GK","number":"1165"},{"lawId":"GK","number":"1168"},{"lawId":"GK","number":"1170"},{"lawId":"GK","number":"252"}],"reviewed":false,"file":"succession"},
{"id":"spouse-share-certificate","title":"Заявление пережившего супруга о выдаче свидетельства о праве собственности на долю","category":"Соглашения и расписки","summary":"После смерти супруга: получить у нотариуса свидетельство о вашей доле в общем имуществе (обычно половина), чтобы оформить права.","notes":["Если один из супругов умер, свидетельство о праве собственности на долю в общем имуществе выдается нотариусом по месту открытия наследства по письменному заявлению пережившего супруга с извещением наследников, принявших наследство.","Оно может быть выдано на половину общего имущества, нажитого в браке. Доля умершего супруга в этом имуществе входит в наследство и делится между наследниками.","Приложите свидетельство о смерти, свидетельство о браке и документы на имущество. Это не заменяет принятия наследства: наследство принимается отдельным заявлением.","Имущество, полученное одним из супругов по наследству или в дар, не считается общим."],"basis":[{"lawId":"NOTAR","number":"75"},{"lawId":"SK","number":"34"},{"lawId":"SK","number":"39"},{"lawId":"GK","number":"1150"}],"reviewed":false,"file":"succession"},
{"id":"job-application","title":"Заявление о приеме на работу","category":"Трудовые отношения","summary":"Просьба принять на работу на должность с указанной даты: с испытательным сроком и без, основная работа или по совместительству.","notes":["Заявление не обязательно по закону: прием на работу оформляется трудовым договором. Но многие работодатели просят его, чтобы подтвердить намерение и дату выхода.","При приеме нужны паспорт, трудовая книжка или сведения о трудовой деятельности, документ об индивидуальном учете, документы воинского учета, а для некоторых должностей документ об образовании. Требовать другие документы работодатель не вправе.","Трудовой договор подписывается в двух экземплярах. Если вас допустили к работе без договора, он считается заключенным, а оформить его обязаны не позднее трех рабочих дней.","Испытание не устанавливается для беременных женщин, несовершеннолетних, молодых специалистов после обучения и в ряде других случаев."],"basis":[{"lawId":"TK","number":"65"},{"lawId":"TK","number":"67"},{"lawId":"TK","number":"68"},{"lawId":"TK","number":"70"}],"reviewed":false,"file":"labor-more"},
{"id":"employment-amendment","title":"Дополнительное соглашение к трудовому договору","category":"Трудовые отношения","summary":"Изменить условия трудового договора по согласию сторон: оплату, режим работы, должность, место работы.","notes":["Условия трудового договора меняются только по соглашению сторон, и соглашение заключается в письменной форме. Работодатель по общему правилу не вправе изменить их в одностороннем порядке.","Если речь о смене должности или трудовой функции, это перевод: работник должен дать письменное согласие.","Соглашение составляется в двух экземплярах, по одному для каждой стороны, и подписывается обеими сторонами.","Работодатель оформляет изменения приказом, который должен соответствовать соглашению, а запись о переводе вносится в сведения о трудовой деятельности."],"basis":[{"lawId":"TK","number":"72"},{"lawId":"TK","number":"57"},{"lawId":"TK","number":"72.1"},{"lawId":"TK","number":"74"}],"reviewed":false,"file":"labor-more"},
{"id":"transfer-request","title":"Заявление о переводе на другую работу","category":"Трудовые отношения","summary":"Просьба о постоянном или временном переводе на другую должность, в другое подразделение или к другому работодателю.","notes":["Перевод на другую работу — это изменение трудовой функции или подразделения (если оно указано в договоре). Он допускается только с письменного согласия работника. Согласие работодателя тоже необходимо: заявление не обязывает его перевести вас.","Временный перевод возможен на срок до одного года, а при замещении отсутствующего работника — до его выхода. Если по окончании срока прежняя работа не предоставлена, а вы продолжаете работать, перевод становится постоянным.","Перевод к другому работодателю оформляется увольнением в порядке перевода: трудовой договор по прежнему месту работы прекращается по пункту 5 части первой статьи 77.","Запрещается переводить на работу, противопоказанную по состоянию здоровья."],"basis":[{"lawId":"TK","number":"72.1"},{"lawId":"TK","number":"72.2"},{"lawId":"TK","number":"72"},{"lawId":"TK","number":"77"}],"reviewed":false,"file":"labor-more"},
{"id":"terms-change-notice","title":"Уведомление об изменении определенных сторонами условий трудового договора","category":"Трудовые отношения","summary":"Работодатель сообщает работнику не позднее чем за два месяца, что условия труда меняются из-за организационных причин. Считает срок.","notes":["Работодатель вправе изменить условия договора в одностороннем порядке только по причинам, связанным с изменением организационных или технологических условий труда. Трудовая функция при этом не меняется.","Уведомить нужно письменно не позднее чем за два месяца. Работник расписывается в получении, а при отказе подписать составляется акт.","Если работник не согласен, работодатель обязан письменно предложить другую имеющуюся работу, включая нижестоящую и нижеоплачиваемую, которую работник может выполнять по состоянию здоровья.","Если подходящей работы нет или работник отказывается от нее, договор прекращается по пункту 7 части первой статьи 77."],"basis":[{"lawId":"TK","number":"74"},{"lawId":"TK","number":"77"},{"lawId":"TK","number":"72"}],"reviewed":false,"file":"labor-more"},
{"id":"redundancy-notice","title":"Уведомление о сокращении","category":"Трудовые отношения","summary":"Работодатель предупреждает работника персонально и под роспись не менее чем за два месяца о предстоящем увольнении при сокращении штата. Считает срок.","notes":["О предстоящем увольнении при сокращении работников предупреждают персонально и под роспись не менее чем за два месяца. С письменного согласия работника договор можно расторгнуть и раньше, выплатив дополнительную компенсацию в размере среднего заработка за оставшуюся часть срока предупреждения.","Работодатель обязан предложить работнику другую имеющуюся работу (вакантную должность или нижестоящую, нижеоплачиваемую), которую тот может выполнять по состоянию здоровья.","Работнику выплачивают выходное пособие в размере среднего месячного заработка, а на время трудоустройства сохраняют средний заработок до двух месяцев со дня увольнения (в исключительных случаях до трех).","При равной производительности труда и квалификации преимущественное право оставления на работе есть у отдельных категорий работников."],"basis":[{"lawId":"TK","number":"180"},{"lawId":"TK","number":"81"},{"lawId":"TK","number":"178"},{"lawId":"TK","number":"179"}],"reviewed":false,"file":"labor-more"},
{"id":"explanation-demand","title":"Требование о даче письменного объяснения работником","category":"Трудовые отношения","summary":"Работодатель просит работника объяснить в письменной форме причины предполагаемого проступка до применения взыскания.","notes":["До применения дисциплинарного взыскания работодатель обязан затребовать письменное объяснение. Если за два рабочих дня объяснение не дано, составляется акт.","Взыскание применяется не позднее одного месяца со дня обнаружения проступка, не считая болезни и отпуска работника, и не позднее шести месяцев со дня его совершения.","Требование вручается под роспись. Если работник отказывается получить его, составляется акт об отказе или требование направляется по почте заказным письмом.","Не допускаются взыскания, не предусмотренные законом: только замечание, выговор или увольнение по соответствующим основаниям."],"basis":[{"lawId":"TK","number":"193"},{"lawId":"TK","number":"192"},{"lawId":"TK","number":"189"}],"reviewed":false,"file":"labor-disputes"},
{"id":"explanation-refusal-act","title":"Акт о непредставлении письменного объяснения","category":"Акты","summary":"Если работник не дал объяснение в течение двух рабочих дней или отказался его писать: фиксируем это перед наказанием.","notes":["Акт составляют не раньше чем по истечении двух рабочих дней после того, как работнику вручено требование об объяснении.","Подписывают акт не менее двух-трех работников, которые присутствовали и видели, что объяснение не дано. Если работник отказался подписать акт, это отмечается в нем отдельной строкой.","Отсутствие объяснения не мешает применить взыскание, но без требования и акта оно может быть признано незаконным.","Акт нужен и при материальной ответственности: работодатель обязан затребовать объяснение до решения о возмещении ущерба."],"basis":[{"lawId":"TK","number":"193"},{"lawId":"TK","number":"247"}],"reviewed":false,"file":"labor-disputes"},
{"id":"discipline-order","title":"Приказ о применении дисциплинарного взыскания","category":"Трудовые отношения","summary":"Замечание или выговор за проступок. Проверяет сроки: месяц с обнаружения и шесть месяцев с совершения.","notes":["Взыскание применяется не позднее одного месяца со дня обнаружения проступка, не считая времени болезни и отпуска работника, и не позднее шести месяцев со дня его совершения (по итогам ревизии и проверки — двух лет).","За каждый проступок — только одно взыскание. При выборе учитываются тяжесть проступка и обстоятельства, при которых он совершен.","Работника знакомят с приказом под роспись в течение трех рабочих дней, не считая времени отсутствия на работе. Если он отказывается расписаться, составляется акт.","Взыскание можно обжаловать в трудовую инспекцию и суд. Приложите к приказу объяснение работника или акт о непредставлении объяснения."],"basis":[{"lawId":"TK","number":"192"},{"lawId":"TK","number":"193"},{"lawId":"TK","number":"189"}],"reviewed":false,"file":"labor-disputes"},
{"id":"discipline-suit","title":"Исковое заявление об оспаривании дисциплинарного взыскания","category":"Трудовые отношения","summary":"Отменить выговор или замечание, если проступка не было или нарушен порядок применения. Пошлину платить не нужно.","notes":["В суд можно обратиться в течение трех месяцев со дня, когда вы узнали или должны были узнать о нарушении права. Пропущенный по уважительной причине срок суд может восстановить.","Работник освобожден от госпошлины по трудовым спорам. Иск подают в суд по месту жительства работника или по месту нахождения работодателя.","Суд проверяет, был ли проступок, соблюден ли порядок (объяснение, сроки, подпись приказа) и соответствует ли взыскание тяжести проступка. Бремя доказывания лежит на работодателе.","Компенсацию морального вреда можно потребовать одновременно (статья 237 ТК)."],"basis":[{"lawId":"TK","number":"192"},{"lawId":"TK","number":"193"},{"lawId":"TK","number":"392"},{"lawId":"TK","number":"237"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"labor-disputes"},
{"id":"dismissal-suit","title":"Исковое заявление о восстановлении на работе","category":"Трудовые отношения","summary":"Оспорить увольнение: вернуться на прежнюю работу или изменить формулировку, взыскать средний заработок за прогул. Срок один месяц.","notes":["По спорам об увольнении в суд можно обратиться в течение одного месяца со дня вручения копии приказа или выдачи трудовой книжки (сведений о трудовой деятельности). Срок короткий: пропущенный по уважительной причине срок суд может восстановить.","Если увольнение признано незаконным, суд восстановит работника и взыщет средний заработок за время вынужденного прогула. Вместо восстановления можно просить изменить формулировку на увольнение по собственному желанию и дату увольнения.","Работник освобожден от госпошлины. Иск подают по месту своего жительства или по месту нахождения работодателя.","Средний дневной заработок считают по правилам статьи 139 ТК за двенадцать месяцев до увольнения; прогул считают по рабочим дням по графику работодателя."],"basis":[{"lawId":"TK","number":"394"},{"lawId":"TK","number":"392"},{"lawId":"TK","number":"81"},{"lawId":"TK","number":"237"},{"lawId":"NK","number":"333.36"}],"reviewed":false,"file":"labor-disputes"},
{"id":"hire-order","title":"Приказ о приеме на работу","category":"Трудовые отношения","summary":"Кадровый приказ на основании трудового договора: должность, оклад, испытание, срочный или бессрочный договор.","notes":["Прием на работу оформляется трудовым договором. Приказ издается на основании договора, и его содержание должно совпадать с условиями договора.","Работника нужно ознакомить с приказом под роспись в течение трех рабочих дней со дня фактического начала работы.","Испытание не может превышать трех месяцев (для руководителей и их заместителей, главных бухгалтеров — шести), для срочного договора до шести месяцев — не более двух недель.","Срочный договор заключается только в случаях, прямо предусмотренных Трудовым кодексом, и срок с обстоятельствами указывается в договоре и приказе."],"basis":[{"lawId":"TK","number":"68"},{"lawId":"TK","number":"57"},{"lawId":"TK","number":"70"},{"lawId":"TK","number":"59"}],"reviewed":false,"file":"labor-orders"},
{"id":"dismissal-order","title":"Приказ об увольнении","category":"Трудовые отношения","summary":"Приказ о прекращении трудового договора: по собственному желанию, по соглашению, по окончании срока или по сокращению; с выплатой компенсации за отпуск.","notes":["Прекращение трудового договора оформляется приказом. Работника знакомят с ним под роспись; по его требованию выдают заверенную копию. Если он отказывается подписать, составляется акт.","Днем прекращения договора считается последний день работы. В этот день работодатель обязан выдать трудовую книжку или сведения о трудовой деятельности и произвести окончательный расчет.","Формулировка основания записывается в точном соответствии с Трудовым кодексом со ссылкой на статью, часть и пункт.","При увольнении выплачивается компенсация за все неиспользованные отпуска. При сокращении дополнительно выходное пособие."],"basis":[{"lawId":"TK","number":"84.1"},{"lawId":"TK","number":"77"},{"lawId":"TK","number":"80"},{"lawId":"TK","number":"140"},{"lawId":"TK","number":"127"}],"reviewed":false,"file":"labor-orders"},
{"id":"vacation-order","title":"Приказ о предоставлении отпуска","category":"Трудовые отношения","summary":"Приказ о ежегодном оплачиваемом отпуске с подсчетом календарных дней и проверкой срока уведомления работника.","notes":["Отпуск предоставляется по графику отпусков. О времени начала отпуска работник должен быть извещен под роспись не позднее чем за две недели до его начала.","Основной отпуск — 28 календарных дней. Работающим инвалидам не менее 30 календарных дней. Право на отпуск за первый год возникает по истечении шести месяцев работы, но по соглашению сторон отпуск можно дать раньше.","Оплата отпуска производится не позднее чем за три дня до его начала.","Если отпуск разделен на части, одна из них должна быть не менее 14 календарных дней."],"basis":[{"lawId":"TK","number":"114"},{"lawId":"TK","number":"115"},{"lawId":"TK","number":"122"},{"lawId":"TK","number":"123"},{"lawId":"TK","number":"136"}],"reviewed":false,"file":"labor-orders"},
{"id":"liability-contract","title":"Договор о полной индивидуальной материальной ответственности","category":"Трудовые отношения","summary":"Работник отвечает за недостачу вверенного имущества в полном размере. Проверяет возраст работника.","notes":["Такой договор можно заключить только с работником старше 18 лет, который непосредственно обслуживает или использует денежные, товарные ценности или иное имущество, и только по должностям и работам из утвержденного перечня.","Работодатель обязан доказать размер ущерба и причину его возникновения, провести проверку и затребовать письменное объяснение работника.","Работник не отвечает за ущерб, возникший из-за нормального производственного риска, крайней необходимости, необходимой обороны или неисполнения работодателем обязанности по обеспечению сохранности имущества.","Договор заключается в письменной форме в двух экземплярах и подписывается обеими сторонами. Он применяется только к имуществу, вверенному работнику."],"basis":[{"lawId":"TK","number":"244"},{"lawId":"TK","number":"243"},{"lawId":"TK","number":"242"},{"lawId":"TK","number":"247"}],"reviewed":false,"file":"labor-orders"},
{"id":"parental-leave","title":"Заявление об отпуске по уходу за ребенком до трех лет","category":"Трудовые отношения","summary":"Отпуск по уходу за ребенком до достижения трех лет: матерью, отцом, бабушкой, дедушкой, другим родственником или опекуном. Проверяет срок.","notes":["Отпуск по уходу предоставляется по заявлению до достижения ребенком трех лет. Его можно использовать полностью или частями, а также передавать другим членам семьи, но не одновременно.","Работник вправе выходить на работу на условиях неполного рабочего времени или на дому, сохраняя право на пособие; на время отпуска за ним сохраняется место работы.","Отпуск засчитывается в трудовой стаж, а также в стаж работы по специальности (за исключением досрочного назначения страховой пенсии по старости).","Если отпуск оформляет не мать, приложите справку с места работы матери о том, что она им не пользуется и пособие не получает."],"basis":[{"lawId":"TK","number":"256"},{"lawId":"TK","number":"255"},{"lawId":"TK","number":"114"}],"reviewed":false,"file":"labor-orders"},
{"id":"koap-appeal","title":"Жалоба на постановление по делу об административном правонарушении","category":"Суд","summary":"Обжаловать штраф, лишение прав и другие наказания по КоАП: в вышестоящий орган или в районный суд, без пошлины, в течение 10 дней.","notes":["Жалобу можно подать в течение десяти дней со дня вручения или получения копии постановления. Если срок пропущен, одновременно подайте ходатайство о его восстановлении (отдельный шаблон).","Постановление, вынесенное должностным лицом, обжалуется в вышестоящий орган или в районный суд по месту рассмотрения дела. Жалобу подают в орган, который вынес постановление, или сразу в суд: орган обязан передать ее в суд в течение трех суток.","Государственная пошлина за жалобу на постановление по делу об административном правонарушении не уплачивается.","Если оштрафовали организацию или предпринимателя за деятельность, связанную с экономической деятельностью, постановление обжалуется в арбитражный суд. Подача жалобы не отменяет обязанность платить штраф, если постановление не приостановлено."],"basis":[{"lawId":"KOAP","number":"30.1"},{"lawId":"KOAP","number":"30.2"},{"lawId":"KOAP","number":"30.3"},{"lawId":"KOAP","number":"30.6"}],"reviewed":false,"file":"admin"},
{"id":"koap-restore-deadline","title":"Ходатайство о восстановлении срока обжалования постановления","category":"Суд","summary":"Если десять дней на жалобу по КоАП уже прошли: просьба вернуть срок с объяснением причин. Подается вместе с жалобой.","notes":["Срок обжалования — десять дней. Он может быть восстановлен по ходатайству судьей или должностным лицом, правомочными рассматривать жалобу.","Подавать ходатайство нужно вместе с жалобой на постановление и приложить документы, подтверждающие причину: больничный, командировочное, почтовые документы, свидетельство об отсутствии извещения.","Уважительными обычно считаются болезнь, командировка, поздняя доставка постановления, отсутствие извещения о рассмотрении дела.","Если в восстановлении срока отказано, выносится определение, которое можно обжаловать."],"basis":[{"lawId":"KOAP","number":"30.3"},{"lawId":"KOAP","number":"30.2"},{"lawId":"KOAP","number":"30.1"}],"reviewed":false,"file":"admin"},
{"id":"fine-instalment","title":"Заявление о рассрочке или отсрочке уплаты административного штрафа","category":"Суд","summary":"Если нет возможности заплатить штраф сразу: рассрочка на срок до трех месяцев с учетом материального положения. Считает ежемесячный платеж.","notes":["С учетом материального положения штраф можно рассрочить на срок до трех месяцев. Отсрочить исполнение постановления можно на срок до шести месяцев при обстоятельствах, из-за которых исполнить его в срок невозможно.","Рассрочка и отсрочка не применяются к иностранным гражданам, которым штраф назначен вместе с выдворением, и в отдельных случаях нарушений на иностранном транспорте.","Заявление подают судье, органу или должностному лицу, которые вынесли постановление, до истечения срока уплаты. Обычно штраф нужно оплатить в течение 60 дней со дня вступления постановления в силу.","Приложите документы о доходах и расходах: справку о заработной плате, о составе семьи, о пособиях, о кредитах."],"basis":[{"lawId":"KOAP","number":"31.5"},{"lawId":"KOAP","number":"32.2"}],"reviewed":false,"file":"admin"},
{"id":"camera-fine-complaint","title":"Жалоба на постановление о штрафе с камеры (собственник не управлял автомобилем)","category":"Суд","summary":"Штраф пришел собственнику, а автомобилем управлял другой человек или он был угнан: освобождение от ответственности по статье 2.6.1 КоАП.","notes":["Если нарушение зафиксировано камерами в автоматическом режиме, ответственность несет собственник. Но он освобождается, если подтвердит, что автомобиль в момент нарушения был в пользовании или владении другого лица либо выбыл из обладания в результате противоправных действий.","Подтверждающие документы: полис ОСАГО с указанием, что лицо допущено к управлению, договор аренды или безвозмездного пользования, путевой лист, доверенность, заявление об угоне и постановление о возбуждении дела.","Жалоба подается в десятидневный срок со дня получения копии постановления в вышестоящий орган или в районный суд, без госпошлины.","Оплата штрафа со скидкой, если скидка применяется, не лишает права обжаловать постановление, но уплаченный штраф может быть возвращен только после отмены постановления."],"basis":[{"lawId":"KOAP","number":"2.6.1"},{"lawId":"KOAP","number":"30.1"},{"lawId":"KOAP","number":"30.2"},{"lawId":"KOAP","number":"30.3"}],"reviewed":false,"file":"admin"},
{"id":"bailiff-claim","title":"Административное исковое заявление об оспаривании постановления или бездействия судебного пристава-исполнителя","category":"Суд","summary":"Если пристав неправильно вынес постановление или бездействует: иск в суд в течение 10 дней. Пошлина 3 000 ₽ для физлица.","notes":["Оспорить постановление, действие или бездействие судебного пристава-исполнителя можно в течение десяти дней со дня, когда вам стало известно о нарушении прав. Пропущенный по уважительной причине срок может быть восстановлен судом.","Пропуск срока не является основанием для отказа в принятии иска: причины выясняются в суде. Но если уважительной причины нет, в удовлетворении иска откажут.","Иск подается в районный суд по месту нахождения подразделения судебных приставов. Административными ответчиками указывают пристава, ГУ ФССП России по субъекту и, если нужно, взыскателя как заинтересованное лицо.","Госпошлина для физического лица по иску о признании решений и действий незаконными — 3 000 ₽, для организации 15 000 ₽. Перед судом можно подать жалобу в порядке подчиненности, но это не обязательно."],"basis":[{"lawId":"KAS","number":"218"},{"lawId":"KAS","number":"219"},{"lawId":"KAS","number":"360"},{"lawId":"KAS","number":"125"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"admin"},
{"id":"arbitr-pretension","title":"Претензия о взыскании долга по договору (досудебный порядок перед арбитражным судом)","category":"Претензии и уведомления","summary":"Обязательный шаг перед иском в арбитражный суд о взыскании денег по договору: иск можно подать через 30 дней после отправки претензии.","notes":["Споры о взыскании денег по договорам, сделкам и неосновательному обогащению передаются в арбитражный суд после принятия мер по досудебному урегулированию: по истечении тридцати календарных дней со дня направления претензии, если иное не предусмотрено договором или законом.","Направляйте претензию способом, который подтверждает отправку и дату: заказным письмом с уведомлением, курьером под расписку, через электронный документооборот. Сохраните почтовую квитанцию, опись вложения, отчет об отслеживании.","В претензии укажите договор, основание долга, сумму и расчет неустойки или процентов, реквизиты для оплаты и срок. К претензии приложите документы, подтверждающие долг: акты, накладные, счета.","Без претензии иск могут оставить без движения или вернуть: приложите ее вместе с доказательствами направления к исковому заявлению."],"basis":[{"lawId":"APK","number":"4"},{"lawId":"APK","number":"125"},{"lawId":"GK","number":"309"},{"lawId":"GK","number":"395"}],"reviewed":false,"file":"arbitration"},
{"id":"arbitr-claim","title":"Исковое заявление в арбитражный суд о взыскании долга по договору","category":"Суд","summary":"Иск организации или предпринимателя о взыскании долга и неустойки с расчетом пошлины и проверкой срока претензии.","notes":["Иск подается в арбитражный суд по месту нахождения ответчика, если договором не определена иная подсудность. Подписывает его истец или представитель с высшим юридическим образованием.","Если иск о взыскании денег по договору, до подачи нужно направить претензию и дождаться тридцати дней (отдельный шаблон). Приложите доказательства направления.","Размер пошлины считается по цене иска (долг плюс неустойка). Для долгов до 100 000 ₽ — 10 000 ₽, затем 5 % свыше 100 000 ₽ до 1 000 000 ₽ и далее по шкале статьи 333.21 Налогового кодекса.","Копии иска и приложений нужно направить ответчику заказным письмом или в электронном виде. Документы, подтверждающие это, приложите к иску."],"basis":[{"lawId":"APK","number":"125"},{"lawId":"APK","number":"126"},{"lawId":"APK","number":"4"},{"lawId":"NK","number":"333.21"},{"lawId":"GK","number":"330"}],"reviewed":false,"file":"arbitration"},
{"id":"arbitr-response","title":"Отзыв на исковое заявление (арбитражный процесс)","category":"Суд","summary":"Ответчик возражает по каждому доводу иска, ссылается на закон и доказательства, высказывается о мировом соглашении.","notes":["Ответчик обязан направить отзыв в суд и всем участникам в срок, который назначил суд в определении о принятии иска. Если отзыва нет, суд вправе рассмотреть дело по имеющимся доказательствам, а расходы могут быть отнесены на ответчика.","В отзыве нужно возразить по каждому доводу иска со ссылкой на нормы и доказательства. Укажите, предпринимались ли действия, направленные на примирение, и мнение о возможности мирового соглашения.","Отзыв направляется заказным письмом или в электронном виде. Приложите документы, подтверждающие возражения и направление отзыва истцу.","Если требуется снизить неустойку, прямо просите об этом в отзыве и объясните, почему она несоразмерна последствиям (статья 333 ГК)."],"basis":[{"lawId":"APK","number":"131"},{"lawId":"APK","number":"125"},{"lawId":"GK","number":"333"},{"lawId":"GK","number":"196"}],"reviewed":false,"file":"arbitration"},
{"id":"arbitr-order-application","title":"Заявление о вынесении судебного приказа в арбитражном суде","category":"Суд","summary":"Быстрое взыскание бесспорного денежного долга по договору до 750 000 ₽ без вызова сторон. Считает пошлину.","notes":["Судебный приказ выдается, если требование вытекает из договора и основано на документах, устанавливающих денежные обязательства, а цена не превышает 750 000 ₽; обязательные платежи и санкции — до 100 000 ₽.","Суд решает за десять дней без вызова сторон. Копия приказа высылается должнику, который в десять дней со дня получения может направить возражения: тогда приказ отменяется и требование придется заявлять в исковом порядке.","Пошлина — половина пошлины за иск, но не менее 8 000 ₽. Если приказ отменят, пошлину можно зачесть при подаче иска.","Приложите документы, подтверждающие долг: договор, акты, накладные, переписку, претензию и доказательства направления копии заявления должнику."],"basis":[{"lawId":"APK","number":"229.2"},{"lawId":"APK","number":"229.5"},{"lawId":"NK","number":"333.21"},{"lawId":"APK","number":"125"}],"reviewed":false,"file":"arbitration"},
{"id":"arbitr-appeal","title":"Апелляционная жалоба на решение арбитражного суда","category":"Суд","summary":"Обжаловать решение арбитражного суда первой инстанции в течение месяца. Подается через суд, принявший решение.","notes":["Апелляционная жалоба подается в течение месяца после принятия обжалуемого решения через арбитражный суд, который его вынес. Он направит жалобу вместе с делом в апелляцию в течение трех дней.","Пропущенный по уважительной причине срок можно восстановить, если ходатайство подано не позднее шести месяцев со дня принятия решения.","В жалобе нельзя заявлять новые требования, которые не рассматривались в первой инстанции. Опирайтесь на материалы дела и доказательства, исследованные судом.","Пошлина: 10 000 ₽ для физических лиц и 30 000 ₽ для организаций. Статус индивидуального предпринимателя для пошлины уточните по статье 333.21 Налогового кодекса и разъяснениям суда."],"basis":[{"lawId":"APK","number":"257"},{"lawId":"APK","number":"259"},{"lawId":"APK","number":"260"},{"lawId":"NK","number":"333.21"}],"reviewed":false,"file":"arbitration"},
{"id":"bankruptcy-citizen","title":"Заявление гражданина о признании его банкротом","category":"Суд","summary":"Обращение должника в арбитражный суд: с долгами не менее 500 000 ₽ и невозможностью их платить. Пошлина 10 000 ₽ и вознаграждение управляющему.","notes":["Гражданин обязан подать заявление не позднее тридцати рабочих дней, если не может платить кредиторам и общий размер долгов не менее 500 000 ₽. Подать можно и раньше, если очевидно, что исполнять обязательства не получится.","Суд принимает заявление при условии, что требования к гражданину не менее 500 000 ₽ и не исполнены в течение трех месяцев с даты, когда они должны были быть исполнены, если закон не предусматривает иное.","К заявлению прилагаются списки кредиторов и должников, опись имущества, документы о доходах и счетах, сведения о сделках за три года и о браке. На счет суда нужно внести фиксированное вознаграждение финансовому управляющему.","После реализации имущества суд освобождает гражданина от обязательств, но не от алиментов, возмещения вреда жизни и здоровью и ряда других требований. Последствия банкротства нужно обсудить с юристом заранее."],"basis":[{"lawId":"FZ127","number":"213.4"},{"lawId":"FZ127","number":"213.3"},{"lawId":"FZ127","number":"213.28"},{"lawId":"NK","number":"333.21"}],"reviewed":false,"file":"bankruptcy"},
{"id":"bankruptcy-out-of-court","title":"Заявление о признании гражданина банкротом во внесудебном порядке (через МФЦ)","category":"Суд","summary":"Бесплатное банкротство через МФЦ при долге от 25 000 до 1 000 000 ₽, если исполнительное производство окончено или выполнены другие условия.","notes":["Заявление подается в МФЦ по месту жительства или пребывания. Через МФЦ могут обратиться граждане с долгами от 25 000 до 1 000 000 ₽, если выполнено одно из условий статьи 223.2: окончено исполнительное производство из-за невозможности взыскания, пенсионный или социальный статус при отсутствии имущества, давность исполнительного документа и другие.","Процедура занимает шесть месяцев. В это время нельзя брать новые кредиты и займы. Через шесть месяцев гражданин освобождается от обязательств, указанных в заявлении, при условии, что нет оснований прекратить процедуру.","МФЦ проверяет документы, но соблюдение условий предполагается и дополнительно не проверяется, кроме особых случаев. Недостоверные сведения могут привести к отказу и ответственности.","К заявлению прилагается список всех известных кредиторов. Если долг хотя бы одному кредитору не включен, обязательство не списывается."],"basis":[{"lawId":"FZ127","number":"223.2"},{"lawId":"FZ127","number":"223.3"},{"lawId":"FZ127","number":"213.28"}],"reviewed":false,"file":"bankruptcy"},
{"id":"creditor-register-claim","title":"Заявление кредитора о включении требования в реестр требований кредиторов","category":"Суд","summary":"Кредитор заявляет долг в банкротстве должника-организации: при наблюдении в течение 30 дней после публикации, при внешнем управлении в любой момент.","notes":["При введении наблюдения кредиторы могут предъявить требования в течение тридцати календарных дней с даты опубликования сообщения. Требования, поступившие позже, рассматриваются после введения следующей процедуры.","К требованию приложите судебный акт или документы, подтверждающие обоснованность: договор, акты, накладные, расчет долга и процентов. Копии направьте должнику и арбитражному управляющему.","Суд рассматривает требование единолично без вызова сторон; при возражениях — в заседании в течение месяца. Определение о включении или отказе можно обжаловать.","Размер госпошлины для обособленных споров в банкротстве определяется статьей 333.21 Налогового кодекса: проверьте актуальный размер перед подачей."],"basis":[{"lawId":"FZ127","number":"71"},{"lawId":"FZ127","number":"100"},{"lawId":"FZ127","number":"16"},{"lawId":"APK","number":"125"}],"reviewed":false,"file":"bankruptcy"},
{"id":"debtor-deal-challenge","title":"Заявление об оспаривании сделки должника в деле о банкротстве","category":"Суд","summary":"Оспорить подозрительную сделку банкрота: неравноценную в течение года или совершенную во вред кредиторам в течение трех лет.","notes":["Сделка должника, совершенная в течение года до принятия заявления о банкротстве, может быть признана недействительной при неравноценном встречном исполнении. Сделка, совершенная в целях причинения вреда кредиторам, оспаривается в течение трех лет.","Заявление может подать арбитражный управляющий. Конкурсный кредитор или уполномоченный орган также могут обратиться, если их требования составляют более десяти процентов реестра, либо по условиям статьи 61.9.","Цель причинения вреда предполагается, если должник отвечал признакам неплатежеспособности и сделка совершена безвозмездно или с заинтересованным лицом, а также в других случаях, указанных в статье 61.2.","Если сделка признана недействительной, суд применяет последствия: имущество возвращается в конкурсную массу. Госпошлину по обособленным спорам в банкротстве проверьте по статье 333.21 Налогового кодекса."],"basis":[{"lawId":"FZ127","number":"61.2"},{"lawId":"FZ127","number":"61.9"},{"lawId":"FZ127","number":"61.6"},{"lawId":"APK","number":"125"}],"reviewed":false,"file":"bankruptcy"},
{"id":"arbitr-deferral","title":"Заявление об отсрочке или рассрочке исполнения судебного акта (арбитражный суд)","category":"Суд","summary":"Должник просит разбить выплату по решению арбитражного суда на части или отложить исполнение. Пошлина 10 000 ₽, считает ежемесячный платеж.","notes":["При наличии обстоятельств, затрудняющих исполнение, суд, выдавший исполнительный лист, по заявлению взыскателя, должника или судебного пристава вправе отсрочить или рассрочить исполнение судебного акта.","Заявление рассматривается в месячный срок в заседании с извещением взыскателя, должника и пристава. Результат — определение.","Объясните, почему нельзя исполнить сразу, и предложите реалистичный график платежей. Приложите документы о финансовом положении: баланс, выписки по счетам, справки о долгах.","Пошлина за такое заявление в арбитражном суде — 10 000 ₽ (подпункт 15 пункта 1 статьи 333.21 Налогового кодекса)."],"basis":[{"lawId":"APK","number":"324"},{"lawId":"APK","number":"325"},{"lawId":"NK","number":"333.21"}],"reviewed":false,"file":"bankruptcy"},
{"id":"crime-report","title":"Заявление о преступлении","category":"Суд","summary":"Если у вас украли имущество, обманули или причинили вред: заявление в полицию с просьбой возбудить дело и выдать документ о приеме.","notes":["Заявление о преступлении может быть устным или письменным. Письменное подписывается заявителем, анонимное поводом для возбуждения дела не служит.","Заявитель предупреждается об уголовной ответственности за заведомо ложный донос по статье 306 Уголовного кодекса, о чем делается отметка.","Сообщение обязаны принять, проверить и принять решение не позднее 3 суток, срок может быть продлен до 10 суток, а при необходимости проверок и экспертиз до 30 суток. Вам должны выдать документ о принятии заявления: талон-уведомление с датой и временем и данными принявшего.","Отказ в приеме заявления можно обжаловать прокурору или в суд по статьям 124 и 125 УПК. Подавайте заявление в двух экземплярах, чтобы на втором поставили отметку о принятии."],"basis":[{"lawId":"UPK","number":"140"},{"lawId":"UPK","number":"141"},{"lawId":"UPK","number":"144"},{"lawId":"UPK","number":"125"},{"lawId":"UK","number":"306"}],"reviewed":false,"file":"criminal"},
{"id":"victim-motion","title":"Ходатайство потерпевшего по уголовному делу","category":"Суд","summary":"Потерпевший просит следователя или суд провести действие: допросить свидетеля, назначить экспертизу, приобщить документы.","notes":["Потерпевший вправе представлять доказательства и заявлять ходатайства. Ходатайство можно заявить в любой момент производства по уголовному делу, письменное приобщается к делу.","Ходатайство заявляется дознавателю, следователю или в суд. Отклонение не лишает права заявить его снова.","Укажите, какое действие нужно провести, и объясните, как оно поможет установить обстоятельства дела. Приложите документы, которые просите приобщить.","Если ходатайство отклонено, постановление об отказе можно обжаловать прокурору, руководителю следственного органа или в суд по статье 125 УПК."],"basis":[{"lawId":"UPK","number":"42"},{"lawId":"UPK","number":"119"},{"lawId":"UPK","number":"120"},{"lawId":"UPK","number":"121"}],"reviewed":false,"file":"criminal"},
{"id":"complaint-125","title":"Жалоба в порядке статьи 125 УПК на бездействие или отказ в возбуждении уголовного дела","category":"Суд","summary":"Если полиция не принимает заявление, отказывает в возбуждении дела или бездействует: жалоба в районный суд, который рассматривает ее в течение 14 суток.","notes":["В суд можно обжаловать постановление об отказе в возбуждении дела, о прекращении дела, а также действия и бездействие следователя, дознавателя, руководителя следственного органа и прокурора, которые способны причинить ущерб правам участников или затруднить доступ к правосудию.","Жалобу вправе подать заявитель, его защитник, законный представитель или представитель, непосредственно в суд или через орган, чье решение обжалуется. Судья рассматривает ее не позднее чем через 14 суток.","Принесение жалобы не приостанавливает исполнение обжалуемого решения. По результатам суд признает действие незаконным и обязывает устранить нарушение либо оставляет жалобу без удовлетворения.","Параллельно можно подать жалобу прокурору или руководителю следственного органа в порядке статьи 124 УПК."],"basis":[{"lawId":"UPK","number":"125"},{"lawId":"UPK","number":"124"},{"lawId":"UPK","number":"144"},{"lawId":"UPK","number":"148"}],"reviewed":false,"file":"criminal"},
{"id":"criminal-civil-claim","title":"Гражданский иск в уголовном деле о возмещении вреда","category":"Суд","summary":"Потерпевший требует возместить ущерб и моральный вред прямо в уголовном деле. Пошлину платить не нужно. Считает общую сумму.","notes":["Гражданский иск о возмещении имущественного вреда, причиненного непосредственно преступлением, можно предъявить после возбуждения дела и до окончания судебного следствия в суде первой инстанции. Госпошлина не уплачивается.","Решение о признании гражданским истцом оформляется постановлением следователя, дознавателя или определением суда. По иску о моральном вреде размер определяется судом при рассмотрении дела или в порядке гражданского судопроизводства.","К иску приложите документы об ущербе: чеки, договоры, оценку, медицинские документы. Иск можно предъявлять к обвиняемому или к лицам, которые несут за него материальную ответственность.","Отказ от иска возможен до удаления суда в совещательную комнату и влечет прекращение производства по иску."],"basis":[{"lawId":"UPK","number":"44"},{"lawId":"UPK","number":"42"},{"lawId":"UPK","number":"54"},{"lawId":"GK","number":"1064"},{"lawId":"GK","number":"151"}],"reviewed":false,"file":"criminal"},
{"id":"criminal-appeal","title":"Апелляционная жалоба на приговор","category":"Суд","summary":"Обжаловать приговор районного суда в течение 15 суток: осужденному, защитнику, потерпевшему или гражданскому истцу. Проверяет срок.","notes":["Апелляционная жалоба на приговор подается в течение 15 суток со дня его постановления, а осужденным, содержащимся под стражей, — со дня вручения копии приговора. Жалоба, поданная с пропуском срока, оставляется без рассмотрения, но срок можно восстановить по уважительной причине.","Право обжалования есть у осужденного, оправданного, их защитников и законных представителей, потерпевшего, частного обвинителя и их представителей. Гражданский истец и ответчик могут обжаловать приговор в части гражданского иска.","Основания для отмены или изменения: несоответствие выводов суда обстоятельствам дела, существенное нарушение процессуального закона, неправильное применение уголовного закона, несправедливость приговора.","Жалоба подается через суд, постановивший приговор. Приложите копию приговора и копии жалобы по числу участников."],"basis":[{"lawId":"UPK","number":"389.1"},{"lawId":"UPK","number":"389.4"},{"lawId":"UPK","number":"389.6"},{"lawId":"UPK","number":"389.15"}],"reviewed":false,"file":"criminal"},
{"id":"tax-refund","title":"Заявление о возврате денежных средств с единого налогового счета","category":"Претензии и уведомления","summary":"Если на едином налоговом счете переплата: просьба вернуть положительное сальдо на банковский счет.","notes":["Вернуть можно деньги, которые формируют положительное сальдо единого налогового счета. Заявление подается в налоговый орган по месту учета по установленной форме на бумаге или в электронной форме с усиленной квалифицированной электронной подписью.","Деньги возвращаются на открытый вам счет в банке. Если сальдо отсутствует, налоговый орган направит сообщение об отказе; если его недостаточно, вернут частично.","Перед возвратом налоговый орган зачтет недоимку и пени, если они есть. Просить вернуть нужно ту сумму, которая остается после зачета.","Для отдельных налогов (например, налога на доходы по статье 227.1 и налога на профессиональный доход) предусмотрены собственные заявления о возврате."],"basis":[{"lawId":"NK","number":"79"},{"lawId":"NK","number":"11.3"},{"lawId":"NK","number":"78"}],"reviewed":false,"file":"tax"},
{"id":"tax-offset","title":"Заявление о зачете денежных средств с единого налогового счета","category":"Претензии и уведомления","summary":"Распорядиться переплатой по ЕНС: зачесть ее в счет будущего налога или в счет обязанности другого лица.","notes":["Положительным сальдо единого налогового счета можно распорядиться путем зачета: в счет обязанности другого лица по налогам, сборам, взносам, пеням, штрафам или в счет предстоящей обязанности по конкретному налогу.","Заявление подается в налоговый орган по месту учета по установленному формату в электронной форме с усиленной квалифицированной электронной подписью или через личный кабинет налогоплательщика.","В заявлении в счет предстоящей обязанности указываются источник доходов бюджета, срок уплаты и реквизиты, необходимые для определения обязанности.","Зачет возможен только в размере положительного сальдо. Если денег недостаточно, зачет выполняют частично; при отсутствии сальдо присылают сообщение об отказе."],"basis":[{"lawId":"NK","number":"78"},{"lawId":"NK","number":"11.3"},{"lawId":"NK","number":"79"}],"reviewed":false,"file":"tax"},
{"id":"tax-act-objections","title":"Возражения на акт налоговой проверки","category":"Претензии и уведомления","summary":"Несогласие с выводами проверяющих: возражения подаются в течение месяца со дня получения акта до вынесения решения. Проверяет срок.","notes":["Если вы не согласны с фактами, выводами и предложениями проверяющих, письменные возражения можно представить в течение одного месяца со дня получения акта налоговой проверки: по всему акту или по отдельным положениям.","К возражениям приложите копии документов, подтверждающих вашу позицию. Подать можно лично, по почте заказным письмом, в электронной форме по телекоммуникационным каналам связи или через личный кабинет.","Руководитель налогового органа рассмотрит акт, материалы проверки и ваши возражения и вынесет решение. Вы вправе участвовать в рассмотрении лично или через представителя, ознакомиться с материалами.","Если возражения не приняты, решение можно обжаловать в апелляционном порядке до вступления его в силу (отдельный шаблон)."],"basis":[{"lawId":"NK","number":"100"},{"lawId":"NK","number":"101"},{"lawId":"NK","number":"101.4"}],"reviewed":false,"file":"tax"},
{"id":"tax-appeal","title":"Апелляционная жалоба на решение налогового органа о привлечении к ответственности","category":"Претензии и уведомления","summary":"Обжаловать решение по итогам проверки в вышестоящий налоговый орган до вступления решения в силу. Подается через налоговый орган, вынесший решение.","notes":["Апелляционная жалоба на решение о привлечении (отказе в привлечении) к ответственности подается в вышестоящий налоговый орган через орган, который вынес решение. Тот в течение трех дней направляет ее со всеми материалами выше.","Подать жалобу можно до дня вступления решения в силу. Если жалоба подана, решение вступает в силу в необжалованной части и в части, не отмененной вышестоящим органом, со дня принятия решения по жалобе.","Пока вы не обжаловали решение в апелляционном порядке, оно вступает в силу по истечении месяца со дня вручения (пункт 9 статьи 101). После этого жалобу можно подать в течение года со дня вынесения решения как обычную.","Подача жалобы не приостанавливает исполнение решения. Для организаций и предпринимателей приостановление возможно при предоставлении банковской гарантии. До принятия решения вы вправе представить дополнительные документы."],"basis":[{"lawId":"NK","number":"138"},{"lawId":"NK","number":"139.1"},{"lawId":"NK","number":"140"},{"lawId":"NK","number":"101.2"},{"lawId":"NK","number":"101.3"}],"reviewed":false,"file":"tax"},
{"id":"tax-sanction-reduction","title":"Ходатайство о снижении налоговых санкций при наличии смягчающих обстоятельств","category":"Претензии и уведомления","summary":"Просьба уменьшить штраф налоговой проверки как минимум вдвое при тяжелых личных обстоятельствах или материальном положении. Проверяет размер.","notes":["При наличии хотя бы одного смягчающего обстоятельства штраф подлежит уменьшению не менее чем в два раза и не более чем в десять раз по сравнению с размером, установленным статьей.","Смягчающие обстоятельства: тяжелые личные или семейные обстоятельства, угроза или принуждение, зависимость, тяжелое материальное положение физического лица, иные обстоятельства, которые налоговый орган или суд признают смягчающими.","Ходатайство подавайте до принятия решения: вместе с возражениями на акт или на рассмотрении материалов проверки. Приложите документы, подтверждающие обстоятельства.","Если налоговый орган не снизил штраф, это можно оспорить в вышестоящем органе или в суде. Лицо, ранее привлекавшееся за такое же нарушение, на смягчение рассчитывать не может, штраф при этом увеличивается."],"basis":[{"lawId":"NK","number":"112"},{"lawId":"NK","number":"114"},{"lawId":"NK","number":"101"}],"reviewed":false,"file":"tax"},
{"id":"bailiff-recusal","title":"Заявление об отводе судебного пристава-исполнителя","category":"Суд","summary":"Если пристав состоит в родстве со стороной, подчинен ей или заинтересован в исходе: мотивированный отвод до начала исполнительных действий.","notes":["Пристав не может участвовать в исполнительном производстве и подлежит отводу, если он состоит в родстве или свойстве со сторонами или их представителями, подчинен или подконтролен им либо заинтересован в исходе производства.","Отвод может заявить взыскатель или должник. Он должен быть мотивирован, изложен в письменной форме и заявлен до начала совершения исполнительных действий, кроме случаев, когда о наличии оснований стало известно позже.","Вопрос об отводе пристава-исполнителя решает старший судебный пристав или его заместитель в трехдневный срок. Выносится мотивированное постановление, копия направляется вам не позднее следующего дня.","Постановление об отказе в отводе можно обжаловать вышестоящему должностному лицу или в суд."],"basis":[{"lawId":"FZ229","number":"63"},{"lawId":"FZ229","number":"64.1"}],"reviewed":false,"file":"enforcement"},
{"id":"enforcement-search","title":"Заявление взыскателя об объявлении исполнительного розыска","category":"Суд","summary":"Если пристав не нашел должника или его имущество: просьба объявить розыск. Для денежных долгов нужна сумма больше 10 000 ₽.","notes":["По исполнительным документам имущественного характера розыск должника или его имущества по заявлению взыскателя возможен, если сумма требований больше 10 000 ₽, а иные исполнительные действия не позволили установить местонахождение.","По неимущественным требованиям розыск должника возможен, если исполнение невозможно без должника. Розыск ребенка по спорам о детях объявляется по инициативе пристава или по заявлению взыскателя.","Постановление о розыске или об отказе пристав выносит в трехдневный срок. Копия направляется сторонам не позднее следующего дня.","Укажите известные сведения о должнике или имуществе: адреса, место работы, автомобиль, знакомые, соцсети. Чем больше информации, тем выше шанс найти."],"basis":[{"lawId":"FZ229","number":"65"},{"lawId":"FZ229","number":"64.1"},{"lawId":"FZ229","number":"64"}],"reviewed":false,"file":"enforcement"},
{"id":"enforcement-suspension","title":"Заявление о приостановлении исполнительного производства","category":"Суд","summary":"Просьба к приставу приостановить производство: мобилизация, участие в СВО, банкротство или смерть должника.","notes":["Пристав обязан приостановить исполнительное производство полностью или частично при наступлении обстоятельств из части 1 статьи 40: смерть должника, утрата дееспособности, призыв по мобилизации, участие в специальной военной операции, процедуры банкротства и другие.","Приложите документы, подтверждающие основание: повестку или справку военкомата, определение суда о введении процедуры банкротства, свидетельство о смерти.","Заявление рассматривается в десятидневный срок со дня поступления, результатом является постановление. Суд приостанавливает производство по другим основаниям, например при иске об освобождении имущества от ареста (статья 39).","Пока производство приостановлено, исполнительные действия не совершаются, но меры по обеспечению сохранности имущества пристав вправе принять."],"basis":[{"lawId":"FZ229","number":"40"},{"lawId":"FZ229","number":"39"},{"lawId":"FZ229","number":"64.1"},{"lawId":"FZ229","number":"69.1"}],"reviewed":false,"file":"enforcement"},
{"id":"arrest-release-suit","title":"Исковое заявление об освобождении имущества от ареста (исключении из описи)","category":"Суд","summary":"Если арестовали вещь, которая принадлежит вам, а не должнику: иск к должнику и взыскателю. Считает пошлину по стоимости.","notes":["Спор о принадлежности арестованного имущества лицом, не участвующим в деле, рассматривается по правилам искового производства. Иск предъявляется к должнику и взыскателю.","Если имущество уже реализовано, иск предъявляется еще и к его приобретателю.","С предъявлением иска об освобождении от ареста суд обязан приостановить исполнительное производство в части спорного имущества (пункт 1 части 1 статьи 39 закона об исполнительном производстве). Приложите копию иска к заявлению о приостановлении.","Докажите, что вещь ваша: договор купли-продажи, чеки, регистрация права, переписка. Госпошлина считается по стоимости имущества."],"basis":[{"lawId":"GPK","number":"442"},{"lawId":"FZ229","number":"80"},{"lawId":"FZ229","number":"39"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"enforcement"},
{"id":"enforcement-end","title":"Заявление об окончании исполнительного производства в связи с исполнением","category":"Суд","summary":"Долг выплачен полностью: просьба окончить исполнительное производство и снять аресты и запреты. Приложите платежные документы.","notes":["Исполнительное производство оканчивается в случае фактического исполнения требований, содержащихся в исполнительном документе. Приложите платежные поручения, квитанции, расписку или акт взыскателя о получении долга.","Заявление рассматривается в десятидневный срок со дня поступления, по результатам выносится постановление. После окончания пристав отменяет меры принудительного исполнения: аресты, запреты на регистрационные действия, ограничения выезда.","Если пристав не выносит постановление, это бездействие можно обжаловать в десятидневный срок вышестоящему должностному лицу или в суд (шаблон об оспаривании бездействия пристава).","Сохраните расписку взыскателя и копии платежек: они же понадобятся при споре об исполнительском сборе."],"basis":[{"lawId":"FZ229","number":"47"},{"lawId":"FZ229","number":"64.1"},{"lawId":"FZ229","number":"80"}],"reviewed":false,"file":"enforcement"},
{"id":"assignment","title":"Договор уступки права требования (цессии)","category":"Договоры","summary":"Кредитор продает или передает свое требование другому лицу: долг по займу, оплате, неустойке. С уведомлением должника.","notes":["Кредитор вправе передать свое требование другому лицу, согласие должника не нужно, если закон или договор не требуют иного. Уступка по сделке, совершенной в письменной или нотариальной форме, оформляется в той же форме.","К новому кредитору права переходят в том объеме, который был на момент уступки, включая права, обеспечивающие требование (залог, поручительство), и проценты.","Должника нужно письменно уведомить о переходе права. Пока он не уведомлен, он вправе исполнять обязательство прежнему кредитору, а риск несет новый кредитор. Первоначальный кредитор обязан передать документы и сведения по требованию.","Цедент отвечает за действительность переданного требования, но не за его неисполнение должником, если не поручился за него."],"basis":[{"lawId":"GK","number":"382"},{"lawId":"GK","number":"384"},{"lawId":"GK","number":"385"},{"lawId":"GK","number":"389"},{"lawId":"GK","number":"390"}],"reviewed":false,"file":"contracts-rights"},
{"id":"debt-transfer","title":"Соглашение о переводе долга","category":"Договоры","summary":"Долг одного человека берет на себя другой с согласия кредитора. Трехстороннее соглашение с подписью кредитора.","notes":["Перевод долга происходит по соглашению между прежним и новым должником, но с согласия кредитора. Без согласия кредитора перевод ничтожен.","В обязательствах между предпринимателями перевод можно оформить и по соглашению кредитора с новым должником. Тогда прежний и новый должник несут солидарную ответственность, если не предусмотрена субсидиарная.","К форме перевода применяются правила об уступке требования: если основной договор нотариальный или подлежит регистрации, соглашение оформляется так же.","Новый должник вправе выдвигать против требования кредитора возражения, основанные на отношениях между кредитором и прежним должником."],"basis":[{"lawId":"GK","number":"391"},{"lawId":"GK","number":"392"},{"lawId":"GK","number":"389"}],"reviewed":false,"file":"contracts-rights"},
{"id":"life-support","title":"Договор пожизненного содержания с иждивением","category":"Договоры","summary":"Человек передает недвижимость, а другой обязуется содержать его всю жизнь: жилье, питание, уход. Нотариус и регистрация обязательны.","notes":["Получатель ренты — гражданин — передает дом, квартиру, участок или иную недвижимость в собственность плательщика, а тот обязуется пожизненно содержать его с иждивением: обеспечивать жилье, питание, одежду, при необходимости уход.","Договор ренты подлежит нотариальному удостоверению, а передача недвижимости — государственной регистрации перехода права и обременения. Без этого договор недействителен.","Договор должен определять стоимость всего объема содержания. При бесплатной передаче имущества месячная стоимость содержания не может быть менее двух величин прожиточного минимума на душу населения в регионе.","Плательщик не вправе продавать, закладывать или обременять имущество без согласия получателя. Обязательство прекращается смертью получателя. При существенном нарушении получатель может потребовать вернуть имущество."],"basis":[{"lawId":"GK","number":"601"},{"lawId":"GK","number":"602"},{"lawId":"GK","number":"584"},{"lawId":"GK","number":"604"},{"lawId":"GK","number":"605"}],"reviewed":false,"file":"contracts-rights"},
{"id":"simple-partnership","title":"Договор простого товарищества (о совместной деятельности)","category":"Договоры","summary":"Двое или несколько лиц соединяют вклады для общего дела без создания юрлица: проект, бизнес, строительство. Для бизнеса только ИП и организации.","notes":["По договору простого товарищества лица соединяют вклады и действуют совместно без образования юридического лица для извлечения прибыли или иной законной цели. Вклады могут быть деньгами, имуществом, знаниями, навыками и деловой репутацией.","Если договор заключается для предпринимательской деятельности, сторонами могут быть только индивидуальные предприниматели и коммерческие организации. Обычные граждане могут объединяться для непредпринимательских целей.","Внесенное имущество, продукция и доходы — общая долевая собственность. Прибыль распределяется пропорционально вкладам, если договором не предусмотрено иное. Договор прекращается по основаниям из статьи 1050, в том числе по истечении срока.","Каждый товарищ вправе знакомиться со всей документацией. Отказ от этого права ничтожен."],"basis":[{"lawId":"GK","number":"1041"},{"lawId":"GK","number":"1042"},{"lawId":"GK","number":"1043"},{"lawId":"GK","number":"1044"},{"lawId":"GK","number":"1048"},{"lawId":"GK","number":"1050"}],"reviewed":false,"file":"contracts-rights"},
{"id":"license-agreement","title":"Лицензионный договор","category":"Договоры","summary":"Правообладатель разрешает использовать произведение, программу, изображение или товарный знак: способы, территория, срок и вознаграждение.","notes":["Лицензионный договор заключается в письменной форме, несоблюдение формы влечет недействительность. В нем нужно указать предмет (результат интеллектуальной деятельности) и способы использования, территорию, срок и вознаграждение.","Если территория не указана, лицензиат вправе использовать результат на всей территории России. Если срок не определен, договор считается заключенным на пять лет, но не более срока действия исключительного права.","Без условия о размере вознаграждения возмездный договор считается незаключенным. Безвозмездная лицензия между коммерческими организациями на всю территорию мира и весь срок действия права не допускается.","Лицензия предполагается простой (неисключительной). Для исключительной лицензии лицензиар не вправе сам использовать результат в тех пределах, в которых право предоставлено лицензиату. Сублицензия возможна только с письменного согласия лицензиара."],"basis":[{"lawId":"GK","number":"1235"},{"lawId":"GK","number":"1236"},{"lawId":"GK","number":"1237"},{"lawId":"GK","number":"1238"}],"reviewed":false,"file":"contracts-rights"},
{"id":"vehicle-power","title":"Доверенность на управление и распоряжение автомобилем","category":"Доверенности","summary":"Разрешить другому человеку ездить на вашей машине, ставить ее на учет, страховать и при необходимости продать. Простая письменная форма.","notes":["Доверенность без даты ничтожна. Если срок не указан, она действует один год со дня совершения. Для безопасности укажите точный срок.","Нотариальная форма обязательна только для сделок, требующих нотариального удостоверения, и для распоряжения правами, зарегистрированными в государственных реестрах. Для управления автомобилем и обычных действий достаточно простой письменной формы, но организации могут требовать нотариальную.","Укажите точные признаки автомобиля: марку, модель, год, VIN, государственный регистрационный знак, свидетельство о регистрации. Перечислите только те полномочия, которые действительно нужны.","Доверенность можно в любое время отменить. Если вы ее отозвали, уведомите представителя и организации, где она предъявлялась, иначе они вправе ей доверять."],"basis":[{"lawId":"GK","number":"185"},{"lawId":"GK","number":"185.1"},{"lawId":"GK","number":"186"},{"lawId":"GK","number":"187"},{"lawId":"GK","number":"188"}],"reviewed":false,"file":"powers-more"},
{"id":"flat-sale-power","title":"Доверенность на продажу квартиры","category":"Доверенности","summary":"Поручить другому человеку продать квартиру и оформить сделку в Росреестре. Обязательно удостоверяется нотариусом.","notes":["Доверенность на сделки, требующие нотариальной формы, подачу заявлений о регистрации прав и распоряжение зарегистрированными правами должна быть нотариально удостоверена. Это значит, что готовый документ нужно подписать у нотариуса.","Перечислите точно, что вправе делать представитель: подписать договор, определить цену, получить деньги, подать документы на регистрацию. Чем точнее, тем безопаснее.","Если квартира в общей собственности супругов, понадобится нотариальное согласие супруга на продажу. Если собственник один, но квартира приобретена в браке, это нужно проверять отдельно.","Доверенность можно в любой момент отменить через нотариуса; после отмены уведомите представителя и всех, кому он ее предъявлял."],"basis":[{"lawId":"GK","number":"185"},{"lawId":"GK","number":"185.1"},{"lawId":"GK","number":"186"},{"lawId":"GK","number":"556"}],"reviewed":false,"file":"powers-more"},
{"id":"org-power","title":"Доверенность от организации на представителя","category":"Доверенности","summary":"Организация поручает сотруднику или другому лицу действовать от ее имени: подписывать документы, получать товары, представлять в органах.","notes":["Доверенность от имени юридического лица выдается за подписью его руководителя или иного лица, уполномоченного уставом и законом. Печать при ее наличии ставится, но обязательной не является.","Без указания срока доверенность действует год со дня совершения. Без даты она ничтожна. Укажите дату и срок.","Перечислите конкретные полномочия. Если нужно получать товары, добавьте реквизиты договора или документа. Право передоверия возможно только если оно прямо указано в доверенности.","Для сделок, требующих нотариальной формы, и распоряжения зарегистрированными правами нужна нотариальная доверенность."],"basis":[{"lawId":"GK","number":"185"},{"lawId":"GK","number":"185.1"},{"lawId":"GK","number":"186"},{"lawId":"GK","number":"53"},{"lawId":"GK","number":"188"}],"reviewed":false,"file":"powers-more"},
{"id":"mail-docs-power","title":"Доверенность на получение документов и почты","category":"Доверенности","summary":"Поручить знакомому или родственнику забрать справки, документы и письма. Простая письменная форма, нотариус не нужен.","notes":["Для получения корреспонденции и документов достаточно простой письменной формы. Ценную корреспонденцию и некоторые документы организации могут просить получать только по нотариальной доверенности.","Доверенность на получение зарплаты, пенсии, пособий и стипендий, а также обычной корреспонденции может удостоверить организация, где вы работаете или учитесь, или администрация стационарного лечебного учреждения (статья 185.1).","Перечислите документы и органы, где представитель их получит. В почтовом отделении представителя могут попросить дополнительные сведения или удостоверить доверенность у начальника отделения.","Доверенность без даты ничтожна; если срок не указан, она действует один год."],"basis":[{"lawId":"GK","number":"185"},{"lawId":"GK","number":"185.1"},{"lawId":"GK","number":"186"},{"lawId":"GK","number":"188"}],"reviewed":false,"file":"powers-more"},
{"id":"power-revocation","title":"Заявление об отмене доверенности","category":"Доверенности","summary":"Отменить ранее выданную доверенность и уведомить представителя и третьих лиц. Отмена совершается в той же форме, что и доверенность.","notes":["Лицо, выдавшее доверенность, может в любое время ее отменить. Соглашение об отказе от этого права ничтожно. Отмена совершается в той же форме, в какой выдана доверенность, либо в нотариальной форме.","Отменить нотариальную доверенность нужно у нотариуса: он внесет сведения об отмене в реестр. Если доверенность простая письменная, достаточно письменного заявления об отмене с уведомлением представителя.","Представитель и третьи лица считаются узнавшими об отмене с момента, когда они ее получили или узнали о ней; пока этого не произошло, действия представителя могут сохранять силу, поэтому лично уведомьте тех, кому доверенность предъявлялась (банк, регистратор, ГИБДД).","Передоверие теряет силу вместе с доверенностью. Потребуйте от представителя вернуть оригинал."],"basis":[{"lawId":"GK","number":"188"},{"lawId":"GK","number":"189"},{"lawId":"GK","number":"185.1"}],"reviewed":false,"file":"powers-more"},
{"id":"equipment-lease","title":"Договор аренды оборудования","category":"Договоры","summary":"Сдать или взять в аренду станок, инструмент, технику, мебель: арендная плата, состояние при возврате, ремонт, расчет общей суммы.","notes":["По договору аренды арендодатель предоставляет имущество за плату во временное владение и пользование. В договоре должны быть данные, позволяющие определенно установить имущество: наименование, модель, серийный номер, комплектность.","Договор на срок более года, а если хотя бы одна сторона юридическое лицо, независимо от срока, заключается письменно. Если срок не определен, любая сторона вправе отказаться, предупредив за месяц.","Арендодатель отвечает за недостатки, препятствующие пользованию, даже если не знал о них. Арендатор вправе потребовать устранить недостатки, снизить плату или расторгнуть договор. Текущий ремонт, если иное не предусмотрено, делает арендатор.","При возврате арендатор должен вернуть имущество в том состоянии, в котором его получил, с учетом нормального износа. Составьте акты приема-передачи при выдаче и возврате."],"basis":[{"lawId":"GK","number":"606"},{"lawId":"GK","number":"607"},{"lawId":"GK","number":"609"},{"lawId":"GK","number":"611"},{"lawId":"GK","number":"614"},{"lawId":"GK","number":"622"}],"reviewed":false,"file":"contracts-transport"},
{"id":"crew-vehicle-lease","title":"Договор аренды транспортного средства с экипажем","category":"Договоры","summary":"Автомобиль, автобус, спецтехника с водителем: арендодатель управляет, обслуживает и ремонтирует технику, арендатор использует ее коммерчески.","notes":["По такому договору арендодатель дает транспорт за плату во временное владение и пользование и сам оказывает услуги по управлению и технической эксплуатации. Члены экипажа — работники арендодателя; они подчиняются ему по управлению и арендатору — по коммерческой эксплуатации.","Договор должен быть заключен письменно независимо от срока. Регистрация, которая нужна для аренды недвижимости, к нему не применяется.","Арендодатель в течение всего срока поддерживает транспорт в надлежащем состоянии, включая текущий и капитальный ремонт и предоставление принадлежностей.","Состав и квалификация экипажа должны соответствовать правилам и условиям договора. Правило о возобновлении договора на неопределенный срок и преимущественном праве арендатора на новый срок не применяется."],"basis":[{"lawId":"GK","number":"632"},{"lawId":"GK","number":"633"},{"lawId":"GK","number":"634"},{"lawId":"GK","number":"635"},{"lawId":"GK","number":"614"}],"reviewed":false,"file":"contracts-transport"},
{"id":"freight-contract","title":"Договор перевозки груза","category":"Договоры","summary":"Перевозчик доставляет груз из пункта А в пункт Б и выдает получателю, отправитель платит. Подача транспорта, сроки, ответственность.","notes":["Договор перевозки груза подтверждается транспортной накладной. Перевозчик обязан подать исправный транспорт, пригодный для перевозки конкретного груза, в срок, и вправе отказаться от поданных непригодных транспортных средств отправитель.","Погрузку и выгрузку выполняет транспортная организация или отправитель (получатель) в порядке, предусмотренном договором. При погрузке силами отправителя сроки должны быть указаны в договоре.","Перевозчик отвечает за несохранность груза с момента принятия до выдачи получателю, если не докажет, что утрата или повреждение произошли по причинам, которые он не мог предотвратить. Возмещение — в размере стоимости утраченного либо суммы снижения стоимости.","Груз нужно доставить в установленный срок, а при отсутствии срока — в разумный срок."],"basis":[{"lawId":"GK","number":"785"},{"lawId":"GK","number":"791"},{"lawId":"GK","number":"792"},{"lawId":"GK","number":"796"}],"reviewed":false,"file":"contracts-transport"},
{"id":"forwarding-contract","title":"Договор транспортной экспедиции","category":"Договоры","summary":"Экспедитор организует перевозку груза за вознаграждение и за счет клиента: заказывает транспорт, оформляет документы, сопровождает груз.","notes":["По договору транспортной экспедиции экспедитор за вознаграждение и за счет клиента выполняет или организует выполнение услуг, связанных с перевозкой груза: заключает договоры перевозки, получает документы, организует погрузку, страхование и таможенное оформление.","Договор заключается в письменной форме. Клиент должен выдать экспедитору доверенность, если она нужна для выполнения обязанностей.","Экспедитор отвечает за утрату, недостачу и повреждение принятого груза, если не докажет, что они произошли не по его вине. За нарушение обязательств, исполняемых третьими лицами, он отвечает как за свои, если не докажет добросовестный выбор.","Подробные правила содержатся в Федеральном законе о транспортно-экспедиционной деятельности; при необходимости стороны могут уточнить их договором."],"basis":[{"lawId":"GK","number":"801"},{"lawId":"GK","number":"802"},{"lawId":"GK","number":"803"},{"lawId":"GK","number":"804"}],"reviewed":false,"file":"contracts-transport"},
{"id":"trust-management","title":"Договор доверительного управления имуществом","category":"Договоры","summary":"Собственник передает имущество управляющему, который управляет им в интересах выгодоприобретателя за вознаграждение. До пяти лет. Проверяет статус управляющего и срок.","notes":["При передаче в доверительное управление право собственности не переходит к управляющему. Он совершает сделки от своего имени, указывая, что действует как управляющий, и управляет имуществом в интересах учредителя или указанного им выгодоприобретателя.","Доверительным управляющим может быть только индивидуальный предприниматель или коммерческая организация (кроме унитарного предприятия); в случаях, указанных в законе, — гражданин или некоммерческая организация. Управляющий не может быть выгодоприобретателем.","Договор заключается на срок не более пяти лет. В нем нужно указать состав имущества, имя учредителя и выгодоприобретателя, размер и форму вознаграждения и срок. Деньги не могут быть самостоятельным объектом.","Если иное не предусмотрено, после окончания срока договор считается продленным на тот же срок на тех же условиях, пока никто не заявит о прекращении."],"basis":[{"lawId":"GK","number":"1012"},{"lawId":"GK","number":"1013"},{"lawId":"GK","number":"1015"},{"lawId":"GK","number":"1016"},{"lawId":"GK","number":"1017"},{"lawId":"GK","number":"1024"}],"reviewed":false,"file":"contracts-transport"},
{"id":"llc-sole-founder-decision","title":"Решение единственного учредителя о создании ООО","category":"Договоры","summary":"Один человек создает общество: наименование, адрес, уставный капитал не менее 10 000 ₽, срок оплаты до четырех месяцев, директор.","notes":["Если общество учреждается одним лицом, решение об учреждении он принимает единолично. Оно должно определять наименование, место нахождения, размер уставного капитала, порядок и сроки его оплаты, размер и номинальную стоимость доли учредителя, устав или типовой устав, избрание органов управления.","Уставный капитал составляется из номинальной стоимости долей и должен быть не менее 10 000 ₽. Оплатить долю нужно полностью в срок, не превышающий четырех месяцев с момента государственной регистрации. Освободить учредителя от оплаты нельзя.","Общество вправе действовать на основании типового устава, утвержденного уполномоченным органом, либо на основании собственного устава. Единоличный исполнительный орган (директор) избирается на срок, который определяет устав.","Решение подписывается учредителем и подается вместе с заявлением о государственной регистрации. Подлинность подписи заявителя может потребовать нотариус."],"basis":[{"lawId":"FZ14","number":"11"},{"lawId":"FZ14","number":"12"},{"lawId":"FZ14","number":"14"},{"lawId":"FZ14","number":"16"},{"lawId":"FZ14","number":"40"}],"reviewed":false,"file":"corporate"},
{"id":"llc-founding-agreement","title":"Договор об учреждении общества с ограниченной ответственностью","category":"Договоры","summary":"Два учредителя договариваются о создании ООО: размер капитала, доли, сроки оплаты. Считает номинальную стоимость долей.","notes":["Учредители заключают в письменной форме договор об учреждении общества, определяющий порядок их совместной деятельности по созданию общества, размер уставного капитала, размер и номинальную стоимость доли каждого, размер, порядок и сроки оплаты долей. Он не является учредительным документом.","Размер уставного капитала — не менее 10 000 ₽. Доля оплачивается полностью в срок, не превышающий четырех месяцев с момента государственной регистрации, и по цене не ниже номинальной стоимости.","Учредители несут солидарную ответственность по обязательствам, связанным с учреждением и возникшим до регистрации. Общество отвечает по этим обязательствам, только если общее собрание последующе их одобрит.","Решения об учреждении принимаются собранием учредителей, а органы управления избираются большинством не менее трех четвертей голосов от общего числа голосов учредителей."],"basis":[{"lawId":"FZ14","number":"11"},{"lawId":"FZ14","number":"14"},{"lawId":"FZ14","number":"16"},{"lawId":"FZ14","number":"12"}],"reviewed":false,"file":"corporate"},
{"id":"llc-exit-statement","title":"Заявление участника о выходе из общества с ограниченной ответственностью","category":"Договоры","summary":"Участник выходит из ООО, передавая долю обществу, если это разрешает устав. Нотариальное заявление, выплата действительной стоимости через три месяца.","notes":["Участник вправе выйти из общества путем отчуждения доли обществу независимо от согласия других участников, если это предусмотрено уставом. Без такого права в уставе выйти можно только продав долю другим лицам.","Заявление о выходе должно быть нотариально удостоверено по правилам удостоверения сделок. Нотариус в течение двух рабочих дней подает заявление о внесении изменений в ЕГРЮЛ и передает обществу заявление и копию.","С момента получения заявления доля переходит к обществу. Общество обязано выплатить действительную стоимость доли (или выдать имущество такой же стоимости) в течение трех месяцев, если иной срок не установлен уставом, при условии что оно вправе выплачивать.","До выхода проверьте, что в уставе есть право на выход, и закройте возникшие обязательства: долги общества перед вами или ваши перед обществом."],"basis":[{"lawId":"FZ14","number":"26"},{"lawId":"FZ14","number":"23"},{"lawId":"FZ14","number":"14"}],"reviewed":false,"file":"corporate"},
{"id":"llc-share-sale","title":"Договор купли-продажи доли в уставном капитале ООО","category":"Договоры","summary":"Продажа доли участником другому лицу с учетом преимущественного права. Обязательное нотариальное удостоверение, иначе сделка недействительна.","notes":["Сделка по отчуждению доли в уставном капитале ООО подлежит нотариальному удостоверению путем составления одного документа, подписанного сторонами. Несоблюдение нотариальной формы влечет недействительность.","Доля переходит к приобретателю с момента внесения записи в ЕГРЮЛ. Нотариус сам подает заявление в течение двух рабочих дней после удостоверения.","Участники общества имеют преимущественное право покупки доли по цене предложения третьему лицу. Продавец обязан письменно известить участников и общество; право используется в течение 30 дней, если устав не предусматривает иное. Если не воспользуются, доля продается третьему лицу.","Доля может быть отчуждена до полной оплаты только в той части, в которой она оплачена. Нотариус проверит полномочия продавца и оплату доли."],"basis":[{"lawId":"FZ14","number":"21"},{"lawId":"FZ14","number":"14"},{"lawId":"FZ14","number":"15"},{"lawId":"GK","number":"454"}],"reviewed":false,"file":"corporate"},
{"id":"llc-meeting-protocol","title":"Протокол общего собрания участников ООО","category":"Договоры","summary":"Оформить решения собрания участников: присутствующие, повестка, голосование. Считает долю голосов «за» и проверяет принятие решения.","notes":["О проведении собрания участников уведомляют не позднее чем за 30 дней, указывая способ принятия решений, дату, время и место, повестку дня. Собрание вправе принимать решения только по вопросам повестки, если не присутствуют все участники.","Большинство голосов определяется от общего числа голосов участников, а не от присутствующих: обычные решения принимаются большинством голосов от общего числа голосов участников. Решения по вопросам, отнесенным к исключительной компетенции, принимают двумя третями голосов или единогласно.","Перед собранием проводится регистрация. Незарегистрировавшийся участник не вправе голосовать. Председательствует директор или избранный участник; результаты голосования и принятые решения заносятся в протокол.","Протокол подписывается председательствующим и секретарем. Решения собрания можно подтвердить нотариально или иным способом, предусмотренным уставом."],"basis":[{"lawId":"FZ14","number":"36"},{"lawId":"FZ14","number":"37"},{"lawId":"FZ14","number":"33"},{"lawId":"FZ14","number":"34"}],"reviewed":false,"file":"corporate"},
{"id":"real-estate-gift","title":"Договор дарения недвижимого имущества между гражданами","category":"Договоры","summary":"Безвозмездная передача квартиры, дома, участка или доли другому человеку. Нотариальное удостоверение между гражданами и регистрация права в Росреестре.","notes":["Договор дарения недвижимого имущества между гражданами подлежит нотариальному удостоверению. Затем нужно зарегистрировать переход права собственности в Росреестре.","Дарение предполагает безвозмездность: если есть встречная передача вещи или обязательство, договор не признается дарением. Обещание подарить все имущество без указания конкретного предмета ничтожно.","Договор, предусматривающий передачу дара после смерти дарителя, ничтожен: в таком случае нужно составить завещание или наследственный договор.","Даритель вправе отменить дарение, если одаряемый покушался на жизнь дарителя или его семьи либо умышленно причинил телесные повреждения. Нужно проверить согласие супруга, если имущество общее."],"basis":[{"lawId":"GK","number":"572"},{"lawId":"GK","number":"574"},{"lawId":"GK","number":"578"},{"lawId":"GK","number":"573"}],"reviewed":false,"file":"housing-final"},
{"id":"preliminary-sale","title":"Предварительный договор купли-продажи недвижимости","category":"Договоры","summary":"Стороны обязуются заключить основной договор в будущем: условия, срок, цена, обеспечительный платеж. Ничтожен без письменной формы.","notes":["Предварительный договор заключается в форме, установленной для основного договора, а если такая не установлена, то в письменной форме. Несоблюдение формы влечет его ничтожность.","Он должен содержать условия, позволяющие установить предмет, и условия основного договора, по которым нужно достичь соглашения. В нем указывается срок заключения основного договора; если срока нет, основной договор заключается в течение года.","Если сторона уклоняется от заключения основного договора, другая вправе потребовать понудить его заключить в течение шести месяцев с момента, когда обязательство должно было быть исполнено.","Деньги, которые передаются в обеспечение, оформляйте как задаток: он засчитывается в цену, а при неисполнении по вине передавшего остается у получившего, при вине получателя возвращается в двойном размере."],"basis":[{"lawId":"GK","number":"429"},{"lawId":"GK","number":"380"},{"lawId":"GK","number":"445"},{"lawId":"GK","number":"550"}],"reviewed":false,"file":"housing-final"},
{"id":"residence-termination-suit","title":"Исковое заявление о признании утратившим право пользования жилым помещением","category":"Суд","summary":"Собственник просит суд признать бывшего члена семьи или постороннего человека утратившим право пользования жильем. Пошлина 3 000 ₽.","notes":["Право пользования жильем у членов семьи собственника производно от права собственника. При прекращении семейных отношений оно не сохраняется, если иное не установлено соглашением (часть 4 статьи 31 Жилищного кодекса).","Суд учитывает, что у бывшего члена семьи нет другого жилья или он не может его обеспечить: тогда право пользования может быть сохранено на определенный срок. Приложите доказательства: выписку из ЕГРН, справку о регистрации, акты, свидетельства.","Собственник вправе требовать устранения любых нарушений своего права, даже если они не связаны с лишением владения (статья 304 ГК). Решение суда направляется в орган регистрационного учета.","Государственная пошлина по неимущественному требованию для физических лиц — 3 000 ₽. Иск подается в суд по месту жительства ответчика или месту нахождения жилья."],"basis":[{"lawId":"JK","number":"31"},{"lawId":"GK","number":"304"},{"lawId":"GK","number":"288"},{"lawId":"GPK","number":"131"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"housing-final"},
{"id":"ddu-defects-claim","title":"Претензия застройщику о недостатках квартиры (договор долевого участия)","category":"Претензии и уведомления","summary":"Недостатки обнаружены в гарантийный срок: потребовать устранения, уменьшения цены или возмещения расходов. Считает возможную неустойку.","notes":["Если квартира построена с отступлениями от договора или обязательных требований, участник долевого строительства вправе по своему выбору потребовать безвозмездного устранения недостатков в разумный срок, соразмерного уменьшения цены или возмещения расходов на устранение.","Требования предъявляются письменно с указанием выявленных недостатков, если они обнаружены в гарантийный срок. Гарантийный срок на объект — не менее трех лет, на технологическое и инженерное оборудование — не менее трех лет, на отделку — не менее года.","При нарушении сроков устранения недостатков застройщик платит неустойку: 1/300 ставки за каждый день просрочки от стоимости работ по устранению, а гражданину-потребителю — в двойном размере, но не более стоимости расходов.","При существенных недостатках или неустранении в разумный срок можно отказаться от договора и потребовать возврата денег. Положения договора об освобождении застройщика от ответственности ничтожны."],"basis":[{"lawId":"FZ214","number":"7"},{"lawId":"FZ214","number":"8"},{"lawId":"GK","number":"330"}],"reviewed":false,"file":"claims-final"},
{"id":"ddu-transfer-act","title":"Передаточный акт квартиры по договору долевого участия","category":"Акты","summary":"Акт приема-передачи квартиры от застройщика участнику: характеристики, показания счетчиков, ключи, замечания к качеству.","notes":["Передача объекта оформляется передаточным актом, в котором указываются дата передачи, основные характеристики помещения и другая информация по усмотрению сторон. Передача возможна не ранее разрешения на ввод в эксплуатацию.","До подписания акта вы вправе потребовать составления акта о несоответствии квартиры требованиям качества и отказаться от подписания передаточного акта, пока застройщик не выполнит свои обязанности по устранению недостатков.","Подписывая акт без замечаний, вы подтверждаете, что объект соответствует договору, но гарантийные права сохраняются. Указывайте недостатки в акте или в приложении, фиксируйте показания счетчиков и ключи.","Вместе с квартирой застройщик обязан передать инструкцию по эксплуатации объекта (часть 1.1 статьи 7)."],"basis":[{"lawId":"FZ214","number":"8"},{"lawId":"FZ214","number":"7"},{"lawId":"FZ214","number":"4"}],"reviewed":false,"file":"claims-final"},
{"id":"rent-debt-claim","title":"Претензия арендатору о задолженности по арендной плате","category":"Претензии и уведомления","summary":"Арендатор не платит: требование погасить долг по аренде, неустойку и пени с расчетом общей суммы.","notes":["Арендатор обязан своевременно вносить арендную плату в порядке и сроки, установленные договором. При существенном нарушении сроков арендодатель вправе потребовать досрочного внесения платы за срок, не более двух сроков подряд, если договором не предусмотрено иное.","Если арендатор не вернул имущество или вернул несвоевременно, арендодатель вправе потребовать плату за все время просрочки, а при недостаточности — возмещения убытков.","Неустойку можно требовать, если она предусмотрена договором или законом. Проценты за пользование чужими деньгами начисляются по ключевой ставке за период просрочки.","Направьте претензию способом, подтверждающим отправку. Если спор арбитражный, иск можно подать через 30 дней после направления претензии."],"basis":[{"lawId":"GK","number":"614"},{"lawId":"GK","number":"622"},{"lawId":"GK","number":"330"},{"lawId":"GK","number":"395"}],"reviewed":false,"file":"claims-final"},
{"id":"security-deposit-claim","title":"Претензия о возврате обеспечительного платежа","category":"Претензии и уведомления","summary":"Договор аренды закончился, а залог не вернули: потребовать вернуть обеспечительный платеж и проценты за просрочку.","notes":["Обеспечительный платеж засчитывается в счет обязательства при наступлении предусмотренных договором обстоятельств. Если они не наступили в срок или обеспеченное обязательство прекратилось, платеж подлежит возврату.","На сумму обеспечительного платежа проценты за пользование (статья 317.1) не начисляются, если иное не предусмотрено договором. Но за просрочку его возврата можно требовать проценты по статье 395 ГК.","Арендодатель вправе удержать из платежа только документально подтвержденные суммы: долг по аренде, ущерб имуществу по акту. Потребуйте расчет удержаний.","Приложите договор, платежный документ о внесении платежа, акт возврата имущества."],"basis":[{"lawId":"GK","number":"381.1"},{"lawId":"GK","number":"395"},{"lawId":"GK","number":"622"},{"lawId":"GK","number":"614"}],"reviewed":false,"file":"claims-final"},
{"id":"lease-return-act","title":"Акт возврата арендованного имущества","category":"Акты","summary":"Арендатор возвращает имущество арендодателю: состояние, комплектность, замечания и расчеты. Подтверждает прекращение аренды.","notes":["При прекращении договора арендатор обязан вернуть имущество в том состоянии, в котором он его получил, с учетом нормального износа или в состоянии, обусловленном договором. Сравните с актом приема-передачи при выдаче.","Если арендатор вернул имущество несвоевременно, арендодатель вправе потребовать арендную плату за все время просрочки, а при недостаточности — убытки; если есть неустойка, убытки взыскиваются сверх нее.","Зафиксируйте в акте состояние, повреждения, комплектность, показания счетчиков и ключи. Отметьте, нет ли взаимных претензий и как будет возвращен обеспечительный платеж.","Сохраняйте фото и видео возврата: они помогут при споре об ущербе."],"basis":[{"lawId":"GK","number":"622"},{"lawId":"GK","number":"611"},{"lawId":"GK","number":"614"}],"reviewed":false,"file":"claims-final"},
{"id":"supplier-quality-claim","title":"Претензия поставщику о ненадлежащем качестве товара","category":"Претензии и уведомления","summary":"Покупатель-организация получила товар с недостатками: просит устранить, уменьшить цену, заменить или вернуть деньги.","notes":["Если недостатки не были оговорены, покупатель вправе по выбору требовать соразмерного уменьшения цены, безвозмездного устранения недостатков в разумный срок или возмещения расходов на их устранение.","При существенных нарушениях (неустранимые или проявляющиеся вновь недостатки) можно отказаться от договора и потребовать возврата денег либо замены товара.","Поставщик, получив уведомление о недостатках, может без промедления заменить товар. Направляйте претензию способом, подтверждающим отправку, и приложите акт о недостатках, накладную, фото.","При споре в арбитраже иск можно подать через 30 дней после направления претензии."],"basis":[{"lawId":"GK","number":"475"},{"lawId":"GK","number":"518"},{"lawId":"GK","number":"476"},{"lawId":"GK","number":"309"}],"reviewed":false,"file":"claims-final2"},
{"id":"contract-defects-claim","title":"Претензия подрядчику о недостатках выполненной работы","category":"Претензии и уведомления","summary":"Результат работ по договору подряда с недостатками: потребовать устранения, уменьшения цены, возмещения расходов или отказаться от договора.","notes":["При отступлениях от договора и недостатках заказчик вправе по своему выбору потребовать безвозмездного устранения в разумный срок, соразмерного уменьшения цены или возмещения своих расходов на устранение, если договор разрешает ему устранять недостатки самому.","Если недостатки не устранены в разумный срок или существенны и неустранимы, заказчик вправе отказаться от договора и потребовать возмещения убытков. Подрядчик вправе вместо устранения выполнить работу заново.","Зафиксируйте недостатки актом, фотографиями, заключением эксперта. Для результатов работ гарантийные сроки определяются договором или законом.","Условие об освобождении подрядчика от ответственности не действует, если недостатки возникли по его вине."],"basis":[{"lawId":"GK","number":"723"},{"lawId":"GK","number":"720"},{"lawId":"GK","number":"737"},{"lawId":"GK","number":"309"}],"reviewed":false,"file":"claims-final2"},
{"id":"service-prepay-refund-claim","title":"Претензия о возврате денег за услугу при отказе от договора","category":"Претензии и уведомления","summary":"Потребитель отказывается от услуги и просит вернуть предоплату за вычетом фактически понесенных расходов. Считает возврат.","notes":["Потребитель вправе отказаться от исполнения договора об оказании услуг в любое время при условии оплаты исполнителю фактически понесенных им расходов, связанных с исполнением обязательств по договору.","Деньги подлежат возврату в десятидневный срок со дня предъявления требования. За просрочку исполнитель платит неустойку, размер которой определяется статьей 28 Закона.","Расходы должен подтвердить сам исполнитель: потребуйте документы. Условия договора, ущемляющие права потребителя (например, невозвратность предоплаты), недействительны.","Отправьте претензию заказным письмом или передайте с отметкой о принятии; к претензии приложите договор и квитанции об оплате."],"basis":[{"lawId":"ZOZPP","number":"32"},{"lawId":"ZOZPP","number":"31"},{"lawId":"ZOZPP","number":"28"},{"lawId":"ZOZPP","number":"13"}],"reviewed":false,"file":"claims-final2"},
{"id":"goods-exchange-claim","title":"Заявление об обмене или возврате товара надлежащего качества","category":"Претензии и уведомления","summary":"Товар не подошел по размеру, цвету или комплектации: обмен в течение 14 дней, а если такого нет, возврат денег. Проверяет срок.","notes":["Потребитель вправе обменять непродовольственный товар надлежащего качества на аналогичный, если он не подошел по форме, габаритам, фасону, расцветке, размеру или комплектации. Срок: четырнадцать дней, не считая дня покупки.","Товар не должен быть в употреблении; нужно сохранить товарный вид, потребительские свойства, пломбы и ярлыки, а также иметь чек или иной документ об оплате. Отсутствие чека не лишает права ссылаться на свидетелей.","Если аналогичного товара нет в продаже, потребитель вправе отказаться от договора и потребовать возврата денег: они возвращаются в течение трех дней со дня возврата товара.","Перечень товаров, не подлежащих обмену, утверждается Правительством (например, лекарства, белье, парфюмерия)."],"basis":[{"lawId":"ZOZPP","number":"25"},{"lawId":"ZOZPP","number":"18"}],"reviewed":false,"file":"claims-final2"},
{"id":"flood-act","title":"Акт о заливе квартиры","category":"Акты","summary":"Зафиксировать залив для управляющей компании или суда: дата, причина, пострадавшее имущество, подписи комиссии и собственника.","notes":["Акт составляет управляющая организация с участием собственника пострадавшей квартиры и представителя виновной стороны. Если управляющая организация отказывается, составьте акт с двумя соседями и сфотографируйте повреждения.","Управляющая организация обеспечивает благоприятные и безопасные условия проживания и надлежащее содержание общего имущества дома. Если залив произошел из-за общего имущества, отвечает она; если из квартиры соседа — собственник этой квартиры.","В акте подробно описывайте повреждения: какие помещения, площадь, материалы, состояние. Приложите фото и видео. Размер ущерба подтверждается оценкой.","Акт — основа для претензии и иска о возмещении ущерба; направьте его причинителю вреда и в управляющую организацию."],"basis":[{"lawId":"JK","number":"161"},{"lawId":"JK","number":"36"},{"lawId":"GK","number":"1064"}],"reviewed":false,"file":"claims-final2"},
{"id":"loan-pledge","title":"Договор займа с залогом движимого имущества","category":"Договоры","summary":"Заем под проценты или без, обеспеченный залогом автомобиля или оборудования. Считает проценты за срок и описывает порядок обращения взыскания.","notes":["Договор займа между гражданами заключен с момента передачи денег. Если займодавец — гражданин, лучше оформлять передачу распиской или платежом, чтобы доказать факт займа.","Договор займа между гражданами на сумму до 100 000 ₽ предполагается беспроцентным, если проценты не оговорены. Размер процентов можно установить в договоре; иначе применяются проценты по ключевой ставке.","Договор залога заключается в простой письменной форме, а несоблюдение правил влечет недействительность. В нем нужно указать предмет залога, существо, размер и срок исполнения обеспечиваемого обязательства (можно сослаться на договор займа).","Залог недвижимости (ипотека) оформляется по отдельным правилам с государственной регистрацией, поэтому этот шаблон предназначен для движимого имущества. Для автомобиля можно дополнительно зарегистрировать уведомление о залоге в реестре."],"basis":[{"lawId":"GK","number":"807"},{"lawId":"GK","number":"809"},{"lawId":"GK","number":"810"},{"lawId":"GK","number":"334"},{"lawId":"GK","number":"339"}],"reviewed":false,"file":"contracts-final"},
{"id":"sale-instalment","title":"Договор купли-продажи с рассрочкой платежа","category":"Договоры","summary":"Покупатель получает товар сразу, а платит частями. Считает размер ежемесячного платежа и описывает последствия просрочки.","notes":["Договор с рассрочкой считается заключенным, если в нем указаны цена товара, порядок, сроки и размеры платежей. Без этих условий договор не заключен.","Если покупатель не внес очередной платеж за переданный товар, продавец вправе (если иное не предусмотрено договором) отказаться от договора и потребовать возврата товара, за исключением случая, когда уже получено больше половины цены.","До полной оплаты товар, проданный в кредит, считается находящимся в залоге у продавца, если договором не предусмотрено иное (статья 488). Это защищает продавца, но не требует отдельного договора залога.","Составьте график платежей и передавайте товар по акту. Для автомобилей и недвижимости действуют дополнительные требования регистрации."],"basis":[{"lawId":"GK","number":"489"},{"lawId":"GK","number":"488"},{"lawId":"GK","number":"454"},{"lawId":"GK","number":"309"}],"reviewed":false,"file":"contracts-final"},
{"id":"design-works","title":"Договор подряда на проектные работы","category":"Договоры","summary":"Разработка проекта дома, перепланировки, дизайн-проекта: задание, этапы, согласование, права на документацию и ответственность за недостатки.","notes":["По такому договору подрядчик по заданию заказчика разрабатывает техническую документацию и (или) выполняет изыскательские работы, а заказчик принимает и оплачивает результат. Заказчик обязан передать задание и исходные данные.","Подрядчик соблюдает требования задания и вправе отступить от них только с согласия заказчика. Он согласует готовую документацию с заказчиком и при необходимости вместе с ним с государственными органами; не вправе передавать документацию третьим лицам без согласия заказчика.","Подрядчик отвечает за недостатки документации, включая обнаруженные при строительстве, и за изыскательские работы; он должен безвозмездно переделать документацию и возместить убытки, если не докажет, что недостатки возникли по вине заказчика.","Права на проект: заказчик вправе использовать документацию для строительства в объеме, установленном договором; исключительное право можно передать отдельно."],"basis":[{"lawId":"GK","number":"758"},{"lawId":"GK","number":"759"},{"lawId":"GK","number":"760"},{"lawId":"GK","number":"761"},{"lawId":"GK","number":"762"}],"reviewed":false,"file":"contracts-final"},
{"id":"furniture-order","title":"Договор на изготовление мебели по индивидуальному заказу","category":"Договоры","summary":"Мебельная мастерская делает кухню, шкаф или стол по размерам заказчика: материалы, этапы оплаты, сроки, гарантия.","notes":["Если исполнитель делает мебель на заказ гражданину как предприниматель, к договору применяются правила о бытовом подряде и законодательство о защите прав потребителей. Подрядчик не вправе навязывать дополнительные работы.","Заказчик вправе в любое время до сдачи работы отказаться от договора, оплатив часть работы, выполненную до отказа, и возместив расходы. Цена работы определяется соглашением, платеж — после окончательной сдачи, а аванс — с согласия заказчика.","Опишите изделие подробно: размеры, материалы, фурнитуру, цвет, эскиз или чертеж. Приложите эскиз и спецификацию. Если подрядчик использует свои материалы, он отвечает за их качество.","При недостатках потребитель вправе требовать устранения, уменьшения цены или отказаться от договора. Сохраните чек, договор и фото готового изделия."],"basis":[{"lawId":"GK","number":"702"},{"lawId":"GK","number":"730"},{"lawId":"GK","number":"731"},{"lawId":"GK","number":"735"},{"lawId":"GK","number":"739"}],"reviewed":false,"file":"contracts-final"},
{"id":"author-commission","title":"Договор авторского заказа","category":"Договоры","summary":"Автор создает произведение по заказу: текст, фото, дизайн, музыку. Срок, гонорар, права: исключительное право или лицензия.","notes":["Автор обязуется по заказу создать произведение науки, литературы или искусства. Договор является возмездным, если не предусмотрено иное. Материальный носитель передается заказчику в собственность, если не согласовано иное.","Договор может предусматривать отчуждение исключительного права на будущее произведение или предоставление права использования в установленных пределах; тогда применяются правила об отчуждении права или лицензии.","Срок исполнения обязателен: договор, не позволяющий определить срок, не считается заключенным. Если срок наступил, автор вправе получить льготный срок в одну четвертую срока при уважительных причинах; по истечении заказчик может отказаться от договора.","Для использования произведения заказчиком по лицензии нужно указать способы, территорию и срок, иначе действуют ограничения закона."],"basis":[{"lawId":"GK","number":"1288"},{"lawId":"GK","number":"1289"},{"lawId":"GK","number":"1286"},{"lawId":"GK","number":"1234"}],"reviewed":false,"file":"contracts-final"},
{"id":"land-lease","title":"Договор аренды земельного участка","category":"Договоры","summary":"Сдать или взять в аренду участок: кадастровый номер, цель использования, арендная плата. Договор на год и больше регистрируется.","notes":["Земельный участок может быть передан в аренду в соответствии с гражданским законодательством и Земельным кодексом. В договоре нужны данные, позволяющие определенно установить участок: кадастровый номер, адрес, площадь, категория, разрешенное использование.","Договор аренды недвижимости подлежит государственной регистрации, если иное не установлено законом. Договор на срок более года, а если сторона юридическое лицо — независимо от срока, заключается в письменной форме.","Если срок не определен, договор считается заключенным на неопределенный срок, и любая сторона вправе отказаться от него, предупредив за три месяца для недвижимости.","Арендная плата может быть фиксированной или в иной форме; пересматривается по соглашению не чаще одного раза в год. Для земель государственной и муниципальной собственности есть особые правила и расчет арендной платы."],"basis":[{"lawId":"ZK","number":"22"},{"lawId":"GK","number":"606"},{"lawId":"GK","number":"607"},{"lawId":"GK","number":"609"},{"lawId":"GK","number":"610"},{"lawId":"GK","number":"614"}],"reviewed":false,"file":"leases-corporate"},
{"id":"sublease","title":"Договор субаренды","category":"Договоры","summary":"Арендатор сдает арендованное помещение или имущество другому лицу с согласия арендодателя. Срок субаренды не больше срока основной аренды.","notes":["Арендатор вправе с согласия арендодателя сдавать арендованное имущество в субаренду. Без согласия арендодателя субаренда недопустима: он вправе потребовать расторжения основного договора и убытков.","Договор субаренды не может быть заключен на срок, превышающий срок основного договора аренды. К субаренде применяются правила об аренде, если иное не установлено законом.","Приложите согласие арендодателя и копию основного договора. Субарендатор вправе проверить права арендатора на имущество и срок аренды.","Если основной договор прекращается, прекращается и субаренда. Предусмотрите порядок, как субарендатор будет уведомлен."],"basis":[{"lawId":"GK","number":"615"},{"lawId":"GK","number":"609"},{"lawId":"GK","number":"614"},{"lawId":"GK","number":"622"}],"reviewed":false,"file":"leases-corporate"},
{"id":"finance-lease","title":"Договор финансовой аренды (лизинга)","category":"Договоры","summary":"Лизингодатель покупает выбранное арендатором имущество у продавца и сдает ему в пользование за плату. Риски, график платежей, уведомление продавца.","notes":["По договору лизинга арендодатель обязуется приобрести указанное арендатором имущество у определенного им продавца и предоставить его арендатору за плату во временное владение и пользование. Арендодатель не отвечает за выбор имущества и продавца, если выбирал арендатор.","Предметом могут быть любые непотребляемые вещи, кроме земельных участков и природных объектов. Арендодатель обязан уведомить продавца, что имущество предназначено для передачи определенному арендатору.","Имущество передается продавцом непосредственно арендатору, если договором не установлено иное. Риск случайной гибели или порчи переходит к арендатору с момента передачи.","Арендатор вправе предъявлять продавцу требования, вытекающие из договора купли-продажи, в частности по качеству и срокам; в отношениях с продавцом арендодатель и арендатор — солидарные кредиторы. Особенности регулирует закон о лизинге."],"basis":[{"lawId":"GK","number":"665"},{"lawId":"GK","number":"666"},{"lawId":"GK","number":"667"},{"lawId":"GK","number":"668"},{"lawId":"GK","number":"669"},{"lawId":"GK","number":"670"}],"reviewed":false,"file":"leases-corporate"},
{"id":"llc-large-deal","title":"Решение общего собрания участников ООО о согласии на крупную сделку","category":"Договоры","summary":"Если сделка на 25 % и более балансовой стоимости активов: нужно согласие собрания. Проверяет порог и описывает условия сделки.","notes":["Крупной считается сделка (или несколько взаимосвязанных), выходящая за пределы обычной хозяйственной деятельности и связанная с приобретением, отчуждением имущества (включая заем, кредит, залог, поручительство) либо передачей имущества в пользование, если ее стоимость составляет 25 и более процентов балансовой стоимости активов общества.","Согласие дает общее собрание участников (при совете директоров часть вопросов может отнести устав к нему). В решении нужно указать сторону сделки, выгодоприобретателя, цену, предмет и существенные условия или порядок их определения.","Согласие действует год, если срок не указан, и может быть предварительным или последующим одобрением. Сделка, совершенная без согласия, может быть признана недействительной по иску общества или участника с долей не менее одного процента.","Правила не применяются к обществу из одного участника, который одновременно директор."],"basis":[{"lawId":"FZ14","number":"46"},{"lawId":"FZ14","number":"37"},{"lawId":"GK","number":"173.1"}],"reviewed":false,"file":"leases-corporate"},
{"id":"llc-info-request","title":"Требование участника ООО о предоставлении информации и документов","category":"Претензии и уведомления","summary":"Участник общества просит ознакомиться с бухгалтерскими документами, протоколами, договорами и получить копии.","notes":["Участники общества вправе получать информацию о деятельности общества и знакомиться с его документами бухгалтерского учета и иной документацией в порядке, установленном уставом. Требование нужно направить письменно, лучше способом, подтверждающим вручение.","Общество обязано хранить документы (устав, протоколы, договоры, бухгалтерская отчетность, списки аффилированных лиц) и по требованию участника предоставлять их для ознакомления, а копии — за разумную плату, не превышающую расходов.","Укажите конкретные документы и период. Чем точнее запрос, тем сложнее отказать. Общество не вправе ограничивать участника без оснований; отказ можно обжаловать в суде.","Срок предоставления определяется уставом и законом. Если срока нет, укажите разумный (например, семь рабочих дней)."],"basis":[{"lawId":"FZ14","number":"8"},{"lawId":"FZ14","number":"50"},{"lawId":"FZ14","number":"36"}],"reviewed":false,"file":"leases-corporate"},
{"id":"civil-cassation","title":"Кассационная жалоба по гражданскому делу","category":"Суд","summary":"Обжаловать вступившее в силу решение или апелляционное определение в кассационный суд общей юрисдикции. Срок три месяца, пошлина 5 000 ₽.","notes":["В кассационный суд можно обратиться после того, как исчерпаны иные способы обжалования, то есть после апелляции, и в срок не более трех месяцев со дня вступления судебного постановления в силу; если было апелляционное обжалование, срок идет со дня изготовления мотивированного апелляционного определения.","Кассационный суд проверяет только законность: правильность применения норм материального и процессуального права, в пределах доводов жалобы. Он не оценивает доказательства заново и не принимает новые.","Жалоба подается через суд первой инстанции в кассационный суд общей юрисдикции по месту нахождения суда. Пошлина: для физических лиц 5 000 ₽, для организаций 20 000 ₽.","Пропущенный по уважительным причинам срок может быть восстановлен судьей кассационного суда. Приложите копии обжалуемых постановлений и документы, подтверждающие направление жалобы участникам дела."],"basis":[{"lawId":"GPK","number":"376"},{"lawId":"GPK","number":"376.1"},{"lawId":"GPK","number":"377"},{"lawId":"GPK","number":"379.6"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"final-misc"},
{"id":"private-appeal-restore","title":"Ходатайство о восстановлении срока подачи частной жалобы","category":"Суд","summary":"Определение суда обжаловать нужно за 15 дней, а срок пропущен: просьба вернуть срок с объяснением причин. Подается вместе с жалобой.","notes":["Частная жалоба на определение суда первой инстанции может быть подана в течение пятнадцати дней со дня вынесения определения, если иное не установлено кодексом. Пропущенный по уважительной причине срок может быть восстановлен.","Заявление подается в суд, в котором надлежало совершить действие, одновременно с самой жалобой. В нем нужно указать причины пропуска и приложить доказательства: больничный, почтовые документы, справки.","Заявление рассматривается судьей в течение пяти дней без вызова лиц, участвующих в деле, если суд не назначит заседание. Результат — определение, которое можно обжаловать.","Госпошлина за заявление о восстановлении срока не взимается, а за саму частную жалобу уплачивается 3 000 ₽ физическим лицом."],"basis":[{"lawId":"GPK","number":"112"},{"lawId":"GPK","number":"332"},{"lawId":"GPK","number":"321"}],"reviewed":false,"file":"final-misc"},
{"id":"illegal-building-suit","title":"Исковое заявление о сносе самовольной постройки","category":"Суд","summary":"Сосед построил без разрешения и нарушает ваши права: требование снести постройку или привести ее в соответствие. Пошлина 3 000 ₽.","notes":["Самовольная постройка — здание или сооружение, возведенное на участке, не предоставленном в установленном порядке, либо без необходимых разрешений, либо с нарушением градостроительных и строительных норм. Лицо, построившее такой объект, не приобретает на него право собственности и не вправе им распоряжаться.","Самовольная постройка подлежит сносу или приведению в соответствие с установленными требованиями осуществившим ее лицом либо за его счет. Суд принимает решение с учетом того, нарушены ли права других лиц и создана ли угроза жизни и здоровью.","Собственник участка может требовать устранения нарушений своих прав, даже если они не связаны с лишением владения (статья 304 ГК). Докажите нарушение: заключение экспертизы, акты, фото, выписки из ЕГРН.","Пошлина по неимущественному требованию для физического лица — 3 000 ₽."],"basis":[{"lawId":"GK","number":"222"},{"lawId":"GK","number":"304"},{"lawId":"GK","number":"209"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"final-misc"},
{"id":"inheritance-partition-suit","title":"Исковое заявление о разделе наследственного имущества","category":"Суд","summary":"Наследники не договорились: выделить в натуре или передать вещь одному с денежной компенсацией другим. Считает пошлину по цене иска.","notes":["При наследовании имущества несколькими наследниками оно поступает в общую долевую собственность, если иное не предусмотрено законом. К разделу применяются правила о разделе общего имущества, но с особенностями статей 1165–1170.","Раздел возможен по соглашению наследников; если соглашения нет, спор решает суд. Неделимые вещи достаются тому, кто имел право на них при жизни или проживал там, с компенсацией другим наследникам.","Наследник, проживавший в жилье на день открытия наследства и не имеющий иного жилья, имеет преимущественное право на получение такого помещения при разделе, а компенсация несоразмерности долей — в денежной форме.","Пошлина считается от стоимости имущества, на которое претендуете. Приложите свидетельство о праве на наследство, выписки из ЕГРН и оценку."],"basis":[{"lawId":"GK","number":"1164"},{"lawId":"GK","number":"1165"},{"lawId":"GK","number":"1168"},{"lawId":"GK","number":"1170"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"final-misc"},
{"id":"wage-demand","title":"Претензия работодателю о выплате заработной платы","category":"Трудовые отношения","summary":"Зарплату задерживают: письменное требование выплатить долг и компенсацию за каждый день задержки. Считает компенсацию.","notes":["Заработная плата выплачивается не реже чем каждые полмесяца, срок выплаты — не позднее 15 календарных дней со дня окончания периода, за который она начислена. Работодатель должен выдавать расчетный листок.","При нарушении срока выплаты работодатель обязан уплатить деньги вместе с компенсацией: не ниже одной сто пятидесятой ключевой ставки Банка России от невыплаченных сумм за каждый день задержки, начиная со следующего дня после срока выплаты.","Претензия — досудебное требование, не обязательное по закону, но оно фиксирует задолженность. Параллельно можно жаловаться в трудовую инспекцию и обращаться в суд: срок для иска о невыплаченной зарплате — один год.","Приостановить работу в связи с задержкой более 15 дней можно, письменно уведомив работодателя (статья 142 ТК)."],"basis":[{"lawId":"TK","number":"136"},{"lawId":"TK","number":"236"},{"lawId":"TK","number":"142"},{"lawId":"TK","number":"392"}],"reviewed":false,"file":"final-misc"},
{"id":"tax-deferral","title":"Заявление об отсрочке или рассрочке уплаты налога","category":"Претензии и уведомления","summary":"Если налог не заплатить сразу: отсрочка до года, рассрочка до трех лет по основаниям статьи 64 НК. Проверяет срок и называет процентную ставку.","notes":["Отсрочка предоставляется на срок до одного года, рассрочка — до трех лет. Основания: ущерб от стихийного бедствия, угроза банкротства, имущественное положение физического лица, исключающее единовременную уплату, сезонность и другие из пункта 2 статьи 64.","На сумму отсрочки или рассрочки по основаниям из подпунктов 3, 4 и 5 начисляются проценты по ставке, равной половине ключевой ставки Банка России; по подпунктам 1 и 2 проценты не начисляются.","Заявление подается в уполномоченный налоговый орган. К нему прилагаются документы, подтверждающие основание, перечень контрагентов-дебиторов и иные сведения, предусмотренные пунктом 4 статьи 64.","Налоговый орган вправе потребовать обеспечение (залог, поручительство, банковская гарантия) и принимает решение в установленный срок. Пока решение не принято, сроки уплаты не меняются: следите за пенями."],"basis":[{"lawId":"NK","number":"64"},{"lawId":"NK","number":"63"},{"lawId":"NK","number":"61"}],"reviewed":false,"file":"final-misc2"},
{"id":"tax-power","title":"Доверенность на представление интересов в налоговом органе","category":"Доверенности","summary":"Доверить другому человеку декларации, получение документов и споры с налоговой. Для физических лиц — нотариальная форма.","notes":["Налогоплательщик вправе участвовать в налоговых отношениях через законного или уполномоченного представителя. Личное участие не лишает права иметь представителя, и наоборот.","Уполномоченный представитель организации действует на основании письменной доверенности или доверенности в форме электронного документа, подписанного квалифицированной электронной подписью. Представитель индивидуального предпринимателя и физического лица — на основании нотариально удостоверенной доверенности либо доверенности, приравненной к ней.","Не могут быть уполномоченными представителями должностные лица налоговых органов, таможни, органов внутренних дел, судьи, следователи и прокуроры.","Документы, подтверждающие полномочия, представляются в налоговый орган лично, через представителя или в электронной форме. Укажите точный перечень действий и срок."],"basis":[{"lawId":"NK","number":"26"},{"lawId":"NK","number":"27"},{"lawId":"NK","number":"29"},{"lawId":"GK","number":"185.1"}],"reviewed":false,"file":"final-misc2"},
{"id":"bailiff-power","title":"Доверенность на представление интересов в исполнительном производстве","category":"Доверенности","summary":"Поручить представителю действовать за вас в ФССП: знакомиться с делом, подавать заявления, получать деньги. Полномочия подтверждаются доверенностью.","notes":["Полномочия представителя в исполнительном производстве подтверждаются доверенностью, выданной и оформленной в соответствии с законом. Для граждан она может быть оформлена в электронном виде с использованием единой системы идентификации и подписана усиленной квалифицированной электронной подписью.","Доверенность, выдаваемая организацией, подписывается руководителем или иным уполномоченным лицом и скрепляется печатью при ее наличии.","Полномочия на получение денег и иные особые действия лучше перечислить прямо. Для подачи жалоб в суд проверьте требования процессуальных кодексов к оформлению доверенности.","Доверенность можно в любой момент отменить; сообщите об отмене приставу и представителю."],"basis":[{"lawId":"FZ229","number":"54"},{"lawId":"GK","number":"185"},{"lawId":"GK","number":"186"},{"lawId":"GK","number":"188"}],"reviewed":false,"file":"final-misc2"},
{"id":"enforcement-setoff","title":"Заявление о зачете встречных однородных требований в исполнительном производстве","category":"Суд","summary":"Стороны должны друг другу по исполнительным документам: просьба к приставу зачесть встречные денежные требования и вынести постановление.","notes":["Пристав по заявлению взыскателя или должника либо по собственной инициативе производит зачет встречных однородных требований, подтвержденных исполнительными документами о взыскании денег, по которым возбуждены исполнительные производства.","Зачет возможен, если требования встречные (каждый должен другому) и однородные (деньги). О зачете выносится постановление, которое утверждает старший судебный пристав или его заместитель; копия направляется сторонам.","Приложите копии исполнительных документов или реквизиты обоих исполнительных производств, чтобы пристав мог проверить встречный характер требований.","Заявление рассматривается в порядке статьи 64.1: в десятидневный срок со дня поступления выносится постановление."],"basis":[{"lawId":"FZ229","number":"88.1"},{"lawId":"FZ229","number":"64.1"},{"lawId":"GK","number":"410"}],"reviewed":false,"file":"final-misc2"},
{"id":"criminal-reconciliation","title":"Заявление потерпевшего о прекращении уголовного дела в связи с примирением","category":"Суд","summary":"Если обвиняемый загладил вред: потерпевший просит прекратить дело за примирением по преступлению небольшой или средней тяжести.","notes":["Лицо, впервые совершившее преступление небольшой или средней тяжести, может быть освобождено от уголовной ответственности, если примирилось с потерпевшим и загладило причиненный вред. Суд, следователь с согласия руководителя или дознаватель с согласия прокурора вправе прекратить дело на основании заявления потерпевшего.","Решение о прекращении принимает орган, а не потерпевший: заявление — только основание. Убедитесь, что вред действительно заглажен и вы действуете добровольно.","Приложите расписку о возмещении ущерба или иные документы. Заявление можно подать на любой стадии до удаления суда в совещательную комнату.","Прекращение дела по этому основанию не является реабилитирующим: обвиняемый должен понимать и принимать такие последствия."],"basis":[{"lawId":"UK","number":"76"},{"lawId":"UPK","number":"25"},{"lawId":"UPK","number":"254"}],"reviewed":false,"file":"final-misc2"},
{"id":"egrn-error-fix","title":"Заявление об исправлении технической ошибки в записях ЕГРН","category":"Претензии и уведомления","summary":"В выписке неверно указаны ФИО, площадь или номер из-за описки органа регистрации: просьба исправить техническую ошибку.","notes":["Техническая ошибка — описка, опечатка, грамматическая или арифметическая ошибка органа регистрации при внесении сведений, приведшая к несоответствию записей документам, на основании которых они вносились. Она исправляется по заявлению заинтересованного лица или по решению самого органа.","Заявление подается в орган регистрации прав (Росреестр) через многофункциональный центр, почтой или в электронной форме через личный кабинет. Приложите документы, показывающие правильные сведения.","Если исправление может причинить вред правообладателям или третьим лицам, оно проводится только по решению суда. Реестровые ошибки в межевых и технических планах исправляются по иным правилам.","О внесенных изменениях орган регистрации направляет уведомление правообладателям в течение трех рабочих дней."],"basis":[{"lawId":"FZ218","number":"61"},{"lawId":"FZ218","number":"26"},{"lawId":"FZ218","number":"29"}],"reviewed":false,"file":"final-last"},
{"id":"registration-suspension-suit","title":"Административное исковое заявление об оспаривании приостановления регистрации прав","category":"Суд","summary":"Росреестр приостановил регистрацию или отказал: иск в суд об оспаривании решения регистратора. Срок три месяца, пошлина 3 000 ₽.","notes":["Регистрация приостанавливается по основаниям статьи 26: нет права на объект, ненадлежащий заявитель, противоречия с зарегистрированными правами, не представлены документы, форма документов не соответствует закону и др. Приостановление действует до трех месяцев, пока устраняются причины.","Сначала можно устранить причины, указанные в уведомлении, и сообщить об этом регистратору. Если вы не согласны с решением, его можно обжаловать в суде в порядке административного судопроизводства.","Административное исковое заявление об оспаривании решения органа, наделенного публичными полномочиями, подается в течение трех месяцев со дня, когда вы узнали о нарушении прав. Пропуск срока не основание отказать в принятии, но может повлиять на удовлетворение.","Госпошлина для физических лиц — 3 000 ₽, для организаций — 15 000 ₽. В заявлении нужно указать, какие права нарушены."],"basis":[{"lawId":"FZ218","number":"26"},{"lawId":"FZ218","number":"29"},{"lawId":"KAS","number":"218"},{"lawId":"KAS","number":"219"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"final-last"},
{"id":"replanning-application","title":"Заявление о согласовании переустройства и перепланировки жилого помещения","category":"Претензии и уведомления","summary":"Хотите снести стену, объединить комнаты или перенести санузел: заявление в орган местного самоуправления с перечнем документов.","notes":["Переустройство и перепланировка в многоквартирном доме проводятся по согласованию с органом местного самоуправления на основании его решения. Перепланировка меняет границы или площадь помещения, образует новые помещения, а переустройство затрагивает инженерные сети и оборудование.","К заявлению прилагаются правоустанавливающие документы на помещение, проект переустройства и (или) перепланировки, технический паспорт, согласие в письменной форме всех членов семьи нанимателя (при социальном найме), заключение органа охраны памятников при необходимости.","Если перепланировка затрагивает общее имущество, нужно согласие всех собственников дома. Самовольная перепланировка может быть узаконена только через суд или потребует приведения помещения в прежнее состояние.","Заявление подается по месту нахождения помещения через многофункциональный центр или непосредственно. Форма заявления утверждается Правительством: этот текст — образец."],"basis":[{"lawId":"JK","number":"25"},{"lawId":"JK","number":"26"},{"lawId":"JK","number":"27"},{"lawId":"JK","number":"28"}],"reviewed":false,"file":"final-last"},
{"id":"photographer-contract","title":"Договор оказания услуг фотографа","category":"Договоры","summary":"Фотосессия, свадьба или мероприятие: объем, сроки передачи фотографий, права на снимки, оплата и порядок отказа.","notes":["По договору возмездного оказания услуг исполнитель по заданию заказчика оказывает услуги, а заказчик оплачивает их. Заказчик вправе отказаться от договора, оплатив исполнителю фактически понесенные расходы; исполнитель — только при возмещении убытков заказчику.","Если услуга не оказана по вине заказчика, она оплачивается полностью; если по обстоятельствам, за которые никто не отвечает, заказчик возмещает фактические расходы исполнителя.","Права на фотографии принадлежат автору. В договоре нужно определить, получает ли заказчик право использовать снимки в личных целях или исключительное право; публикация фото людей требует их согласия.","Укажите, сколько фотографий будет передано, в каком формате, в какой срок и как их обработают. Предусмотрите запасной вариант на случай болезни фотографа или плохой погоды."],"basis":[{"lawId":"GK","number":"779"},{"lawId":"GK","number":"781"},{"lawId":"GK","number":"782"},{"lawId":"GK","number":"1259"}],"reviewed":false,"file":"final-last"},
{"id":"kas-restore-deadline","title":"Ходатайство о восстановлении пропущенного процессуального срока (административное дело)","category":"Суд","summary":"Срок на иск, жалобу или частную жалобу по КАС пропущен: просьба вернуть его с уважительными причинами. Действие совершается одновременно.","notes":["Лицам, пропустившим процессуальный срок по причинам, признанным судом уважительными, срок может быть восстановлен. В некоторых случаях, прямо предусмотренных кодексом, срок не подлежит восстановлению ни при каких причинах.","Заявление подается в суд, где нужно было совершить действие, одновременно с самим действием (иск, жалоба, документы). Причины пропуска нужно описать и подтвердить документами.","Заявление рассматривается без извещения участников, если суд не решит иначе. На определение можно подать частную жалобу.","По иску об оспаривании решений органов власти общий срок три месяца со дня, когда вы узнали о нарушении; по решениям судебных приставов — десять дней."],"basis":[{"lawId":"KAS","number":"95"},{"lawId":"KAS","number":"219"}],"reviewed":false,"file":"final-last"},
{"id":"authority-decision-suit","title":"Административное исковое заявление об оспаривании решения органа власти","category":"Суд","summary":"Орган власти или должностное лицо нарушили ваши права: иск об оспаривании решения, действия или бездействия. Срок три месяца, пошлина 3 000 ₽.","notes":["Гражданин, организация могут обратиться в суд с требованием об оспаривании решений, действий или бездействия органа государственной власти, местного самоуправления, иного органа, организации, наделенных публичными полномочиями, а также должностного лица, государственного или муниципального служащего.","Если федеральный закон требует соблюдения досудебного порядка, обращение в суд возможно только после него. Срок обращения — три месяца со дня, когда вы узнали о нарушении, если кодекс не устанавливает иной. Пропущенный срок можно восстановить по уважительной причине.","Укажите, какие права, свободы и законные интересы нарушены, содержание требований, основания и доводы, сведения о досудебном порядке и жалобах в порядке подчиненности. Приложите копию оспариваемого решения.","Госпошлина для физических лиц — 3 000 ₽, для организаций — 15 000 ₽."],"basis":[{"lawId":"KAS","number":"218"},{"lawId":"KAS","number":"219"},{"lawId":"KAS","number":"220"},{"lawId":"KAS","number":"125"},{"lawId":"NK","number":"333.19"}],"reviewed":false,"file":"final-last"},
{"id":"preventive-measure-motion","title":"Ходатайство об изменении меры пресечения","category":"Суд","summary":"Просьба заменить заключение под стражу на домашний арест, залог или подписку о невыезде: основания, поручители, здоровье, семья.","notes":["Мера пресечения отменяется, когда в ней отпала необходимость, или изменяется на более мягкую, когда изменились основания, предусмотренные статьями 97 и 99. Заключение под стражу применяется только по судебному решению при ограниченном перечне случаев (статья 108).","Если у подозреваемого или обвиняемого выявлено тяжелое заболевание, препятствующее содержанию под стражей и подтвержденное медицинским заключением по результатам освидетельствования, мера изменяется на более мягкую.","Ходатайство вправе заявить подозреваемый, обвиняемый, защитник, законный представитель. Подайте его следователю, а при мере, избранной судом, — в суд. Приложите документы: поручительства, справки о здоровье, семье, работе и жилье.","Мера, избранная следователем с согласия руководителя или дознавателем с согласия прокурора, может быть изменена только с согласия этих лиц."],"basis":[{"lawId":"UPK","number":"110"},{"lawId":"UPK","number":"108"},{"lawId":"UPK","number":"97"},{"lawId":"UPK","number":"99"},{"lawId":"UPK","number":"119"}],"reviewed":false,"file":"final-last"},
{"id":"osago-direct-claim","title":"Заявление о прямом возмещении убытков по ОСАГО","category":"Претензии и уведомления","summary":"ДТП с двумя и более машинами, вред только автомобилям: заявление в свою страховую о ремонте или выплате.","notes":["В свою страховую компанию обращаются, если в ДТП столкнулись две и более машины, у владельцев которых есть полис ОСАГО, и вред причинен только автомобилям. Если пострадали люди или иное имущество, заявление подается страховщику виновника.","За легковой автомобиль гражданина страховщик по общему правилу организует и оплачивает ремонт. Деньгами возмещение выплачивается в случаях, перечисленных в пункте 16.1 статьи 12 закона, в том числе по письменному соглашению со страховщиком.","В течение пяти рабочих дней после подачи заявления машину нужно представить на осмотр. Страховщик должен выплатить возмещение или выдать направление на ремонт в течение 20 календарных дней без учета нерабочих праздничных дней.","Предел возмещения за вред имуществу — 400 000 ₽. К заявлению прикладываются документы по правилам ОСАГО: паспорт, документы на машину, извещение о ДТП, при оформлении полицией — документы полиции. Форма заявления утверждена Банком России: этот текст — образец."],"basis":[{"lawId":"FZ40","number":"14.1"},{"lawId":"FZ40","number":"12"},{"lawId":"FZ40","number":"7"}],"reviewed":false,"file":"osago-travel"},
{"id":"osago-surcharge-claim","title":"Претензия страховщику о доплате страхового возмещения по ОСАГО","category":"Претензии и уведомления","summary":"Страховая выплатила меньше, чем стоит ремонт по независимой экспертизе: заявление о несогласии и требование доплаты. Обязательно до обращения к финансовому уполномоченному и в суд.","notes":["Если вы не согласны с размером выплаты, до иска нужно направить страховщику письменное заявление. Страховщик рассматривает его в порядке, установленном законом об уполномоченном по правам потребителей финансовых услуг; если ответ не устроил, следующий шаг — обращение к финансовому уполномоченному.","Размер доплаты обоснуйте независимой экспертизой. Возмещение за вред имуществу не может превышать 400 000 ₽, код учитывает этот предел.","Если страховщик должен был организовать ремонт, но без вашего согласия выплатил деньги, это тоже повод для претензии: можно требовать ремонт или возмещение без учета износа.","В суде со страховщика в пользу гражданина взыскивается штраф 50 % от суммы, которую он не выплатил добровольно (пункт 3 статьи 16.1 закона)."],"basis":[{"lawId":"FZ40","number":"16.1"},{"lawId":"FZ40","number":"12"},{"lawId":"FZ40","number":"7"}],"reviewed":false,"file":"osago-travel"},
{"id":"osago-penalty-claim","title":"Заявление о выплате неустойки по ОСАГО","category":"Претензии и уведомления","summary":"Страховая опоздала с выплатой или направлением на ремонт: неустойка 1 % от возмещения за каждый день просрочки. Сумму считает код.","notes":["Страховщик должен выплатить возмещение или выдать направление на ремонт в течение 20 календарных дней (за исключением нерабочих праздничных дней) со дня принятия заявления с документами. За каждый день просрочки он платит неустойку — один процент от размера возмещения.","Неустойка выплачивается по заявлению потерпевшего, в котором указывается форма расчета: почтовый перевод или перечисление на счет с реквизитами. Дополнительных документов страховщик требовать не вправе.","Общий размер неустойки не может превышать 400 000 ₽ — страховую сумму за вред имуществу. Код ограничивает расчет этим пределом.","Последний день срока код считает сам по производственному календарю: 20 (при ремонте на станции по выбору потерпевшего — 30) календарных дней со дня принятия заявления, не считая нерабочих праздничных дней; если последний день выпал на выходной, он переносится на ближайший рабочий день. Если срок ремонта нарушила станция, неустойка другая — 0,5 % в день, для нее есть отдельный шаблон."],"basis":[{"lawId":"FZ40","number":"12"},{"lawId":"FZ40","number":"16.1"},{"lawId":"GK","number":"193"}],"reviewed":false,"file":"osago-travel"},
{"id":"child-travel-consent","title":"Согласие на выезд несовершеннолетнего ребенка из Российской Федерации","category":"Доверенности","summary":"Ребенок едет за границу без родителей: с бабушкой, тренером, группой или один. Проект согласия для нотариуса со сроком и странами.","notes":["Если ребенок выезжает с одним из родителей, согласие второго не требуется, пока второй родитель не подал заявление о несогласии на выезд. Согласие нужно, когда ребенок едет без законных представителей.","Согласие оформляется нотариально. В нем можно указать срок выезда и государства, которые ребенок намерен посетить. Нотариусу нужен паспорт законного представителя и свидетельство о рождении или паспорт ребенка.","Достаточно согласия одного из законных представителей. Но если второй подал заявление о несогласии, ребенка не выпустят без решения суда или без сопровождения подавшего заявление.","Ребенок везет с собой паспорт и подлинник нотариального согласия. Некоторые страны требуют перевод согласия или согласие обоих родителей — уточните требования страны въезда."],"basis":[{"lawId":"FZ114","number":"20"},{"lawId":"FZ114","number":"21"},{"lawId":"FZ114","number":"22"}],"reviewed":false,"file":"osago-travel"},
{"id":"child-travel-objection","title":"Заявление о несогласии на выезд несовершеннолетнего из Российской Федерации","category":"Претензии и уведомления","summary":"Родитель против того, чтобы ребенка вывезли за границу без него: заявление в МВД о несогласии на выезд. Тот же шаблон — для отзыва такого заявления.","notes":["Законный представитель вправе заявить о несогласии на выезд ребенка из России. В заявлении можно указать срок его действия и государства, выезд в которые запрещается. Запрет не распространяется на выезд вместе с подавшим заявление законным представителем — гражданином России.","Заявление подается в территориальный орган МВД по вопросам миграции лично, с паспортом и свидетельством о рождении ребенка. Порядок подачи и форму устанавливает МВД России: этот текст — образец содержания.","Заявление можно отозвать во внесудебном порядке. Если родители спорят, возможность выезда решает суд.","Пограничники узнают о несогласии из учета МВД и не выпустят ребенка, даже если у сопровождающего есть нотариальное согласие другого родителя."],"basis":[{"lawId":"FZ114","number":"21"},{"lawId":"FZ114","number":"20"}],"reviewed":false,"file":"osago-travel"},
{"id":"tour-refusal-refund","title":"Заявление об отказе от туристского продукта и возврате денег","category":"Претензии и уведомления","summary":"Заболели, не дали визу или просто передумали ехать: отказ от тура и требование вернуть деньги за вычетом фактических расходов туроператора.","notes":["Турист вправе отказаться от договора в любое время, оплатив туроператору фактически понесенные расходы. Расходы туроператор должен подтвердить документами; штрафы «за аннуляцию» в процентах от цены сами по себе расходами не являются.","Болезнь туриста, отказ в выдаче визы, ухудшение условий и изменение сроков путешествия закон называет существенным изменением обстоятельств: это основание расторгнуть договор. Приложите подтверждение — справку врача или уведомление об отказе в визе.","Заявление направьте туроператору; если тур куплен через агентство, отдайте копию турагенту. Сохраните доказательство вручения: отметку о приеме или почтовую квитанцию с описью.","Если деньги не вернули, можно обратиться в суд по закону о защите прав потребителей: при удовлетворении иска взыскивается также штраф 50 % от присужденной суммы."],"basis":[{"lawId":"FZ132","number":"10"},{"lawId":"ZOZPP","number":"32"},{"lawId":"GK","number":"782"}],"reviewed":false,"file":"tourism-education"},
{"id":"tour-quality-claim","title":"Претензия туроператору о ненадлежащем качестве тура","category":"Претензии и уведомления","summary":"Отель хуже обещанного, не было трансфера или экскурсий: претензия об уменьшении цены и возмещении убытков. Подается в течение 20 дней после окончания поездки.","notes":["Претензии к качеству туристского продукта предъявляются туроператору в письменной форме в течение 20 дней со дня окончания договора и рассматриваются в течение 10 дней со дня получения.","Туроператор отвечает перед туристом за все услуги, входящие в тур, в том числе за отель, трансфер и экскурсии, даже если их оказывали третьи лица и тур куплен через агентство.","Соберите доказательства прямо на месте: фото и видео, переписку с гидом и отелем, акт или запись в книге жалоб, чеки на расходы, которые пришлось понести.","По закону о защите прав потребителей при недостатках услуги можно требовать соразмерного уменьшения цены и возмещения убытков. Если претензию не удовлетворили, суд взыщет также неустойку и штраф."],"basis":[{"lawId":"FZ132","number":"10"},{"lawId":"FZ132","number":"9"},{"lawId":"ZOZPP","number":"29"},{"lawId":"ZOZPP","number":"31"}],"reviewed":false,"file":"tourism-education"},
{"id":"tour-safety-termination","title":"Требование о расторжении договора о туре в связи с угрозой безопасности","category":"Претензии и уведомления","summary":"В стране поездки опасно, и власти это официально признали: требование расторгнуть договор и вернуть полную цену тура, а после начала поездки — часть за неоказанные услуги.","notes":["Если в стране временного пребывания возникла угроза жизни, здоровью или имуществу туристов, турист вправе потребовать расторжения или изменения договора. Угроза подтверждается решениями или рекомендациями органов власти, например сообщением Ростуризма.","При расторжении до начала путешествия туристу возвращается вся цена тура, после начала — часть, пропорциональная стоимости неоказанных услуг. Удержать «фактические расходы» в этом случае туроператор не вправе.","Закон говорит о расторжении в судебном порядке, но сначала стоит направить туроператору это требование: многие туроператоры возвращают деньги добровольно, а отказ пригодится в суде.","Укажите конкретное решение или рекомендацию органа власти с датой и источником и приложите их распечатку."],"basis":[{"lawId":"FZ132","number":"14"},{"lawId":"FZ132","number":"10"}],"reviewed":false,"file":"tourism-education"},
{"id":"paid-education-contract","title":"Договор об оказании платных образовательных услуг","category":"Договоры","summary":"Курсы, репетиторская школа, вуз или колледж на платной основе: программа, форма и срок обучения, полная стоимость и порядок оплаты, основания расторжения.","notes":["В договоре обязательно указываются вид, уровень и направленность программы, форма обучения, срок освоения, полная стоимость и порядок оплаты. Сведения в договоре должны совпадать с информацией на сайте организации на дату заключения.","Увеличить стоимость после заключения договора нельзя, кроме индексации на уровень инфляции, заложенный в федеральном бюджете. Условия, ограничивающие права обучающегося по сравнению с законом, не применяются.","Организация может расторгнуть договор в одностороннем порядке при просрочке оплаты или если обучение стало невозможным из-за действий обучающегося. Эти основания должны быть указаны в договоре.","Для вузов, колледжей и школ утверждены примерные формы договоров: этот текст подходит прежде всего для дополнительного образования и курсов. Образовательная деятельность требует лицензии, кроме случаев, указанных в законе (например, индивидуальный предприниматель, который учит сам)."],"basis":[{"lawId":"FZ273","number":"54"},{"lawId":"FZ273","number":"61"},{"lawId":"GK","number":"779"},{"lawId":"GK","number":"782"},{"lawId":"ZOZPP","number":"32"}],"reviewed":false,"file":"tourism-education"},
{"id":"education-refund-application","title":"Заявление о расторжении договора об обучении и возврате платы","category":"Претензии и уведомления","summary":"Решили не учиться дальше на курсах, в школе или вузе: отказ от договора и требование вернуть оплату за вычетом стоимости уже прошедших занятий. Сумму считает код.","notes":["Обучающийся или заказчик вправе отказаться от договора в любое время, оплатив организации фактически понесенные расходы. Образовательные отношения при этом прекращаются досрочно по инициативе обучающегося.","Вернуть должны плату за неоказанный период. Условия договора о невозврате аванса или о «штрафе» за отказ ущемляют права потребителя и не применяются.","Посчитайте, сколько занятий или месяцев уже прошло, и укажите их стоимость: код вычтет ее из оплаченной суммы. Если организация считает расходы иначе, пусть подтвердит их документами.","Заявление подается в организацию с отметкой о получении или почтой. Если деньги не вернули, можно обратиться в суд по закону о защите прав потребителей."],"basis":[{"lawId":"ZOZPP","number":"32"},{"lawId":"GK","number":"782"},{"lawId":"FZ273","number":"61"},{"lawId":"FZ273","number":"54"}],"reviewed":false,"file":"tourism-education"},
{"id":"medical-intervention-refusal","title":"Отказ от медицинского вмешательства","category":"Претензии и уведомления","summary":"Не согласны на операцию, прививку, госпитализацию или обследование: письменный отказ от вмешательства или требование его прекратить.","notes":["Гражданин, а за ребенка до 15 лет — родитель или иной законный представитель, вправе отказаться от медицинского вмешательства или потребовать его прекращения. Исключения — случаи из части 9 статьи 20: например, угроза жизни, когда выразить волю некому, опасные для окружающих заболевания, тяжелые психические расстройства.","При отказе врач должен разъяснить возможные последствия в доступной форме. Отказ оформляется письменно, подписывается гражданином или представителем и медицинским работником и хранится в медицинской документации.","Обычно больница дает свой бланк отказа — его можно заполнить. Этот текст пригодится, если бланка нет или нужно точно описать, от чего вы отказываетесь.","Если родитель отказывается от вмешательства, необходимого для спасения жизни ребенка, больница вправе обратиться в суд."],"basis":[{"lawId":"FZ323","number":"20"},{"lawId":"FZ323","number":"19"}],"reviewed":false,"file":"medicine"},
{"id":"medical-records-request","title":"Запрос медицинских документов (копий, выписок)","category":"Претензии и уведомления","summary":"Нужны копия медицинской карты, выписка или результаты обследований для другой клиники, суда или страховой: запрос в медицинскую организацию.","notes":["Пациент или его законный представитель вправе по запросу, в том числе электронному, получать медицинские документы, их копии и выписки, а также непосредственно знакомиться с медицинской документацией.","Супруг, близкие родственники и лица, указанные пациентом в согласии на разглашение врачебной тайны, вправе получать документы, в том числе после смерти пациента, если он этого не запретил.","Порядок и сроки выдачи документов устанавливает Минздрав России. Укажите в запросе, какие документы и за какой период нужны, и сохраните отметку о приеме.","Отказ или молчание можно обжаловать главному врачу, в территориальный орган Росздравнадзора или в суд."],"basis":[{"lawId":"FZ323","number":"22"},{"lawId":"FZ323","number":"13"}],"reviewed":false,"file":"medicine"},
{"id":"medical-doctor-change","title":"Заявление о выборе (замене) лечащего врача","category":"Претензии и уведомления","summary":"Хотите сменить участкового терапевта, педиатра или лечащего врача в стационаре: заявление на имя главного врача.","notes":["В выбранной поликлинике гражданин может выбрать терапевта, педиатра, врача общей практики или фельдшера не чаще одного раза в год, кроме случаев смены медицинской организации. Заявление подается лично или через представителя на имя руководителя организации.","Лечащий врач назначается руководителем или выбирается пациентом с учетом согласия врача. Если пациент требует заменить лечащего врача, руководитель должен содействовать выбору другого врача.","Укажите, какого врача вы хотите выбрать. Если желаемый врач не согласен или у него слишком большая нагрузка, организация предложит другого.","Причину замены указывать не обязательно, но она помогает быстрее решить вопрос."],"basis":[{"lawId":"FZ323","number":"21"},{"lawId":"FZ323","number":"70"},{"lawId":"FZ323","number":"19"}],"reviewed":false,"file":"medicine"},
{"id":"medical-secrecy-consent","title":"Согласие на разглашение сведений, составляющих врачебную тайну","category":"Доверенности","summary":"Кому врачи могут сообщать о вашем здоровье и выдавать документы, в том числе после смерти. Тот же шаблон — для запрета сообщать сведения.","notes":["Сведения о факте обращения за медицинской помощью, о состоянии здоровья и диагнозе составляют врачебную тайну. Сообщать их другим людям можно только с письменного согласия пациента или его законного представителя, кроме случаев, перечисленных в законе.","Лица, указанные в согласии, вправе знакомиться с медицинской документацией и получать ее копии, в том числе после смерти пациента. Супругу и близким родственникам после смерти сведения сообщаются и без согласия, если пациент это не запретил.","Пациент может запретить сообщать сведения кому-либо, в том числе родственникам. Запрет тоже оформляется письменно и передается в медицинскую организацию.","Согласие можно отозвать в любой момент, подав письменное заявление. Сдайте документ в регистратуру с отметкой о приеме, чтобы он попал в медицинскую карту."],"basis":[{"lawId":"FZ323","number":"13"},{"lawId":"FZ323","number":"22"},{"lawId":"FZ323","number":"19"}],"reviewed":false,"file":"medicine"},
{"id":"paid-medical-service-claim","title":"Претензия о некачественной платной медицинской услуге","category":"Претензии и уведомления","summary":"Платное лечение в клинике или стоматологии оказано некачественно: требование вернуть деньги или уменьшить цену и возместить расходы на исправление.","notes":["Платные медицинские услуги оказываются по договору, и к ним применяется закон о защите прав потребителей. При недостатках услуги пациент вправе потребовать безвозмездного устранения, уменьшения цены, возмещения расходов на устранение недостатков другим врачом или отказаться от договора и вернуть деньги.","Требования о возврате денег, уменьшении цены и возмещении расходов должны быть удовлетворены в десятидневный срок со дня предъявления. За просрочку начисляется неустойка 3 % в день.","Вред здоровью, причиненный при оказании медицинской помощи, медицинская организация возмещает независимо от вины, если вред причинен вследствие недостатков услуги.","Подтвердите недостатки: заключение другого врача, результаты обследований, снимки. Можно просить провести экспертизу качества; копии документов запросите отдельным запросом."],"basis":[{"lawId":"FZ323","number":"84"},{"lawId":"FZ323","number":"98"},{"lawId":"ZOZPP","number":"29"},{"lawId":"ZOZPP","number":"31"},{"lawId":"GK","number":"1095"}],"reviewed":false,"file":"medicine"},
{"id":"school-admission-application","title":"Заявление о приеме ребенка в школу","category":"Претензии и уведомления","summary":"Запись в первый или другой класс государственной или муниципальной школы: заявление родителя с языком обучения, правом преимущественного приема и согласием на обработку данных.","notes":["В первый класс принимают с шести лет и шести месяцев до восьми лет при отсутствии противопоказаний. Принять ребенка раньше или позже может разрешить учредитель школы по заявлению родителей.","Государственная или муниципальная школа обязана принять детей, проживающих на закрепленной за ней территории. Ребенок имеет право преимущественного приема в школу, где учится его брат или сестра.","Отказать в приеме можно только из-за отсутствия свободных мест. Тогда родители обращаются в орган управления образованием, чтобы устроить ребенка в другую школу.","Обычно заявление подают через Госуслуги или по форме школы, сроки приема публикуются на сайте школы. Этот текст подойдет для подачи лично или почтой; приложите копии свидетельства о рождении и документа о регистрации по месту жительства."],"basis":[{"lawId":"FZ273","number":"67"},{"lawId":"FZ273","number":"55"},{"lawId":"FZ273","number":"63"}],"reviewed":false,"file":"education-rights"},
{"id":"family-education-notice","title":"Уведомление о выборе семейной формы образования","category":"Претензии и уведомления","summary":"Ребенок будет учиться дома: уведомление в орган местного самоуправления о выборе семейного образования. Аттестацию ребенок проходит в выбранной школе.","notes":["Общее образование можно получать вне школы — в форме семейного образования. Форму получения образования выбирают родители с учетом мнения ребенка.","О выборе семейного образования родители информируют орган местного самоуправления муниципального района, округа или городского округа по месту жительства — обычно управление (комитет) образования.","Ребенок на семейном образовании вправе пройти экстерном промежуточную и государственную итоговую аттестацию в школе, имеющей государственную аккредитацию; без основного общего и среднего общего образования — бесплатно (часть 3 статьи 34 закона).","Если ребенок уже учится в школе, одновременно подается заявление об отчислении в связи с переходом на семейное образование."],"basis":[{"lawId":"FZ273","number":"63"},{"lawId":"FZ273","number":"17"},{"lawId":"FZ273","number":"34"},{"lawId":"FZ273","number":"44"}],"reviewed":false,"file":"education-rights"},
{"id":"individual-plan-application","title":"Заявление об обучении по индивидуальному учебному плану","category":"Претензии и уведомления","summary":"Спорт, болезнь, работа или желание учиться быстрее: заявление о переводе на индивидуальный учебный план, в том числе ускоренное обучение.","notes":["Обучающийся вправе учиться по индивидуальному учебному плану, в том числе ускоренно, в пределах осваиваемой программы. Порядок устанавливается локальным актом организации — попросите его в учебной части или найдите на сайте.","Индивидуальный учебный план обеспечивает освоение программы с учетом особенностей и образовательных потребностей конкретного обучающегося: можно изменить расписание, сроки, порядок изучения предметов.","За несовершеннолетнего школьника заявление подает родитель. Студент вуза или колледжа подает заявление сам.","Приложите документы, подтверждающие причину: справку спортивной школы, медицинское заключение, справку с места работы."],"basis":[{"lawId":"FZ273","number":"34"},{"lawId":"FZ273","number":"2"}],"reviewed":false,"file":"education-rights"},
{"id":"education-dispute-commission","title":"Обращение в комиссию по урегулированию споров между участниками образовательных отношений","category":"Претензии и уведомления","summary":"Несогласие с оценкой, дисциплинарным взысканием, решением учителя или локальным актом школы: обращение в школьную комиссию по спорам.","notes":["Обучающиеся и родители несовершеннолетних вправе обращаться в комиссию по урегулированию споров — по вопросам реализации права на образование, конфликта интересов педагога, применения локальных актов, обжалования дисциплинарных взысканий.","Комиссия создается в каждой организации из равного числа представителей обучающихся или родителей и работников. Ее решение обязательно для всех участников образовательных отношений в организации.","Решение комиссии можно обжаловать в установленном порядке: в орган управления образованием, в надзорный орган или в суд.","Опишите спор конкретно: дата, что произошло, какой документ или решение вы оспариваете, чего просите. Приложите копии документов."],"basis":[{"lawId":"FZ273","number":"45"},{"lawId":"FZ273","number":"34"}],"reviewed":false,"file":"education-rights"},
{"id":"academic-leave-application","title":"Заявление о предоставлении академического отпуска","category":"Претензии и уведомления","summary":"Студент вуза или колледжа берет перерыв в учебе по болезни, семейным обстоятельствам или из-за призыва: заявление на имя ректора или директора.","notes":["Обучающийся имеет право на академический отпуск в порядке и по основаниям, которые установлены Минобрнауки России по согласованию с Минпросвещения России. Сроки отпуска и перечень документов сверьте с этим порядком и с локальным актом вуза или колледжа: в базе «Нормы» этого порядка нет.","Приложите документ-основание: заключение врачебной комиссии, повестку военкомата, документы о семейных обстоятельствах. Сохраните копию заявления с отметкой о приеме.","Если вы учитесь платно, уточните в договоре, как вносится плата за период отпуска, и приложите копию заявления к переписке с бухгалтерией.","Отпуск по беременности и родам и отпуск по уходу за ребенком до трех лет предоставляются отдельно, в порядке, установленном федеральными законами."],"basis":[{"lawId":"FZ273","number":"34"}],"reviewed":false,"file":"education-rights"},
{"id":"osago-repair-delay-claim","title":"Заявление о выплате неустойки за просрочку ремонта по ОСАГО","category":"Претензии и уведомления","summary":"Станция техобслуживания держит машину дольше 30 рабочих дней или согласованного срока: неустойка 0,5 % от суммы возмещения за каждый день. Сумму считает код.","notes":["Срок восстановительного ремонта — не более 30 рабочих дней со дня, когда машину передали на станцию или страховщику для транспортировки, если со страховщиком не согласован более длинный срок.","За каждый день нарушения срока ремонта страховщик платит неустойку 0,5 % от суммы страхового возмещения, но не больше самой суммы возмещения. Отвечает страховщик, даже если затянула станция.","Неустойка выплачивается по заявлению, в котором указывается способ расчета: почтовый перевод или перечисление на счет с реквизитами. Последний день срока ремонта код считает сам по производственному календарю; согласованный более длинный срок можно указать отдельно.","Если ремонт не только затянули, но и сделали некачественно, это отдельное требование: заявление о несогласии страховщику, затем финансовому уполномоченному."],"basis":[{"lawId":"FZ40","number":"12"},{"lawId":"FZ40","number":"16.1"}],"reviewed":false,"file":"osago-tour-health"},
{"id":"osago-premium-refund","title":"Заявление о досрочном прекращении договора ОСАГО и возврате части страховой премии","category":"Претензии и уведомления","summary":"Продали машину или она погибла, а полис еще действует: заявление о досрочном прекращении договора и возврате премии за неистекший срок.","notes":["При досрочном прекращении договора ОСАГО в случаях, предусмотренных правилами обязательного страхования, страховщик возвращает часть премии — долю, предназначенную для страхового возмещения и приходящуюся на неистекший срок договора.","Основания досрочного прекращения перечислены в правилах ОСАГО, утвержденных Банком России: среди них замена собственника машины и ее гибель. Приложите подтверждение — договор купли-продажи, документы о снятии с учета.","Если страховщик нарушил срок возврата, он платит страхователю-гражданину неустойку 1 % от суммы к возврату за каждый день просрочки, но не больше самой суммы (пункт 4 статьи 16.1 закона).","Точную сумму возврата рассчитывает страховщик. Если она кажется заниженной, попросите расчет."],"basis":[{"lawId":"FZ40","number":"10"},{"lawId":"FZ40","number":"16.1"}],"reviewed":false,"file":"osago-tour-health"},
{"id":"tour-operator-security-claim","title":"Требование о выплате по финансовому обеспечению ответственности туроператора","category":"Претензии и уведомления","summary":"Туроператор прекратил деятельность и не исполнил договор: требование к его страховщику или банку-гаранту о возмещении реального ущерба.","notes":["Ответственность туроператора обеспечивается договором страхования или банковской гарантией. Когда туроператор публично объявил о прекращении деятельности из-за невозможности исполнить обязательства, турист вправе потребовать возмещения реального ущерба прямо у страховщика или гаранта.","Реквизиты финансового обеспечения указаны в договоре о туре и в реестре туроператоров на сайте Ростуризма. Выплата производится в пределах размера финансового обеспечения.","Закон перечисляет обязательные сведения требования и приложения: копию паспорта, копию договора о туре, документы, подтверждающие реальный ущерб. Гаранту нужен также документ об отказе туроператора возместить ущерб или решение суда.","Если денег страховщика или гаранта не хватит, остаток возмещается из фонда персональной ответственности туроператора, если фонд не достиг максимального размера."],"basis":[{"lawId":"FZ132","number":"17.4"},{"lawId":"FZ132","number":"17.5"},{"lawId":"FZ132","number":"10"}],"reviewed":false,"file":"osago-tour-health"},
{"id":"clinic-choice-application","title":"Заявление о выборе медицинской организации (прикреплении к поликлинике)","category":"Претензии и уведомления","summary":"Хотите лечиться в другой поликлинике по ОМС — ближе к работе или с лучшими врачами: заявление о прикреплении на имя главного врача выбранной поликлиники.","notes":["Для первичной медико-санитарной помощи гражданин выбирает медицинскую организацию, в том числе по территориально-участковому принципу, не чаще одного раза в год. Исключение — переезд: тогда выбрать можно в любое время.","В выбранной поликлинике можно выбрать терапевта, педиатра, врача общей практики или фельдшера — с учетом согласия врача.","Заявление подается лично или через представителя в выбранную поликлинику. Возьмите паспорт, полис ОМС и СНИЛС. За ребенка заявление подает родитель.","Порядок выбора медицинской организации утвержден Минздравом России. Поликлиника сама уведомляет прежнюю организацию и страховую компанию."],"basis":[{"lawId":"FZ323","number":"21"},{"lawId":"FZ323","number":"19"}],"reviewed":false,"file":"osago-tour-health"},
{"id":"medical-harm-claim","title":"Претензия о возмещении вреда здоровью, причиненного при оказании медицинской помощи","category":"Претензии и уведомления","summary":"Ошибка врача, осложнение по вине больницы, неправильный диагноз: требование возместить расходы на лечение, утраченный заработок и моральный вред — и по ОМС, и в платной клинике.","notes":["Медицинские организации отвечают за причинение вреда жизни и здоровью при оказании медицинской помощи; вред возмещает сама организация, в том числе за действия своих врачей. Это касается и бесплатной помощи по ОМС.","Возмещаются утраченный заработок и дополнительные расходы, вызванные повреждением здоровья: на лечение, лекарства, уход, реабилитацию, если пострадавший не может получить их бесплатно. Отдельно взыскивается компенсация морального вреда.","Доказательства: медицинские документы (запросите копии), заключения других врачей, результаты экспертизы качества медицинской помощи. В суде обычно назначается судебно-медицинская экспертиза.","Параллельно можно обратиться в страховую медицинскую организацию за экспертизой качества помощи по ОМС и в Росздравнадзор."],"basis":[{"lawId":"FZ323","number":"98"},{"lawId":"GK","number":"1064"},{"lawId":"GK","number":"1068"},{"lawId":"GK","number":"1085"},{"lawId":"GK","number":"151"},{"lawId":"GK","number":"1101"}],"reviewed":false,"file":"osago-tour-health"},
{"id":"fin-org-claim","title":"Заявление в финансовую организацию о восстановлении нарушенного права","category":"Претензии и уведомления","summary":"Обязательный первый шаг перед финансовым уполномоченным: требование к банку, страховщику или МФО вернуть деньги или исполнить договор.","notes":["До обращения к финансовому уполномоченному нужно направить в финансовую организацию заявление о восстановлении нарушенного права — письменно или электронно. Без него уполномоченный обращение не примет.","Если закон или договор требуют сначала подать заявление об исполнении обязательства (например, о страховой выплате), это заявление подается только после ответа на него или после истечения срока его рассмотрения.","Организация отвечает в течение 30 календарных дней, а на заявление по стандартной электронной форме, поданное не позднее 180 дней после нарушения, — в течение 15 рабочих дней. После ответа или по истечении срока можно обращаться к уполномоченному.","Уполномоченный рассматривает требования о взыскании до 500 000 ₽ (по ОСАГО — без этого предела), если с момента, когда вы узнали о нарушении, прошло не больше трех лет."],"basis":[{"lawId":"FZ123","number":"16"},{"lawId":"FZ123","number":"15"}],"reviewed":false,"file":"fin-ombudsman"},
{"id":"fin-ombudsman-appeal","title":"Обращение к финансовому уполномоченному","category":"Претензии и уведомления","summary":"Банк, МФО, страховщик или ломбард не выполнили требование: обращение к финансовому уполномоченному — обязательный досудебный этап для споров до 500 000 ₽.","notes":["Обращение подается после заявления в финансовую организацию: когда получен ответ или истек срок его рассмотрения. Подать можно через личный кабинет на сайте финансового уполномоченного, через Госуслуги, почтой или через МФЦ, заключивший соглашение со службой уполномоченного. Для потребителя рассмотрение бесплатно.","Закон перечисляет обязательные сведения обращения: ФИО, дату и место рождения, место жительства, почтовый адрес и контакты, сведения о финансовой организации, существо спора и размер требования, номер и дату договора, сведения о заявлении в организацию и ее ответе. Шаблон собирает их все.","К обращению прикладываются копии заявления в организацию и ее ответа, договора и других документов по спору.","Решение вступает в силу через 10 рабочих дней после подписания. Если не согласны, в течение 30 календарных дней после вступления решения в силу можно подать иск в суд."],"basis":[{"lawId":"FZ123","number":"15"},{"lawId":"FZ123","number":"16"},{"lawId":"FZ123","number":"17"},{"lawId":"FZ123","number":"25"}],"reviewed":false,"file":"fin-ombudsman"},
{"id":"fin-ombudsman-osago-appeal","title":"Обращение к финансовому уполномоченному по спору об ОСАГО","category":"Претензии и уведомления","summary":"Страховая не доплатила, не организовала ремонт или не заплатила неустойку и отказала на претензию: обращение к финансовому уполномоченному перед иском.","notes":["Потерпевший-гражданин, не согласный с выплатой по ОСАГО, сначала направляет страховщику письменное заявление (претензию), а затем обращается к финансовому уполномоченному. Только после его решения можно идти в суд.","Требования из нарушения страховщиком порядка страхового возмещения по ОСАГО уполномоченный рассматривает без предела в 500 000 ₽.","Закон перечисляет обязательные сведения обращения: ФИО, дату и место рождения, место жительства, почтовый адрес и контакты, сведения о финансовой организации, существо спора и размер требования, номер и дату договора, сведения о заявлении в организацию и ее ответе. Шаблон собирает их все.","К обращению прикладываются копии заявления в организацию и ее ответа, договора и других документов по спору.","Решение вступает в силу через 10 рабочих дней после подписания. Если не согласны, в течение 30 календарных дней после вступления решения в силу можно подать иск в суд."],"basis":[{"lawId":"FZ123","number":"15"},{"lawId":"FZ123","number":"16"},{"lawId":"FZ123","number":"17"},{"lawId":"FZ40","number":"16.1"},{"lawId":"FZ40","number":"12"}],"reviewed":false,"file":"fin-ombudsman"},
{"id":"fin-ombudsman-certificate","title":"Заявление о выдаче удостоверения финансового уполномоченного","category":"Претензии и уведомления","summary":"Финансовая организация не исполнила решение уполномоченного: заявление о выдаче удостоверения для банка или о направлении его приставам. Срок — три месяца.","notes":["Решение финансового уполномоченного вступает в силу через 10 рабочих дней после подписания и исполняется в срок, указанный в решении. Если организация его не исполнила, уполномоченный по заявлению потребителя выдает удостоверение — исполнительный документ.","Удостоверение можно получить для предъявления в банк, где у организации счет, или попросить уполномоченного направить его в ФССП в электронной форме.","Заявление подается в течение трех месяцев с даты, когда решение должно было быть исполнено. Пропущенный по уважительной причине срок уполномоченный может восстановить по ходатайству — его можно включить в это же заявление.","Удостоверение выдается в срок не более 30 календарных дней со дня получения заявления."],"basis":[{"lawId":"FZ123","number":"23"}],"reviewed":false,"file":"fin-ombudsman"},
{"id":"fin-ombudsman-disagreement-suit","title":"Исковое заявление к финансовой организации при несогласии с решением финансового уполномоченного","category":"Суд","summary":"Уполномоченный отказал или удовлетворил требования частично: иск к банку, страховщику или МФО в течение 30 дней после вступления решения в силу. Потребитель пошлину не платит при цене иска до 1 млн ₽.","notes":["Потребитель, не согласный с вступившим в силу решением финансового уполномоченного, вправе в течение 30 календарных дней после вступления решения в силу обратиться в суд с требованиями к финансовой организации. Решение вступает в силу через 10 рабочих дней после подписания — код считает эту дату по производственному календарю.","Подтверждением досудебного порядка служит решение уполномоченного, неисполненное соглашение или уведомление о принятии (отказе в принятии) обращения. Копию иска нужно направить и финансовому уполномоченному.","Иск о защите прав потребителя подается по выбору истца: по месту нахождения организации, по своему месту жительства или пребывания, по месту заключения или исполнения договора. Потребитель освобожден от пошлины, если цена иска не больше 1 000 000 ₽.","Ответчик — финансовая организация, а не уполномоченный: иск заявляется по предмету, который был в обращении."],"basis":[{"lawId":"FZ123","number":"25"},{"lawId":"FZ123","number":"23"},{"lawId":"ZOZPP","number":"17"},{"lawId":"NK","number":"333.36"},{"lawId":"GPK","number":"131"},{"lawId":"GPK","number":"132"}],"reviewed":false,"file":"fin-ombudsman"},
{"id":"prosecutor-complaint","title":"Жалоба в прокуратуру","category":"Претензии и уведомления","summary":"Чиновник, управляющая компания, работодатель или другая организация нарушает закон: жалоба прокурору с просьбой провести проверку и принять меры.","notes":["Прокуратура разрешает заявления и жалобы о нарушении законов органами власти, органами местного самоуправления, руководителями коммерческих и некоммерческих организаций. Прокурор проверяет сведения, разъясняет порядок защиты прав и принимает меры: вносит представление, возбуждает дело об административном правонарушении, направляет материалы для уголовного преследования.","Прокуратура не подменяет другие органы: если вопрос входит в компетенцию инспекции или надзора (трудовой, жилищной, Роспотребнадзора), разумно сначала обратиться туда, а в прокуратуру — если они бездействуют.","Жалобу запрещено пересылать в орган или должностному лицу, на чьи решения или действия она подана. Письменное обращение рассматривается в течение 30 дней со дня регистрации; срок может быть продлен еще не более чем на 30 дней с уведомлением заявителя.","Ответ прокурора должен быть мотивированным; при отказе разъясняется порядок обжалования. Решение прокурора не мешает обратиться в суд."],"basis":[{"lawId":"PROK","number":"10"},{"lawId":"PROK","number":"21"},{"lawId":"PROK","number":"27"},{"lawId":"FZ59","number":"7"},{"lawId":"FZ59","number":"12"}],"reviewed":false,"file":"appeals"},
{"id":"state-body-appeal","title":"Обращение в государственный орган или орган местного самоуправления","category":"Претензии и уведомления","summary":"Заявление, жалоба или предложение в министерство, инспекцию, администрацию или депутату: обращение с обязательными реквизитами и ссылкой на 30-дневный срок ответа.","notes":["В письменном обращении обязательно указываются наименование органа или ФИО (должность) должностного лица, ваши ФИО и почтовый адрес для ответа, суть предложения, заявления или жалобы, подпись и дата. Шаблон собирает все эти реквизиты.","Обращение направляется в тот орган, к компетенции которого относится вопрос. Если адресат выбран неверно, обращение в течение семи дней со дня регистрации переадресуется с уведомлением заявителя.","Письменное обращение регистрируется в течение трех дней и рассматривается в течение 30 дней со дня регистрации. В исключительных случаях срок продлевается не более чем на 30 дней с уведомлением.","Заявитель вправе представлять дополнительные документы, знакомиться с материалами рассмотрения и получить письменный ответ по существу. Нарушение порядка рассмотрения обращений — административное правонарушение (статья 5.59 КоАП)."],"basis":[{"lawId":"FZ59","number":"4"},{"lawId":"FZ59","number":"5"},{"lawId":"FZ59","number":"7"},{"lawId":"FZ59","number":"8"},{"lawId":"FZ59","number":"12"}],"reviewed":false,"file":"appeals"},
{"id":"appeal-deadline-complaint","title":"Жалоба на нарушение срока рассмотрения обращения","category":"Претензии и уведомления","summary":"Госорган или администрация не ответили на обращение за 30 дней: жалоба руководителю или в прокуратуру с просьбой обязать ответить и привлечь виновных к ответственности.","notes":["Письменное обращение рассматривается в течение 30 дней со дня регистрации, а регистрируется в течение трех дней с поступления. Продлить срок можно только в исключительных случаях и не больше чем на 30 дней — с уведомлением заявителя.","Гражданин вправе обжаловать решение или действие (бездействие) по его обращению вышестоящему органу или должностному лицу либо в суд.","Нарушение порядка рассмотрения обращений граждан — административное правонарушение (статья 5.59 КоАП). Дела по этой статье возбуждает прокурор, поэтому жалобу на молчание органа удобно направить в прокуратуру.","Приложите копию обращения и доказательство его отправки или регистрации: отметку о приеме, почтовую квитанцию, номер регистрации с сайта."],"basis":[{"lawId":"FZ59","number":"12"},{"lawId":"FZ59","number":"5"},{"lawId":"FZ59","number":"10"},{"lawId":"KOAP","number":"5.59"},{"lawId":"PROK","number":"10"}],"reviewed":false,"file":"appeals"},
{"id":"prosecutor-lawsuit-request","title":"Заявление прокурору об обращении в суд в защиту прав гражданина","category":"Претензии и уведомления","summary":"Пожилой или больной человек не может судиться сам, либо нарушены трудовые, жилищные, социальные права: просьба к прокурору подать иск в его защиту.","notes":["Прокурор вправе подать иск в защиту гражданина, если тот по состоянию здоровья, возрасту, недееспособности или по другим уважительным причинам не может обратиться в суд сам.","Без этого ограничения прокурор может обратиться в суд по заявлению гражданина о защите социальных прав: в трудовых отношениях, защите семьи, материнства и детства, социальном обеспечении, праве на жилье в государственном и муниципальном фонде, охране здоровья, благоприятной окружающей среде и образовании.","Решение о подаче иска принимает прокурор. Если он откажет, вы сохраняете право обратиться в суд самостоятельно; прокурор не платит судебные расходы и не может заключить мировое соглашение.","Приложите документы, подтверждающие нарушение и причину, по которой вы не можете судиться сами: справку о состоянии здоровья, пенсионное удостоверение, документы о трудовом споре."],"basis":[{"lawId":"GPK","number":"45"},{"lawId":"PROK","number":"27"},{"lawId":"PROK","number":"10"}],"reviewed":false,"file":"appeals"},
{"id":"personal-reception-request","title":"Заявление о записи на личный прием к руководителю","category":"Претензии и уведомления","summary":"Хотите лично поговорить с главой администрации, министром, прокурором или руководителем инспекции: заявление о записи на прием с темой вопроса.","notes":["Личный прием граждан проводят руководители органов и уполномоченные лица. Дни, часы и место приема доводятся до сведения граждан — обычно они опубликованы на сайте органа.","На прием нужно взять паспорт. Содержание устного обращения заносится в карточку приема; если вопрос очевиден, ответ с вашего согласия может быть дан устно, в остальных случаях — письменно.","Письменное обращение, переданное на приеме, регистрируется и рассматривается в обычном порядке — 30 дней.","Укажите тему коротко и приложите документы: так вопрос подготовят к приему, а при необходимости переадресуют в компетентный орган."],"basis":[{"lawId":"FZ59","number":"13"},{"lawId":"FZ59","number":"5"}],"reviewed":false,"file":"appeals"},
{"id":"roszdravnadzor-complaint","title":"Жалоба в Росздравнадзор на качество медицинской помощи","category":"Претензии и уведомления","summary":"Отказали в помощи, лечили с нарушениями, нарушили права пациента: жалоба в территориальный орган Росздравнадзора с просьбой провести проверку клиники или больницы.","notes":["Федеральный государственный контроль качества и безопасности медицинской деятельности ведет Росздравнадзор. Предмет контроля — соблюдение медицинскими организациями и врачами обязательных требований, в том числе прав граждан в сфере охраны здоровья, порядков оказания медицинской помощи и стандартов.","По итогам контроля орган выдает обязательные для исполнения предписания и привлекает медицинские организации и должностных лиц к ответственности. Взыскать деньги или компенсацию вреда Росздравнадзор не может — для этого нужна претензия в клинику и иск.","Жалоба подается в территориальный орган Росздравнадзора по региону, где находится медицинская организация, письменно или через сайт. Письменное обращение рассматривается в течение 30 дней со дня регистрации.","Опишите конкретно: дату, отделение, врача, что было сделано или не сделано. Приложите медицинские документы, их можно запросить отдельным запросом."],"basis":[{"lawId":"FZ323","number":"87"},{"lawId":"FZ323","number":"86"},{"lawId":"FZ323","number":"19"},{"lawId":"FZ59","number":"12"}],"reviewed":false,"file":"appeals"},
{"id":"loan-insurance-refusal","title":"Заявление об исключении из числа застрахованных лиц (отказ от страховки по кредиту)","category":"Претензии и уведомления","summary":"Банк подключил к коллективной страховке при кредите: в течение 30 дней можно отказаться и вернуть всю плату за страхование за 7 рабочих дней.","notes":["Если при выдаче кредита банк сделал вас застрахованным лицом по договору личного страхования, где страхователь — сам банк или лицо, действующее в его интересах, вы вправе в течение 30 календарных дней со дня согласия на услугу подать заявление об исключении из числа застрахованных.","Банк или лицо, действующее в его интересах, обязаны вернуть все уплаченные за эту услугу деньги, включая страховую премию, в полном объеме в срок не более семи рабочих дней со дня получения заявления. Это правило действует, только если не было событий с признаками страхового случая.","Если вы сами заключили договор страхования со страховщиком, порядок отказа другой — он зависит от условий страхования и указаний Банка России.","После отказа банк вправе изменить ставку по кредиту, если в договоре предусмотрена более высокая ставка без страхования. Подайте заявление с отметкой о получении или заказным письмом и сохраните доказательства."],"basis":[{"lawId":"FZ353","number":"7"}],"reviewed":false,"file":"credit-collectors"},
{"id":"loan-extra-service-refusal","title":"Отказ от дополнительной услуги, навязанной при кредите","category":"Претензии и уведомления","summary":"К кредиту продали «юридическую поддержку», карту помощи на дорогах или сертификат: отказ в течение 30 дней и возврат денег, а если продавец не вернул — требование к банку.","notes":["Если при кредите за отдельную плату предложены дополнительные услуги, работы или товары, информация о которых указана в заявлении о предоставлении кредита, заемщик вправе отказаться от них в течение 30 календарных дней, обратившись к лицу, которое их оказывает.","Это лицо обязано вернуть деньги за вычетом стоимости фактически оказанной части услуги в срок не более семи рабочих дней со дня получения заявления об отказе.","Если услугу оказывает третье лицо и оно деньги не вернуло, заемщик вправе потребовать возврата от кредитора, указав дату своего обращения к третьему лицу. Кредитор возвращает деньги или мотивированно отказывает в течение семи рабочих дней.","Шаблон собирает оба документа: сначала заявление продавцу услуги, а если он не вернул деньги — требование к банку."],"basis":[{"lawId":"FZ353","number":"7"}],"reviewed":false,"file":"credit-collectors"},
{"id":"loan-early-repayment-notice","title":"Уведомление о досрочном возврате потребительского кредита (займа)","category":"Претензии и уведомления","summary":"Хотите погасить кредит раньше полностью или частично: уведомление кредитору не позднее чем за 30 дней (или в срок по договору) и просьба пересчитать проценты и график.","notes":["Заемщик вправе досрочно вернуть весь кредит или его часть, уведомив кредитора способом, установленным договором, не менее чем за 30 календарных дней до дня возврата, если договором не установлен более короткий срок.","В течение 14 календарных дней с даты получения кредита (по целевому кредиту — 30 дней) вернуть деньги можно без предварительного уведомления, уплатив проценты только за фактический срок пользования.","При досрочном возврате проценты уплачиваются за фактический срок кредитования. После частичного возврата попросите новый график платежей: уменьшение срока или размера платежа.","Многие банки принимают уведомление в приложении или в отделении — проверьте, какой способ указан в договоре. Этот текст пригодится, если нужен письменный документ."],"basis":[{"lawId":"FZ353","number":"11"}],"reviewed":false,"file":"credit-collectors"},
{"id":"collector-interaction-refusal","title":"Заявление кредитору или коллектору об отказе от взаимодействия","category":"Претензии и уведомления","summary":"Звонят и пишут из-за просроченного долга: отказ от звонков, встреч и сообщений (не раньше чем через 4 месяца просрочки) или общение только через адвоката.","notes":["Должник вправе заявить кредитору и (или) его представителю (коллектору) об отказе от взаимодействия либо о взаимодействии только через представителя — им может быть только адвокат.","Отказ от взаимодействия можно направить не ранее чем через четыре месяца с даты возникновения просрочки; поданный раньше отказ недействителен. Через три рабочих дня после получения отказа кредитор и коллектор не вправе по своей инициативе звонить, встречаться и писать сообщения. После решения суда или исполнительной надписи о взыскании действие отказа приостанавливается на два месяца.","Заявление направляется через нотариуса, заказным письмом, по электронной почте, указанной на сайте кредитора или в договоре, либо вручается под расписку. Форму заявления утверждает уполномоченный орган — сверьтесь с ней перед отправкой.","Отказ от взаимодействия не отменяет долг: кредитор может взыскивать его через суд, а письма по почте продолжат приходить."],"basis":[{"lawId":"FZ230","number":"8"},{"lawId":"FZ230","number":"4"},{"lawId":"FZ230","number":"7"}],"reviewed":false,"file":"credit-collectors"},
{"id":"collector-complaint","title":"Жалоба на действия коллектора или кредитора при взыскании долга","category":"Претензии и уведомления","summary":"Звонят ночью, по десять раз в день, угрожают, рассказывают о долге соседям: жалоба в ФССП России с просьбой проверить коллектора и привлечь к ответственности.","notes":["Кредитор и коллектор обязаны действовать добросовестно и разумно. Не допускаются угрозы и применение силы, повреждение имущества, психологическое давление, введение в заблуждение о размере долга и последствиях неуплаты, звонки в ночное время, превышение лимитов звонков и встреч.","Типичные нарушения, которые стоит описать: звонки чаще одного раза в сутки, двух раз в неделю или восьми раз в месяц; звонки и встречи в рабочие дни с 22 до 8 часов, в выходные и праздники с 20 до 9 часов; угрозы, давление, оскорбления, введение в заблуждение; сообщение сведений о долге третьим лицам: родственникам, соседям, работодателю; взаимодействие после отказа от взаимодействия.","Контроль за профессиональными коллекторскими организациями и за соблюдением закона при взыскании долгов ведет ФССП России: жалобу направляют в территориальный орган ФССП по месту жительства, через сайт или почтой. Если коллектор угрожает жизни или имуществу, сразу обращайтесь в полицию.","Доказательства решают все: детализация звонков, записи разговоров, скриншоты сообщений, показания соседей. Письменная жалоба рассматривается в течение 30 дней со дня регистрации."],"basis":[{"lawId":"FZ230","number":"6"},{"lawId":"FZ230","number":"7"},{"lawId":"FZ230","number":"8"},{"lawId":"FZ59","number":"12"}],"reviewed":false,"file":"credit-collectors"},
{"id":"credit-holiday-request","title":"Требование о предоставлении льготного периода по потребительскому кредиту (кредитные каникулы)","category":"Претензии и уведомления","summary":"Доход упал больше чем на 30 % или жилье пострадало от ЧС: требование к банку или МФО приостановить платежи по кредиту или займу на срок до 6 месяцев.","notes":["Заемщик по потребительскому кредиту или займу вправе потребовать льготный период — приостановку платежей — если находится в трудной жизненной ситуации: среднемесячный доход за два месяца до обращения снизился более чем на 30 % по сравнению со средним за 12 месяцев, или жилье оказалось в зоне чрезвычайной ситуации с утратой имущества.","Размер кредита не должен превышать максимум, установленный Правительством; условия договора не должны были ранее меняться по такому же требованию; не должно быть решения суда о взыскании или о банкротстве. При ЧС требование подается в течение 60 дней со дня установления фактов.","Длительность — не больше шести месяцев, начало — не раньше чем за месяц до обращения, а по кредитной карте — не раньше дня обращения. Если срок и дату не указать, каникулы считаются шестимесячными с даты требования.","Если есть поручитель или залогодатель — третье лицо, к требованию прикладывается его согласие. Документы о снижении дохода (справки о доходах, выписки) стоит приложить сразу."],"basis":[{"lawId":"FZ353","number":"6.1-2"}],"reviewed":false,"file":"credit-collectors"},
{"id":"pd-info-request","title":"Запрос оператору о предоставлении сведений об обработке персональных данных","category":"Претензии и уведомления","summary":"Хотите узнать, какие ваши данные хранит магазин, банк или сервис, откуда их взяли и кому передают: запрос с ответом в течение 10 рабочих дней.","notes":["Субъект персональных данных вправе получить сведения об их обработке: подтверждение факта обработки, правовые основания и цели, какие данные обрабатываются и откуда получены, сроки хранения, кому данные раскрываются и кто обрабатывает их по поручению оператора.","Запрос должен содержать номер документа, удостоверяющего личность, дату его выдачи и выдавший орган, сведения, подтверждающие отношения с оператором (номер договора, карты, аккаунта), и подпись. Без них оператор вправе не отвечать по существу.","Оператор отвечает в течение 10 рабочих дней; срок может быть продлен не более чем на 5 рабочих дней с мотивированным уведомлением. Отказ должен быть мотивированным, со ссылкой на основание в законе.","Если ответа нет или он неполный, можно обратиться в Роскомнадзор или в суд."],"basis":[{"lawId":"FZ152","number":"14"},{"lawId":"FZ152","number":"20"}],"reviewed":false,"file":"personal-data"},
{"id":"pd-consent-withdrawal","title":"Отзыв согласия на обработку персональных данных","category":"Претензии и уведомления","summary":"Надоела рассылка, звонки или не хотите, чтобы сервис хранил ваши данные: отзыв согласия с требованием прекратить обработку и уничтожить данные в течение 30 дней.","notes":["Согласие на обработку персональных данных можно отозвать в любой момент. После отзыва оператор обязан прекратить обработку и, если хранить данные больше не нужно для целей обработки, уничтожить их в срок не более 30 дней с даты поступления отзыва.","Оператор вправе продолжить обработку без согласия, если для этого есть другое законное основание: например, исполнение договора, стороной которого вы являетесь, или обязанность хранить данные по закону. Тогда он должен это объяснить.","Отзыв согласия не расторгает договор. Если нужно прекратить пользоваться услугой, это отдельное заявление.","Отправьте отзыв способом, по которому можно подтвердить получение: заказным письмом, через личный кабинет с сохранением ответа, вручением под отметку."],"basis":[{"lawId":"FZ152","number":"9"},{"lawId":"FZ152","number":"21"}],"reviewed":false,"file":"personal-data"},
{"id":"pd-correction-demand","title":"Требование уточнить, заблокировать или уничтожить персональные данные","category":"Претензии и уведомления","summary":"В базе неверный телефон или адрес, долг чужого человека «висит» на вас, данные получены без согласия: требование исправить или уничтожить данные с блокировкой на время проверки.","notes":["Субъект вправе требовать от оператора уточнения, блокирования или уничтожения персональных данных, если они неполные, устаревшие, неточные, незаконно получены или не нужны для заявленной цели.","Получив обращение о неточных или неправомерно обрабатываемых данных, оператор обязан заблокировать их на период проверки. Неточные данные уточняются в течение семи рабочих дней после представления подтверждающих сведений.","Неправомерную обработку оператор прекращает не позднее трех рабочих дней с даты выявления, а если сделать ее правомерной нельзя — уничтожает данные в течение десяти рабочих дней и уведомляет об этом.","Приложите документы, подтверждающие правильные сведения: копию паспорта, свидетельство о смене фамилии, документ о регистрации по месту жительства."],"basis":[{"lawId":"FZ152","number":"14"},{"lawId":"FZ152","number":"21"}],"reviewed":false,"file":"personal-data"},
{"id":"pd-rkn-complaint","title":"Жалоба в Роскомнадзор на нарушение при обработке персональных данных","category":"Претензии и уведомления","summary":"Оператор не ответил на запрос, продолжает рассылку после отзыва согласия, передал данные без разрешения или допустил утечку: жалоба в Роскомнадзор с просьбой провести проверку.","notes":["Если оператор обрабатывает персональные данные с нарушением закона или иным образом нарушает права, его действия можно обжаловать в уполномоченный орган по защите прав субъектов персональных данных — Роскомнадзор — или в суд.","Уполномоченный орган рассматривает обращения о соответствии содержания и способов обработки данных целям обработки, вправе запрашивать у оператора информацию и требовать уточнения, блокирования или уничтожения недостоверных или незаконно полученных данных.","Взыскать убытки и компенсацию морального вреда можно только через суд — для этого нужен отдельный иск.","Жалобу удобно подать на сайте Роскомнадзора или в территориальное управление по месту жительства. Приложите свой запрос или отзыв согласия оператору, его ответ (или доказательства, что ответа нет), скриншоты рассылок, записи звонков."],"basis":[{"lawId":"FZ152","number":"17"},{"lawId":"FZ152","number":"23"},{"lawId":"FZ59","number":"12"}],"reviewed":false,"file":"personal-data"},
{"id":"mortgage-holiday-request","title":"Требование о предоставлении льготного периода по ипотеке (ипотечные каникулы)","category":"Претензии и уведомления","summary":"Потеряли работу, заболели, доход упал или родился второй ребенок: требование к банку приостановить или уменьшить платежи по ипотеке на срок до 6 месяцев (при рождении ребенка — до 18).","notes":["Заемщик по ипотеке на единственное жилье вправе потребовать льготный период при особых обстоятельствах: безработица, инвалидность I или II группы, больничный более двух месяцев, снижение дохода более чем на 30 %, рост числа иждивенцев со снижением дохода более чем на 20 %, чрезвычайная ситуация, рождение или усыновление второго и следующего ребенка.","Размер кредита не должен превышать максимум, установленный Правительством, а условия договора не должны были ранее меняться по такому же требованию (кроме случаев, указанных в законе). Банкротство заемщика исключает каникулы.","Длительность и дату начала выбирает заемщик: начало — не ранее чем за два месяца до обращения, длительность — до 6 месяцев, а при рождении или усыновлении ребенка — до 18 месяцев. Если залогодатель — другое лицо, приложите его согласие.","Требование подается способом, указанным в договоре, заказным письмом с уведомлением о вручении или под расписку. Документы об особых обстоятельствах можно приложить сразу или позже."],"basis":[{"lawId":"FZ353","number":"6.1-1"}],"reviewed":false,"file":"personal-data"},
{"id":"salary-delay-claim","title":"Требование о выплате задержанной заработной платы и компенсации за задержку","category":"Трудовые отношения","summary":"Зарплату не выплатили в срок: требование к работодателю выплатить долг и проценты по статье 236 ТК — 1/150 ключевой ставки за каждый день.","notes":["Зарплата выплачивается не реже чем каждые полмесяца, в день, установленный правилами внутреннего трудового распорядка, коллективным или трудовым договором.","За каждый день задержки работодатель обязан выплатить компенсацию не ниже 1/150 ключевой ставки Банка России от невыплаченной суммы — со дня, следующего за днём выплаты, по день фактического расчёта включительно. Обязанность не зависит от вины работодателя.","Шаблон считает компенсацию по одной ставке. Если ключевая ставка за время задержки менялась, посчитайте каждый период отдельно в калькуляторе процентов или поправьте сумму вручную.","Если задержка больше 15 дней, можно письменно известить работодателя и приостановить работу до выплаты — для этого есть отдельный шаблон."],"basis":[{"lawId":"TK","number":"136"},{"lawId":"TK","number":"236"},{"lawId":"TK","number":"142"}],"reviewed":false,"file":"labor-pay"},
{"id":"work-suspension-notice","title":"Уведомление о приостановлении работы в связи с задержкой заработной платы","category":"Трудовые отношения","summary":"Зарплату задерживают больше 15 дней: письменно известить работодателя и не выходить на работу до выплаты, сохраняя средний заработок.","notes":["Приостановить работу можно только при задержке больше 15 дней и только после письменного извещения работодателя. Вручите уведомление под отметку о получении или отправьте ценным письмом с описью.","Нельзя приостанавливать работу при военном или чрезвычайном положении, в армии и силовых структурах, на аварийно-спасательных работах, государственным служащим, на особо опасных производствах и тем, кто обеспечивает жизнедеятельность населения: энергию, тепло, воду, газ, связь, скорую помощь.","На время приостановления сохраняется средний заработок. Выйти на работу нужно не позднее следующего рабочего дня после письменного уведомления работодателя о готовности выплатить долг в день выхода."],"basis":[{"lawId":"TK","number":"142"},{"lawId":"TK","number":"236"}],"reviewed":false,"file":"labor-pay"},
{"id":"unpaid-leave","title":"Заявление о предоставлении отпуска без сохранения заработной платы","category":"Трудовые отношения","summary":"Отпуск за свой счёт: по соглашению с работодателем или в случаях, когда отказать нельзя — рождение ребенка, брак, смерть близкого, пенсионеру, инвалиду.","notes":["По семейным обстоятельствам и другим уважительным причинам отпуск без сохранения зарплаты дают по соглашению: его длительность согласуют работник и работодатель.","Обязательно по заявлению работника: при рождении ребенка, регистрации брака, смерти близких родственников — до 5 календарных дней; работающим пенсионерам по старости — до 14 дней в году; работающим инвалидам — до 60 дней в году. Есть и другие случаи в статье 128 ТК, например для участников Великой Отечественной войны и семей военнослужащих.","Приложите документ, который подтверждает основание: свидетельство о рождении или браке, справку об инвалидности."],"basis":[{"lawId":"TK","number":"128"}],"reviewed":false,"file":"labor-pay"},
{"id":"work-documents-request","title":"Заявление о выдаче документов, связанных с работой","category":"Трудовые отношения","summary":"Копии приказов, справки о зарплате и периоде работы, сведения о трудовой деятельности: работодатель выдает их бесплатно не позднее трех рабочих дней.","notes":["По письменному заявлению работодатель обязан не позднее трех рабочих дней выдать копии документов, связанных с работой, заверенные надлежащим образом, — бесплатно.","К таким документам относятся копии приказов о приеме, переводах и увольнении, выписка из трудовой книжки, справки о заработной плате, о страховых взносах, о периоде работы. Сведения о трудовой деятельности выдаются по правилам статьи 66.1 ТК.","Подайте заявление в двух экземплярах и попросите отметку о получении на своем — от этой даты считается срок."],"basis":[{"lawId":"TK","number":"62"},{"lawId":"TK","number":"66.1"}],"reviewed":false,"file":"labor-pay"},
{"id":"child-tax-deduction","title":"Заявление о предоставлении стандартного налогового вычета на детей","category":"Трудовые отношения","summary":"Вычет по НДФЛ на детей у работодателя: 1 400 ₽ на первого, 2 800 ₽ на второго, 6 000 ₽ на третьего и следующих, 12 000 ₽ на ребенка-инвалида — пока доход с начала года не превысит 450 000 ₽.","notes":["Вычет в месяц: 1 400 ₽ на первого ребенка, 2 800 ₽ на второго, 6 000 ₽ на третьего и каждого следующего, 12 000 ₽ на ребенка-инвалида до 18 лет или учащегося очно инвалида I или II группы до 24 лет.","Вычет дают на ребенка до 18 лет и на учащегося очной формы до 24 лет — до месяца, в котором доход с начала года превысил 450 000 ₽.","Единственному родителю вычет дают в двойном размере; также в двойном размере его может получать один из родителей, если второй отказался от вычета.","Работодатель может дать вычет без заявления, если у него уже есть сведения о детях. При первом получении вычета у этого работодателя приложите документы: свидетельства о рождении, справку об очном обучении, справку об инвалидности."],"basis":[{"lawId":"NK","number":"218"}],"reviewed":false,"file":"labor-pay"},
{"id":"dismissal-payment-demand","title":"Требование о выплате расчета при увольнении и компенсации за неиспользованный отпуск","category":"Трудовые отношения","summary":"При увольнении не выплатили зарплату или компенсацию за отпуск: требование рассчитаться — в день увольнения или на следующий день после требования.","notes":["Все суммы при увольнении выплачиваются в день увольнения. Если в этот день работник не работал — не позднее следующего дня после того, как он потребовал расчет.","При увольнении выплачивается денежная компенсация за все неиспользованные отпуска. Если о размере сумм спор, работодатель в тот же срок обязан выплатить сумму, которую не оспаривает.","За каждый день задержки положена компенсация не ниже 1/150 ключевой ставки (статья 236 ТК). Чтобы посчитать ее, воспользуйтесь шаблоном требования о выплате задержанной зарплаты."],"basis":[{"lawId":"TK","number":"140"},{"lawId":"TK","number":"127"},{"lawId":"TK","number":"236"}],"reviewed":false,"file":"labor-pay"},
{"id":"vacation-then-dismissal","title":"Заявление о предоставлении неиспользованного отпуска с последующим увольнением","category":"Трудовые отношения","summary":"Уйти в оставшийся отпуск и уволиться после него: днем увольнения считается последний день отпуска, отозвать заявление можно до начала отпуска.","notes":["По письменному заявлению неиспользованные отпуска могут быть предоставлены с последующим увольнением, кроме увольнения за виновные действия. Днем увольнения считается последний день отпуска.","Это право, а не обязанность работодателя: он может согласиться или выплатить компенсацию за отпуск при увольнении.","Если увольняетесь по собственному желанию, отозвать заявление можно до дня начала отпуска, если на ваше место не приглашен другой работник в порядке перевода.","Расчет и трудовую книжку (сведения о трудовой деятельности) выдают в последний рабочий день перед отпуском."],"basis":[{"lawId":"TK","number":"127"},{"lawId":"TK","number":"80"}],"reviewed":false,"file":"labor-pay"},
{"id":"leave-compensation-request","title":"Заявление о замене части отпуска денежной компенсацией","category":"Трудовые отношения","summary":"Получить деньги вместо дней отпуска сверх 28 календарных дней — например, дополнительного отпуска или перенесенных дней.","notes":["Денежной компенсацией по письменному заявлению можно заменить только часть отпуска, превышающую 28 календарных дней. При суммировании или переносе отпусков — часть каждого отпуска сверх 28 дней или любое количество дней из нее.","Нельзя заменять деньгами основной и дополнительные отпуска беременным и работникам до 18 лет, а также дополнительный отпуск за работу во вредных или опасных условиях.","Замена — право работодателя, а не обязанность: он может отказать."],"basis":[{"lawId":"TK","number":"126"}],"reviewed":false,"file":"labor-pay"},
{"id":"disabled-child-days","title":"Заявление о предоставлении дополнительных оплачиваемых выходных дней для ухода за ребенком-инвалидом","category":"Трудовые отношения","summary":"Четыре оплачиваемых выходных в месяц одному из родителей, а один раз в году — до 24 дней подряд. Оплата — по среднему заработку.","notes":["Одному из родителей (опекуну, попечителю) для ухода за ребенком-инвалидом по письменному заявлению предоставляются четыре дополнительных оплачиваемых выходных дня в месяц. Родители могут разделить их между собой.","Один раз в календарном году можно взять до 24 таких дней подряд в пределах неиспользованных дней этого года. График дней при использовании больше четырех подряд согласовывается с работодателем.","Каждый день оплачивается в размере среднего заработка. Приложите справку об инвалидности ребенка и справку с работы второго родителя о том, что он в этом месяце дни не использовал (или использовал не все)."],"basis":[{"lawId":"TK","number":"262"}],"reviewed":false,"file":"labor-pay"},
{"id":"part-time-request","title":"Заявление об установлении неполного рабочего времени","category":"Трудовые отношения","summary":"Неполный день или неполная неделя: по соглашению с работодателем, а беременной, родителю ребенка до 14 лет и тому, кто ухаживает за больным родственником, отказать нельзя.","notes":["Неполное рабочее время устанавливается по соглашению сторон — без ограничения срока или на согласованный срок. Оплата — пропорционально отработанному времени или выработке.","Работодатель обязан установить неполное время по просьбе беременной женщины, одного из родителей ребенка до 14 лет (ребенка-инвалида до 18 лет), а также того, кто ухаживает за больным членом семьи по медицинскому заключению. Режим устанавливается по пожеланию работника с учетом условий работы.","Решение работодатель принимает не позднее пяти рабочих дней с даты обращения. Изменение режима оформляется дополнительным соглашением к трудовому договору."],"basis":[{"lawId":"TK","number":"93"}],"reviewed":false,"file":"labor-pay"}
];
